const AI_GRADIENT_MUTED = 'linear-gradient(244.79deg, #9FC0FF 2.17%, #BBA9E9 103.16%)';
const CARD_SHADOW = '0px 2px 6px rgba(15,23,51,0.08)';
// The dataviz skill's validated categorical palette (light-mode steps only — book
