const PAGE_W = DEFAULT_PAGE_W;
const PAGE_MIN_H = DEFAULT_PAGE_H;
const PAGE_SHADOW = '0 1px 2px rgba(15,23,51,0.04), 0 10px 28px rgba(15,23,51,0.08)';
const ZOOM_OPTIONS = [50, 75, 90, 100, 125, 150];

/* A small curated stock library, standing in for the real contextual/Unsplash-style
   search Designrr's own live product has — mocked like every other network-backed
   feature in this prototype, but real enough to demonstrate "pick from a library"
   instead of always getting the same fixed placeholder. */
const STOCK_IMAGES: { label: string; src: string }[] = [
  // Real photos (bundled assets, not live hotlinks, matching the zero-network-
  // dependency convention) — replaced the placeholder pastel swatches these used
  // to be so the editor stops looking like a wireframe wherever imagery shows up
  // (cover backgrounds, image-grid cells, the stock-photo picker).
  { label: 'Minimalist desk (default)', src: '/assets/cover-default.jpg' },
  { label: 'Desk workspace', src: '/assets/stock-desk.jpg' },
  { label: 'Team meeting', src: '/assets/stock-team.jpg' },
  { label: 'City skyline', src: '/assets/stock-skyline.jpg' },
  { label: 'Nature trail', src: '/assets/stock-trail.jpg' },
  { label: 'Reading a book', src: '/assets/stock-reading.jpg' },
  { label: 'Data chart', src: '/assets/stock-chart.jpg' },
  { label: 'Smiling portrait', src: '/assets/stock-portrait.jpg' },
  { label: 'Vintage family photo', src: '/assets/stock-vintage.jpg' },
  { label: 'Canoe on a lake', src: '/assets/stock-canoe.jpg' },
];

/* Deterministic "generation" for the mocked AI image tool below — same idea as
   qrModules further down: no real model to call, so the prompt text is hashed
   into a pick from the existing stock library instead of always handing back
   the same placeholder regardless of what was typed. */
function seededPick<T>(items: T[], seed: string): T {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return items[h % items.length];
}

/* Photo generation is NOT metered — no per-tier allowance, no cost on the
   button, no balance under it. The mocked pool that used to live here (20/60/∞
   by tier, 10 a run) is in the history if it comes back.

   This is deliberately out of step with Wordgenie TEXT, which IS metered: the
   chat header counts drafts against the shared books+presentations pool via
   `combinedGenerationsUsed` / `manuscriptLimitFor` (flowStore). Two pools, two
   rules, on purpose — that pool meters whole MANUSCRIPT generations, which is a
   different resource from a photo dropped into a page, and folding images into
   it would make the book-generation gate mean something it doesn't. Anyone
   tidying this into one system later should start by asking the product which
   resource an image is, not by making the two surfaces match. */

/* ── shared editor services ──────────────────────────────────────────────────
   Three things every editing surface in this file needs, threaded by context
   rather than by prop chains six components deep: the user's own uploaded
   (and generated) images, and a registry of every live editor so
   find-and-replace can reach all of them at once. */

// `source` distinguishes a file upload from an AI generation — both used to be
// flattened into one `uploaded` flag, which was fine while PhotoSourcePanel
// searched them as a single pool. It now keeps Upload/My uploads/Wordgenie AI
// as separate sections (matching the real product's own Media panel), so it
// needs to tell them apart.
interface ImageLibraryEntry { label: string; src: string; source?: 'upload' | 'generated' }

interface UnsplashResult {
  id: string;
  thumbUrl: string;
  fullUrl: string;
  alt: string;
  // The photo's own proportions, carried through from the API so a tile can
  // hold its exact height before the image decodes.
  width: number;
  height: number;
  downloadLocation: string;
  credit: { name: string; profileUrl: string };
}

/* Why a search came back empty-handed, because the two cases need different
   words: a spent quota tells you to come back, anything else tells you the
   search itself is off. */
type UnsplashFailure = 'rate_limited' | 'unavailable';

interface UnsplashAnswer {
  status: 'error' | 'ok';
  results: UnsplashResult[];
  /* Everything the query matched, not the twenty on this page — the difference
     between "your wording is too narrow" and "the search is broken". */
  total: number;
  reason?: UnsplashFailure;
}

/* Answers already in hand, keyed by query — module-level, because the panel that
   asks for them unmounts every time the Photos tab loses its turn in the rail and
   a per-component cache would refetch the same six photos on every visit. Only
   successes are kept: a failed request is usually the Unsplash key or the
   network, and caching that would make one bad moment permanent for the session.
   Errors fall through to the curated STOCK_IMAGES grid instead. */
const unsplashCache = new Map<string, UnsplashAnswer>();
/* Requests already out. Two panels mounting on the same seed (the Photos tab and
   a Replace-image overlay) share one request, and — the reason this exists — a
   panel opening while the prefetch below is still in flight joins it rather than
   starting a second one 400ms later. */
const unsplashInFlight = new Map<string, Promise<UnsplashAnswer>>();

/* Behind the app's first API route (`/api/unsplash/search`) so the access key
   stays server-side. Deliberately not abortable: the one caller that cancels is a
   panel being unmounted, and throwing away a response that's already paid for is
   how the next mount ends up waiting for it all over again. */
/* Two searches for the same word in different shapes are two different answers,
   so they can't share a cache slot. No orientation keeps the bare query as the
   key, which is what lets the prefetch below and an unfiltered panel meet on the
   same entry instead of requesting it twice. */
function unsplashKey(q: string, orientation: string) {
  return orientation ? `${orientation}:${q}` : q;
}

function fetchUnsplash(q: string, orientation = ''): Promise<UnsplashAnswer> {
  const key = unsplashKey(q, orientation);
  const cached = unsplashCache.get(key);
  if (cached) return Promise.resolve(cached);
  const pending = unsplashInFlight.get(key);
  if (pending) return pending;
  const request: Promise<UnsplashAnswer> = fetch(`/api/unsplash/search?q=${encodeURIComponent(q)}${orientation ? `&orientation=${orientation}` : ''}`)
    .then(async (res) => {
      // 429 is the route's own signal for a spent Unsplash quota; everything
      // else that isn't a 2xx is the generic failure.
      if (!res.ok) {
        return { status: 'error' as const, results: [], total: 0, reason: (res.status === 429 ? 'rate_limited' : 'unavailable') as UnsplashFailure };
      }
      const data = await res.json();
      const value: UnsplashAnswer = { status: 'ok', results: (data.results ?? []) as UnsplashResult[], total: (data.total ?? 0) as number };
      unsplashCache.set(key, value);
      return value;
    })
    .catch(() => ({ status: 'error' as const, results: [], total: 0, reason: 'unavailable' as UnsplashFailure }))
    .finally(() => { unsplashInFlight.delete(key); });
  unsplashInFlight.set(key, request);
  return request;
}

/* Real Unsplash search. No key configured (or the request fails) -> 'error', and
   PhotoSourcePanel falls back to the curated STOCK_IMAGES grid rather than
   showing a dead end. */
function useUnsplashSearch(query: string, attempt = 0, orientation = '') {
  // Keyed by the request it answers, so render time (not the effect body) can
  // tell "idle" (no query) apart from "loading" (request changed, fetch not
  // back yet) without ever calling setState synchronously inside the effect.
  const [resolved, setResolved] = useState<(UnsplashAnswer & { key: string; attempt: number }) | null>(null);
  const q = query.trim();
  const key = unsplashKey(q, orientation);
  const cached = q ? unsplashCache.get(key) : undefined;

  useEffect(() => {
    if (!q || unsplashCache.has(key)) return;
    let cancelled = false;
    /* No debounce. Nothing types into this hook any more — the search box submits
       a finished query and the suggestion seed arrives whole — so a delay here
       would only be latency between clicking Search and seeing it happen.
       Coalescing two panels onto one request is fetchUnsplash's job regardless,
       via unsplashInFlight. */
    fetchUnsplash(q, orientation).then((value) => { if (!cancelled) setResolved({ key, attempt, ...value }); });
    return () => { cancelled = true; };
    /* `attempt` is Retry's whole mechanism. Failures are deliberately not cached,
       so asking again is enough to make a real request — but the query string
       hasn't changed, so without something else in the deps this effect would
       never run a second time. */
  }, [q, key, orientation, attempt]);

  const none: UnsplashResult[] = [];
  if (!q) return { status: 'idle' as const, results: none, total: 0, reason: undefined, stale: none };
  if (cached) return { status: cached.status, results: cached.results, total: cached.total, reason: cached.reason, stale: none };
  if (!resolved || resolved.key !== key || resolved.attempt !== attempt) {
    /* The answer this one is replacing, handed out for as long as it takes to
       replace it. The panel shows it dimmed rather than emptying the grid, and
       sourcing it here means nothing downstream has to keep its own copy of the
       last render — which is a ref read during render, the one thing this hook
       was shaped to avoid in the first place. */
    return { status: 'loading' as const, results: none, total: 0, reason: undefined, stale: resolved?.results ?? none };
  }
  return { status: resolved.status, results: resolved.results, total: resolved.total, reason: resolved.reason, stale: none };
}

/* A boolean that refuses to flicker. `on` has to hold for `delay` before this
   turns true, and once true it stays for at least `hold`.
   Both halves earn their place on this panel. A warm Unsplash search answers
   inside the band Nielsen calls "no feedback needed" (under a second), so a
   loading state that appears instantly is a flash of grey that makes a fast
   search feel worse than a silent one; the delay swallows it. And a skeleton
   that does appear, then vanishes two frames later, reads as a glitch rather
   than as progress — hence the floor. */
function useSettledFlag(on: boolean, delay = 200, hold = 300) {
  const [shown, setShown] = useState(false);
  const shownAt = useRef(0);
  useEffect(() => {
    if (on) {
      if (shown) return;
      const t = setTimeout(() => { shownAt.current = Date.now(); setShown(true); }, delay);
      return () => clearTimeout(t);
    }
    if (!shown) return;
    const remaining = hold - (Date.now() - shownAt.current);
    const t = setTimeout(() => setShown(false), Math.max(0, remaining));
    return () => clearTimeout(t);
  }, [on, shown, delay, hold]);
  return shown;
}

/* Warms Suggested as soon as the editor knows what the book is about, rather than
   when the Photos tab is first opened. Both halves matter: the JSON, and then the
   six thumbnails it names — the request itself came back fast enough, and what
   you actually watched fill in one by one was the images. Decoding them into the
   browser cache ahead of time is what makes the tab open populated.
   Fire-and-forget, and never awaited by anything: if it hasn't finished by the
   time you open the tab, the panel joins the same request through
   unsplashInFlight and shows its own loading line as before. */
function usePhotoSuggestPrefetch(seed: string) {
  useEffect(() => {
    const q = seed.trim();
    if (!q || unsplashCache.has(q) || unsplashInFlight.has(q)) return;
    let cancelled = false;
    fetchUnsplash(q).then((value) => {
      if (cancelled || typeof window === 'undefined') return;
      for (const r of value.results.slice(0, SUGGESTED_LIMIT)) {
        const img = new window.Image();
        img.src = r.thumbUrl;
      }
    });
    return () => { cancelled = true; };
  }, [seed]);
}

const ImageLibraryContext = createContext<{
  images: ImageLibraryEntry[];
  add: (label: string, src: string, source?: 'upload' | 'generated') => void;
}>({ images: STOCK_IMAGES, add: () => {} });

/* Suggested caps at the same six — two rows of the three-up grid. A suggestion
   you have to scroll to is not doing the job a suggestion exists to do, and the
   search box directly above it is the route to more. */
const SUGGESTED_LIMIT = 6;

/* What the Suggested section searches for when nobody has typed anything.
   Context rather than a prop because PhotoSourcePanel has five call sites
   (Replace image, cover element, opener photo, author photo, and the Photos tab
   itself) and none of the other four care about this.

   Before this, "Suggested" rendered the same ten bundled JPEGs for every user,
   every book and every topic — it did not suggest, it was a fixed shelf wearing a
   label it had not earned. The search half was always real
   (`/api/unsplash/search` behind a server-side key); only the zero-query state
   was invented. */
const PhotoSuggestContext = createContext<string>('');

/* How paragraphs are separated, book-wide. Two options, because there are only
   two real answers: the printed-book one (indent the first line, no space
   between) and the web one (space between, no indent). Using both at once is
   the classic beginner's tell — the indent and the blank line each do the same
   job, so together they say it twice — and using neither leaves the reader with
   no paragraph boundaries at all.

   Spaced is the default and what every book in this editor has been set in so
   far, so nothing already written reflows on upgrade. */
type ParagraphStyle = 'spaced' | 'indented';
/* Paragraph separation, both axes, as a PERCENTAGE OF THE TEXT SIZE.
   Not em, which appeared nowhere else in this editor — the unit vocabulary here
   is % (7 uses), px (5), ° (2) and inches (margins). Percent is the same
   relative measure em is, just the number times a hundred, so it keeps the
   property that made em right: the indent and the gap hold their proportion at
   whatever size a reading system renders the text, and EPUB has no fixed page
   to measure a physical unit against.
   Not inches either, which would have matched the margins next door — but those
   live in Page setup, the one leaf that never reaches EPUB, while these reach
   every format. A fixed-inch indent is a different indent on every device. */
const PARAGRAPH_INDENT_PCT = 150;
const INDENT_STEP = 25;
/* Never zero or below. Zero is the "No indent" tile above, and a NEGATIVE value
   would not give a hanging indent — the rule this feeds carries no matching
   padding-left, so the first line would hang off the left of the text block into
   the margin. A real hanging indent is the pair (padding-left: X;
   text-indent: -X) and it is a per-block style for bibliographies, glossaries
   and verse, not a book-wide body setting — where Atticus files it too. */
const INDENT_MIN = 50;
const INDENT_MAX = 400;
/* Zero is reachable on purpose. Indent and space were mutually exclusive here
   because using both says the same thing twice — but that is a convention, not
   a constraint, and enforcing it by hiding the control meant the printed-book
   setting (indent, no gap) could only be had by accepting whatever gap we had
   hardcoded. They are two independent axes now. 90% is what the old hardcoded
   14px worked out to at the 15.5px body size. */
const PARAGRAPH_SPACE_PCT = 90;
const SPACE_STEP = 25;
const SPACE_MIN = 0;
const SPACE_MAX = 200;

/* accentColor rides along so SwatchRow can offer the book's own accent without
   every inspector having to be handed the theme. It was the one colour a theme
   had already committed to and the one colour no palette in the editor offered. */
const EditorPrefsContext = createContext<{ paragraphStyle: ParagraphStyle; paragraphIndent: number; paragraphSpace: number; accentColor: string; chapterOpener: ChapterOpener }>({ paragraphStyle: 'spaced', paragraphIndent: PARAGRAPH_INDENT_PCT, paragraphSpace: PARAGRAPH_SPACE_PCT, accentColor: '#006EFE', chapterOpener: 'none' });

/* The live page box — trim size and margins, from Book settings. A context and
   not a prop because nearly every rendering surface in this file draws a page:
   the chapter canvas, the cover, the read-only Preview render, and four sizes
   of thumbnail. They have nothing else in common and most are several levels
   apart, so threading one more prop through all of them would touch far more
   code than it explains. Default is the shipped Letter page, which is what the
   surfaces OUTSIDE the provider want anyway — a template row's preview shows a
   design, not this book. */
const PageGeometryContext = createContext<PageGeometry>(DEFAULT_GEOMETRY);

/* Links to somewhere else in the same book.

   Standard equipment in book tools — Vellum and Atticus both have it — and the
   shape here is Vellum's, because it is the one that cannot produce a dead link:
   you PICK a destination chapter (and optionally a heading inside it) from a
   list, you never type an address. Atticus is the weaker version, where only a
   chapter title can be targeted and nothing inside one.

   The href carries the chapter's ID, not its title, so renaming a chapter cannot
   break a link pointing at it. Headings are addressed by their ORDER within the
   chapter rather than by their words, for the same reason — and because two
   headings in a chapter are allowed to read the same.

   NOT stripped for print. Vellum strips internal links on its print pass because
   Vellum produces a physical book; every format this product exports (PDF,
   flipbook, HTML, Kindle, EPUB) is read on a screen, and "see Chapter 4" is at
   its most useful in a PDF. */
const INTERNAL_LINK_PREFIX = '#ch-';
const INTERNAL_LINK_HEADING_SEP = '--h-';

function internalHref(chapterId: string, headingIndex?: number): string {
  return headingIndex == null
    ? `${INTERNAL_LINK_PREFIX}${chapterId}`
    : `${INTERNAL_LINK_PREFIX}${chapterId}${INTERNAL_LINK_HEADING_SEP}${headingIndex}`;
}

function parseInternalHref(href: string | undefined | null): { chapterId: string; headingIndex: number | null } | null {
  if (!href || !href.startsWith(INTERNAL_LINK_PREFIX)) return null;
  const rest = href.slice(INTERNAL_LINK_PREFIX.length);
  const at = rest.indexOf(INTERNAL_LINK_HEADING_SEP);
  if (at === -1) return { chapterId: rest, headingIndex: null };
  const idx = Number(rest.slice(at + INTERNAL_LINK_HEADING_SEP.length));
  return { chapterId: rest.slice(0, at), headingIndex: Number.isFinite(idx) ? idx : null };
}

interface LinkTargetHeading { index: number; text: string; level: number }
interface LinkTarget { chapterId: string; title: string; headings: LinkTargetHeading[] }

const BookLinkTargetsContext = createContext<{
  targets: LinkTarget[];
  /** Every href that currently resolves. A link whose href is absent is broken. */
  valid: Set<string>;
  goTo: (chapterId: string, headingIndex: number | null) => void;
}>({ targets: [], valid: new Set(), goTo: () => {} });


type RegisteredEditorKind = 'chapter' | 'field';
interface RegisteredEditor { key: string; editor: Editor; kind: RegisteredEditorKind }

const EditorRegistryContext = createContext<
  (key: string, editor: Editor, kind: RegisteredEditorKind) => () => void
>(() => () => {});

/* Registers an editor for the lifetime of the component that owns it. Kept as a
   hook so both ChapterEditor and SimpleFieldEditor opt in with one line. */
function useRegisterEditor(key: string, editor: Editor | null, kind: RegisteredEditorKind) {
  const register = useContext(EditorRegistryContext);
  useEffect(() => {
    if (!editor) return;
    return register(key, editor, kind);
  }, [register, key, editor, kind]);
}

/* Browsers default contenteditable spell-check inconsistently, and TipTap sets
   the attribute only at creation — so it's applied to the live DOM node instead.
   Always on, with no control of our own: the editor doesn't run a dictionary, it
   defers to the browser's, and the browser's right-click menu is already where
   turning it off lives. */
function useSpellcheck(editor: Editor | null) {
  useEffect(() => {
    if (!editor) return;
    editor.view.dom.setAttribute('spellcheck', 'true');
  }, [editor]);
}

/* Upload cap. These become base64 inside the document, which is also what gets
   persisted, so an unbounded upload would blow the storage quota on one photo. */
const MAX_UPLOAD_BYTES = 4 * 1024 * 1024;

function readImageFile(file: File): Promise<{ src: string; label: string } | { error: string }> {
  if (!file.type.startsWith('image/')) return Promise.resolve({ error: 'That file isn’t an image.' });
  if (file.size > MAX_UPLOAD_BYTES) return Promise.resolve({ error: `Images need to be under ${Math.round(MAX_UPLOAD_BYTES / 1024 / 1024)} MB. That one is ${(file.size / 1024 / 1024).toFixed(1)} MB.` });
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve(
      typeof reader.result === 'string'
        ? { src: reader.result, label: file.name.replace(/\.[^.]+$/, '') }
        : { error: 'That image couldn’t be read.' },
    );
    reader.onerror = () => resolve({ error: 'That image couldn’t be read.' });
    reader.readAsDataURL(file);
  });
}

/* Audio and video caps. Unlike images these never enter the document — they go to
   IndexedDB (see lib/mediaStore) — so the 4MB localStorage ceiling above doesn't
   apply and the limit is about the book you end up with, not about saving. A
   50MB clip makes a 50MB EPUB, which is past what most retailers will take. */
const MAX_AUDIO_BYTES = 20 * 1024 * 1024;
const MAX_VIDEO_BYTES = 50 * 1024 * 1024;
/* Above this, the upload still works but the panel says what it will do to the
   file size — a warning rather than a refusal, because "too big for a retailer"
   depends on where the book is going and the author knows that, we don't. */
export const HEAVY_MEDIA_BYTES = 10 * 1024 * 1024;

/* First real frame of an uploaded video, for the poster. A linked video gets this
   from the provider; an uploaded one has no thumbnail anywhere, and without a
   poster the block is a black rectangle in the editor and in any reader that
   won't play it. One second in rather than frame zero, which on most encodes is
   a black or title frame. */
function grabVideoPoster(objectUrl: string): Promise<string> {
  return new Promise((resolve) => {
    const video = document.createElement('video');
    let settled = false;
    const done = (value: string) => { if (!settled) { settled = true; resolve(value); } };
    // Never leave the caller hanging on a codec the browser can't decode.
    const timer = setTimeout(() => done(''), 5000);
    video.preload = 'metadata';
    video.muted = true;
    video.playsInline = true;
    video.onloadeddata = () => { video.currentTime = Math.min(1, (video.duration || 2) / 2); };
    video.onseeked = () => {
      clearTimeout(timer);
      try {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (!ctx || !canvas.width) return done('');
        ctx.drawImage(video, 0, 0);
        done(canvas.toDataURL('image/jpeg', 0.82));
      } catch {
        // A blob: URL is same-origin, so the canvas can't taint — but a decode
        // failure here should still cost the poster, not the upload.
        done('');
      }
    };
    video.onerror = () => { clearTimeout(timer); done(''); };
    video.src = objectUrl;
  });
}

export interface ReadMediaResult { src: string; label: string; poster: string; bytes: number }

/* Stores an uploaded clip and returns the reference to put in the document. */
async function readMediaFile(file: File, kind: 'video' | 'audio'): Promise<ReadMediaResult | { error: string }> {
  const wanted = kind === 'video' ? 'video/' : 'audio/';
  if (!file.type.startsWith(wanted)) {
    return { error: kind === 'video' ? 'That file isn’t a video.' : 'That file isn’t an audio file.' };
  }
  const cap = kind === 'video' ? MAX_VIDEO_BYTES : MAX_AUDIO_BYTES;
  if (file.size > cap) {
    return { error: `${kind === 'video' ? 'Videos' : 'Audio files'} need to be under ${Math.round(cap / 1024 / 1024)} MB. That one is ${(file.size / 1024 / 1024).toFixed(1)} MB.` };
  }
  const ref = await putMedia(file);
  if (!ref) return { error: 'This browser wouldn’t store the file. Try a link instead.' };
  const label = file.name.replace(/\.[^.]+$/, '');
  const poster = kind === 'video' ? await grabVideoPoster(mediaUrl(ref)) : '';
  return { src: ref, label, poster, bytes: file.size };
}

/* ── the wrap-aware image node — the whole point of this rebuild ─────────────
   A plain <img> would need x/y coordinates to place near text; this node instead
   carries a `wrap` attribute that resolves to a CSS float, so an image is a
   participant in the document flow, not an object floating over it. */
type WrapValue = 'inline' | 'left' | 'right';

/* 'full-bleed' was a fourth wrap option that rendered identically to inline:
   both resolved to a full-column-width block, differing only by 4px of vertical
   margin, and neither reached the page's own edge. It's gone rather than left
   as a choice that does nothing. Books saved while it existed still carry
   data-wrap="full-bleed", so parsing goes through here — without it they'd keep
   a class no stylesheet matches and lose their margins entirely. */
function parseWrap(raw: string | null): WrapValue {
  return raw === 'left' || raw === 'right' ? raw : 'inline';
}

/* -- hand-resize, for photos and photo grids ---------------------------------
   Same idea as the cover's ResizeHandles + beginResize (four corner dots, the
   diagonally-opposite corner stays put), with two differences that come from
   these boxes living in a text flow rather than on a free canvas:

   - The cover writes x/y/w/h as PERCENTAGES of its stage, because an element
     there is positioned absolutely. A photo in a chapter is positioned by the
     flow, so there is nothing to anchor: the drag writes boxW/boxH in px, the
     same pair the inspector's W and H fields write, and the flow re-places the
     box at its new size.
   - The cover commits on every pointermove into React state. Here a commit is a
     ProseMirror transaction, which re-paginates the chapter -- sixty of those a
     second would fight the reflow loop and leave sixty steps in the undo stack.
     So the drag writes straight to the element's style and commits once, on
     pointerup: one transaction, one reflow, one undo step.

   The canvas is CSS-scaled by the zoom control, so a pointer moves more screen
   pixels than layout pixels at 150% and fewer at 50%. Dividing by the box's own
   rendered-over-layout ratio corrects for it without this code having to know
   anything about zoom. */
const RESIZE_MIN_PX = 48;
type ResizeCorner = 'tl' | 'tr' | 'bl' | 'br';

function buildResizeHandles(onStart: (corner: ResizeCorner, e: PointerEvent) => void): HTMLElement {
  const wrap = document.createElement('div');
  wrap.className = 'book-resize-handles';
  wrap.contentEditable = 'false';
  wrap.style.display = 'none';
  const corners: { corner: ResizeCorner; cursor: string }[] = [
    { corner: 'tl', cursor: 'nwse-resize' },
    { corner: 'tr', cursor: 'nesw-resize' },
    { corner: 'bl', cursor: 'nesw-resize' },
    { corner: 'br', cursor: 'nwse-resize' },
  ];
  for (const { corner, cursor } of corners) {
    const dot = document.createElement('div');
    dot.className = 'book-resize-dot book-resize-dot--' + corner;
    dot.style.cursor = cursor;
    dot.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      onStart(corner, e);
    });
    wrap.appendChild(dot);
  }
  return wrap;
}

function dragResize({ box, corner, event, lockAspect, maxW, commit }: {
  /** The element whose rendered size is being dragged. */
  box: HTMLElement;
  corner: ResizeCorner;
  event: PointerEvent;
  lockAspect: boolean;
  /** Width of the column the box sits in; 0 for "no ceiling". Matches the
      max-width:100% every one of these boxes already renders with, so a drag
      cannot push a photo wider than the page it is on. */
  maxW: number;
  commit: (w: number, h: number) => void;
}) {
  const startW = box.offsetWidth;
  const startH = box.offsetHeight;
  if (!startW || !startH) return;
  const rendered = box.getBoundingClientRect().width;
  const scale = rendered && startW ? rendered / startW : 1;
  const ratio = startW / startH;
  // Which way "bigger" is for this corner: a left-hand handle grows as it
  // moves left, a top handle as it moves up.
  const signX = corner === 'tr' || corner === 'br' ? 1 : -1;
  const signY = corner === 'bl' || corner === 'br' ? 1 : -1;
  const ceiling = maxW > 0 ? maxW : Number.POSITIVE_INFINITY;
  let w = startW;
  let h = startH;

  const onMove = (ev: PointerEvent) => {
    const dx = ((ev.clientX - event.clientX) / scale) * signX;
    const dy = ((ev.clientY - event.clientY) / scale) * signY;
    if (lockAspect) {
      // One dimension drives, and it is whichever the pointer moved further
      // in -- dragging a corner mostly sideways should read as a width change
      // and mostly downwards as a height change, rather than always one.
      const byWidth = Math.abs(dx) >= Math.abs(dy);
      w = Math.round(Math.min(ceiling, Math.max(RESIZE_MIN_PX, byWidth ? startW + dx : (startH + dy) * ratio)));
      h = Math.round(Math.max(RESIZE_MIN_PX, w / ratio));
    } else {
      w = Math.round(Math.min(ceiling, Math.max(RESIZE_MIN_PX, startW + dx)));
      h = Math.round(Math.max(RESIZE_MIN_PX, startH + dy));
    }
    box.style.width = w + 'px';
    box.style.height = h + 'px';
  };
  const onUp = () => {
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
    if (w !== startW || h !== startH) commit(w, h);
  };
  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);
}

/* One pass over the attributes, feeding both renderings of a figure: addNodeView
   builds real DOM from it for the live canvas, renderHTML turns the same values
   into a ProseMirror output spec for editor.getHTML() and every export
   downstream of it. Same split ShapeBlock, QrCodeBlock and ChartBlock already
   use — written once here so the canvas and the exported file cannot drift. */
type ImageNodeAttrs = {
  src: string; alt: string; wrap: WrapValue; caption: string; decorative: boolean; locked: boolean;
  /* Old Designrr wraps the image in a Link element; this is the same thing as a
     property, so an already-placed photo can be pointed somewhere without being
     deleted and re-inserted. Empty means an ordinary picture. */
  href: string;
  radius: string; borderWidth: number; borderColor: string; shadow: string; originalSrc: string; crop: string; opacity: number;
  fit: string; boxW: number; boxH: number; borderPos: string; borderSides: string; borderStyle: string; lockAspect: boolean; sizeMode: string;
  /* How the caption under the photo is set. Unset means the stylesheet's own
     caption treatment (body face, 13px, centred, #6B7686) — so an untouched
     figure serializes exactly the markup it did before these existed, and a
     theme change still moves every caption nobody has overridden. */
  capFont: string; capSize: number; capAlign: string; capColor: string; capBold: boolean; capItalic: boolean;
};

const CAPTION_DEFAULT_SIZE = 13;
const CAPTION_DEFAULT_COLOR = '#6B7686';
/* Fired on the figcaption, bubbling to the chapter's own container, when the
   author puts the caret in a caption or types in one — the one thing a node
   view can do that React above it will hear. See the listener in ChapterEditor
   and CaptionInspector. */
const CAPTION_FOCUS_EVENT = 'book:caption-edit';

function imageFigureParts(attrs: ImageNodeAttrs): { figAttrs: Record<string, string>; imgAttrs: Record<string, string>; capAttrs: Record<string, string> } {
  const { src, alt, wrap, decorative, locked, href, radius, borderWidth, borderColor, shadow, originalSrc, crop, opacity, fit, boxW, boxH, borderPos, borderSides, borderStyle, lockAspect, sizeMode,
    capFont, capSize, capAlign, capColor, capBold, capItalic } = attrs;
  const imgAttrs: Record<string, string> = decorative ? { src, alt: '', role: 'presentation' } : { src, alt };
  const sizing: string[] = [];
  // 'column' needs nothing — .book-img-wrap img is already width:100%.
  if (sizeMode === 'original') sizing.push('width:auto', 'max-width:100%');
  if (sizeMode === 'fixed') {
    if (boxW) sizing.push(`width:${boxW}px`);
    if (boxH) sizing.push(`height:${boxH}px`);
  }
  /* object-fit can only change anything when the box is constrained in BOTH
     dimensions — otherwise the box just takes the photo's own shape and there
     is nothing to trim or letterbox. Emitting it otherwise produced a control
     that visibly did nothing, which is why the panel now hides it instead. */
  if (sizeMode === 'fixed' && boxW && boxH) sizing.push(`object-fit:${fit}`);
  const style = [imageStyleValue({ radius, borderWidth, borderColor, shadow, opacity, borderPos, borderSides, borderStyle }), ...sizing].filter(Boolean).join(';');
  if (style) imgAttrs.style = style;
  const figAttrs: Record<string, string> = {
    'data-wrap': wrap,
    ...(locked ? { 'data-locked': 'true' } : {}),
    // Mirrored onto the figure so parseHTML can read them straight back — the
    // <img>'s own inline style would otherwise have to be re-parsed out of CSS.
    ...(src ? {} : { 'data-empty': 'true' }),
    ...(href ? { 'data-href': href } : {}),
    ...(fit !== 'cover' ? { 'data-fit': fit } : {}),
    ...(sizeMode !== 'column' ? { 'data-size-mode': sizeMode } : {}),
    ...(lockAspect ? {} : { 'data-lock-aspect': 'false' }),
    ...(boxW ? { 'data-w': String(boxW) } : {}),
    ...(boxH ? { 'data-h': String(boxH) } : {}),
    ...(opacity < 1 ? { 'data-opacity': String(opacity) } : {}),
    ...(radius ? { 'data-radius': radius } : {}),
    ...(borderWidth ? {
      'data-border-w': String(borderWidth), 'data-border-c': borderColor, 'data-border-pos': borderPos,
      // Only when it isn't the default, so the markup of the ordinary four-sided
      // stroke is byte-for-byte what it was before sides existed.
      ...(borderSides && borderSides !== 'all' ? { 'data-border-sides': borderSides } : {}),
      ...(borderStyle && borderStyle !== 'solid' ? { 'data-border-style': borderStyle } : {}),
    } : {}),
    ...(shadow && shadow !== 'none' ? { 'data-shadow': shadow } : {}),
    ...(originalSrc ? { 'data-original-src': originalSrc } : {}),
    ...(crop ? { 'data-crop': crop } : {}),
    ...(capFont ? { 'data-cap-font': capFont } : {}),
    ...(capSize ? { 'data-cap-size': String(capSize) } : {}),
    ...(capAlign ? { 'data-cap-align': capAlign } : {}),
    ...(capColor ? { 'data-cap-color': capColor } : {}),
    ...(capBold ? { 'data-cap-bold': 'true' } : {}),
    ...(capItalic ? { 'data-cap-italic': 'true' } : {}),
    class: `book-img-wrap book-img-wrap--${wrap}`,
  };
  /* Inline on the <figcaption> for the same reason the <img>'s own presentation
     is inline: the export path ships this HTML without the editor's stylesheet,
     so a class would style the caption on the canvas and nowhere else. Only the
     properties actually set are emitted, so the rest keep falling through to
     whatever the PDF/EPUB stylesheet says a caption looks like. */
  const capStyle = [
    capFont ? `font-family:${capFont}` : '',
    capSize ? `font-size:${capSize}px` : '',
    capAlign ? `text-align:${capAlign}` : '',
    capColor ? `color:${capColor}` : '',
    capBold ? 'font-weight:700' : '',
    capItalic ? 'font-style:italic' : '',
  ].filter(Boolean).join(';');
  return { figAttrs, imgAttrs, capAttrs: capStyle ? { style: capStyle } : {} };
}

const WrappableImage = TiptapImage.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      wrap: {
        default: 'inline' as WrapValue,
        parseHTML: (el: HTMLElement) => parseWrap(el.getAttribute('data-wrap')),
        renderHTML: (attrs: Record<string, unknown>) => ({
          'data-wrap': attrs.wrap,
          class: `book-img-wrap book-img-wrap--${attrs.wrap}`,
        }),
      },
      // Old Designrr's "Captioned Image" as a plain attribute rather than a second
      // node type: empty renders exactly like before, non-empty wraps the <img> in a
      // <figure> with a <figcaption> underneath (see renderHTML override below).
      caption: {
        default: '',
        parseHTML: (el: HTMLElement) => (el.tagName === 'FIGURE' ? el.querySelector('figcaption')?.textContent ?? '' : ''),
        renderHTML: () => ({}),
      },
      /* An image that carries no meaning. WCAG's answer is an explicit empty alt
         plus role="presentation" — which the alt check previously read as a
         missing alt, leaving decorative images permanently un-passable. */
      decorative: {
        default: false,
        parseHTML: (el: HTMLElement) => el.querySelector('img')?.getAttribute('role') === 'presentation',
        renderHTML: () => ({}),
      },
      // Frozen against drag/resize/delete until unlocked — see the Lock feature's
      // FloatingObjectBar/Inspector treatment. Explicit parseHTML/renderHTML here
      // (rather than relying on the bare attribute default) since this node's own
      // renderHTML below builds its tag from scratch and ignores HTMLAttributes.
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
      /* Read off the <a> as well as off the figure, so an image link that came in
         from an import or a paste survives the round trip and not only one the
         inspector wrote. */
      href: {
        default: '',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-href') ?? el.querySelector('a')?.getAttribute('href') ?? '',
        renderHTML: () => ({}),
      },
      /* Presentation attributes, serialized as an inline style on the <img> by
         renderHTML below. Inline rather than a class because the export path ships
         the serialized HTML on its own — PDF, EPUB and Kindle all get the figure
         markup without this file's stylesheet, so a class would silently drop the
         styling everywhere except the editor canvas. Numeric presets rather than
         free input: these are the four/three choices worth having, and they keep
         the values inside what reflowable EPUB renderers actually honour. */
      /* Crop is applied destructively — the cropped pixels become `src`, so every
         export (PDF, DOCX, EPUB, Kindle) ships a plain <img> that is already the
         right shape. CSS cropping would have been reversible for free, but DOCX
         ignores object-fit entirely and DOCX is the largest ebook export by volume,
         so it would have silently shipped uncropped images.
         `originalSrc` and `crop` exist so the destruction is still undoable and
         re-editable: re-entering crop restores the previous rect and re-cuts from
         the original, never from an already-cropped copy. */
      originalSrc: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-original-src') ?? '', renderHTML: () => ({}) },
      // "x,y,w,h,rotate,flipH,flipV" — x/y/w/h normalised 0–1 against the ORIGINAL.
      crop: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-crop') ?? '', renderHTML: () => ({}) },
      /* How the photo fills its box when it has one — a grid cell, or a manual
         W/H. Default 'cover' so a grid reads as a grid: equal tiles, no ragged
         heights. 'contain' letterboxes instead of trimming. */
      /* How the BOX is sized, as distinct from `fit`, which is how the pixels sit
         inside it. 'column' is the CSS default (width:100%); 'original' lets the
         photo be its own size; 'fixed' honours boxW/boxH. */
      sizeMode: { default: 'column', parseHTML: (el: HTMLElement) => el.getAttribute('data-size-mode') ?? 'column', renderHTML: () => ({}) },
      lockAspect: { default: true, parseHTML: (el: HTMLElement) => el.getAttribute('data-lock-aspect') !== 'false', renderHTML: () => ({}) },
      borderPos: { default: 'inside', parseHTML: (el: HTMLElement) => el.getAttribute('data-border-pos') ?? 'inside', renderHTML: () => ({}) },
      borderSides: { default: 'all', parseHTML: (el: HTMLElement) => el.getAttribute('data-border-sides') ?? 'all', renderHTML: () => ({}) },
      borderStyle: { default: 'solid', parseHTML: (el: HTMLElement) => el.getAttribute('data-border-style') ?? 'solid', renderHTML: () => ({}) },
      fit: { default: 'cover', parseHTML: (el: HTMLElement) => el.getAttribute('data-fit') ?? 'cover', renderHTML: () => ({}) },
      /* Caption typography. Six attributes rather than one packed string like
         `crop` or `shadow`: these are read and written one at a time by one
         control each, and there is nothing to parse back out of a `13,,center`
         that a named attribute doesn't say better. Every default is empty/0,
         meaning "whatever a caption looks like here" — see CAPTION_DEFAULT_*. */
      capFont: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-cap-font') ?? '', renderHTML: () => ({}) },
      capSize: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-cap-size') ?? 0), renderHTML: () => ({}) },
      capAlign: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-cap-align') ?? '', renderHTML: () => ({}) },
      capColor: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-cap-color') ?? '', renderHTML: () => ({}) },
      capBold: { default: false, parseHTML: (el: HTMLElement) => el.getAttribute('data-cap-bold') === 'true', renderHTML: () => ({}) },
      capItalic: { default: false, parseHTML: (el: HTMLElement) => el.getAttribute('data-cap-italic') === 'true', renderHTML: () => ({}) },
      boxW: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-w') ?? 0), renderHTML: () => ({}) },
      boxH: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-h') ?? 0), renderHTML: () => ({}) },
      opacity: { default: 1, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-opacity') ?? 1), renderHTML: () => ({}) },
      radius: { default: '', parseHTML: (el: HTMLElement) => el.getAttribute('data-radius') ?? '', renderHTML: () => ({}) },
      borderWidth: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-border-w') ?? 0), renderHTML: () => ({}) },
      borderColor: { default: '#0F1733', parseHTML: (el: HTMLElement) => el.getAttribute('data-border-c') ?? '#0F1733', renderHTML: () => ({}) },
      shadow: { default: 'none', parseHTML: (el: HTMLElement) => el.getAttribute('data-shadow') ?? 'none', renderHTML: () => ({}) },
    };
  },
  parseHTML() {
    return [
      {
        tag: 'figure[data-wrap]',
        getAttrs: (el) => {
          const figure = el as HTMLElement;
          const img = figure.querySelector('img');
          return {
            src: img?.getAttribute('src') || '',
            alt: img?.getAttribute('alt') || '',
            wrap: parseWrap(figure.getAttribute('data-wrap')),
            caption: figure.querySelector('figcaption')?.textContent ?? '',
            decorative: img?.getAttribute('role') === 'presentation',
            locked: figure.getAttribute('data-locked') === 'true',
            href: figure.getAttribute('data-href') ?? figure.querySelector('a')?.getAttribute('href') ?? '',
            originalSrc: figure.getAttribute('data-original-src') ?? '',
            crop: figure.getAttribute('data-crop') ?? '',
            sizeMode: figure.getAttribute('data-size-mode') ?? 'column',
            lockAspect: figure.getAttribute('data-lock-aspect') !== 'false',
            borderPos: figure.getAttribute('data-border-pos') ?? 'inside',
            borderSides: figure.getAttribute('data-border-sides') ?? 'all',
            borderStyle: figure.getAttribute('data-border-style') ?? 'solid',
            fit: figure.getAttribute('data-fit') ?? 'cover',
            boxW: Number(figure.getAttribute('data-w') ?? 0),
            boxH: Number(figure.getAttribute('data-h') ?? 0),
            opacity: Number(figure.getAttribute('data-opacity') ?? 1),
            radius: figure.getAttribute('data-radius') ?? '',
            borderWidth: Number(figure.getAttribute('data-border-w') ?? 0),
            borderColor: figure.getAttribute('data-border-c') ?? '#0F1733',
            shadow: figure.getAttribute('data-shadow') ?? 'none',
            capFont: figure.getAttribute('data-cap-font') ?? '',
            capSize: Number(figure.getAttribute('data-cap-size') ?? 0),
            capAlign: figure.getAttribute('data-cap-align') ?? '',
            capColor: figure.getAttribute('data-cap-color') ?? '',
            capBold: figure.getAttribute('data-cap-bold') === 'true',
            capItalic: figure.getAttribute('data-cap-italic') === 'true',
          };
        },
      },
      ...(this.parent?.() ?? []),
    ];
  },
  renderHTML({ node }) {
    const attrs = node.attrs as ImageNodeAttrs;
    const { figAttrs, imgAttrs, capAttrs } = imageFigureParts(attrs);
    /* <a><img></a> is valid in every format we export, unlike video. The anchor
       wraps the image only — never the caption, which is the figure's own text
       and not part of what you are clicking.
       Nothing here strips it for print: that happens in the export, because the
       same saved book produces both a PDF and an EPUB and only one of them
       should carry links. */
    const picture = attrs.href
      ? ['a', { href: attrs.href, 'data-img-link': 'true' }, ['img', imgAttrs]] as const
      : ['img', imgAttrs] as const;
    return [
      'figure',
      figAttrs,
      picture,
      /* Serialized only when there is something in it. The live canvas keeps a
         permanently present figcaption so there is always something to click,
         but an empty one in the saved HTML would round-trip into every export
         and print as a blank line under every uncaptioned image. */
      ...(attrs.caption ? [['figcaption', capAttrs, attrs.caption] as const] : []),
    ];
  },

  /* The caption is edited in place, under the image, the way WordPress, Notion,
     Medium and Ghost all do it — not in the side panel. A panel field made you
     leave the picture to describe the picture, and it put a text input and a
     node selection in a tug of war over focus, which is what let typing a
     caption delete the image.

     The node stays a leaf atom and the caption stays an attribute, written by
     this contenteditable, rather than becoming real node content. Content would
     read better in the abstract, but it costs atom-ness, and handleClickOn's
     one-click select, activeObjectKind, MOVABLE_NODE_TYPES and the floating
     object bar all key off exactly that. */
  addNodeView() {
    return ({ node, getPos, editor }) => {
      const dom = document.createElement('figure');
      const img = document.createElement('img');
      const cap = document.createElement('figcaption');
      dom.contentEditable = 'false';
      cap.setAttribute('draggable', 'false');
      let selected = false;
      let composing = false;

      const paint = (n: PMNode) => {
        const attrs = n.attrs as ImageNodeAttrs;
        const { figAttrs, imgAttrs, capAttrs } = imageFigureParts(attrs);
        // Only data-* is ours to clear; contenteditable and draggable belong to
        // ProseMirror, and the selected class is tracked below.
        for (const a of Array.from(dom.attributes)) {
          if (a.name.startsWith('data-') && !(a.name in figAttrs)) dom.removeAttribute(a.name);
        }
        for (const [k, v] of Object.entries(figAttrs)) if (k !== 'class') dom.setAttribute(k, v);
        dom.className = figAttrs.class;
        markSelected();
        for (const a of Array.from(img.attributes)) if (!(a.name in imgAttrs)) img.removeAttribute(a.name);
        for (const [k, v] of Object.entries(imgAttrs)) img.setAttribute(k, v);
        /* Never mid-word: this runs on every transaction, including the one this
           very keystroke just dispatched, and rewriting textContent would drop
           the caret back to the start of the caption on each character. */
        if (!composing && cap.textContent !== attrs.caption) cap.textContent = attrs.caption;
        /* Set wholesale rather than property by property: capAttrs is the whole
           of what this view puts in the caption's style attribute, so clearing a
           property in the panel has to be able to empty it again. */
        if (capAttrs.style) cap.setAttribute('style', capAttrs.style);
        else cap.removeAttribute('style');
        cap.contentEditable = editor.isEditable ? 'true' : 'false';
      };

      const commit = () => {
        // A contenteditable emptied with Backspace keeps a stray <br>, which is
        // enough to defeat :empty and leave a blank line where the collapsed
        // caption should be.
        if (!cap.textContent) cap.innerHTML = '';
        if (typeof getPos !== 'function') return;
        const pos = getPos();
        if (pos == null) return;
        const current = editor.state.doc.nodeAt(pos);
        if (!current || current.type.name !== 'image') return;
        const text = cap.textContent ?? '';
        if (text === current.attrs.caption) return;
        editor.view.dispatch(editor.state.tr.setNodeMarkup(pos, undefined, { ...current.attrs, caption: text }));
      };

      /* Working in the caption moves no ProseMirror selection — stopEvent keeps
         every event in here — so without this nothing outside the node view
         would know the author had stopped editing a photo and started editing
         text. The panel needs exactly that distinction, and an event is the way
         out of a node view: there is no React above it to call. The pos rides
         along because the panel addresses the caption by position (a caption can
         be clicked straight into, with the photo never selected), and getPos is
         the only thing that knows it.

         Pointer-down and input, NOT focus. Selecting the photo already leaves
         the browser's focus in this figcaption — a contenteditable island inside
         a contenteditable-false figure is where the DOM selection lands when
         ProseMirror draws a NodeSelection around it — so a focus listener
         reported "the author is editing the caption" for every click on the
         picture, and the photo's own properties became unreachable. These two
         are the gestures that are unambiguously about the words: putting the
         caret in them, or typing. */
      const announceCaption = () => {
        if (typeof getPos !== 'function') return;
        const pos = getPos();
        if (pos == null) return;
        cap.dispatchEvent(new CustomEvent(CAPTION_FOCUS_EVENT, { bubbles: true, detail: { pos } }));
      };
      cap.addEventListener('pointerdown', announceCaption);
      cap.addEventListener('input', announceCaption);
      cap.addEventListener('input', commit);
      cap.addEventListener('compositionstart', () => { composing = true; });
      cap.addEventListener('compositionend', () => { composing = false; commit(); });
      cap.addEventListener('blur', commit);
      cap.addEventListener('keydown', (e) => {
        // A caption has no second line, so Enter commits rather than splitting
        // anything; Escape does the same. Both hand the selection back to the
        // image, which is where the arrow keys are useful again.
        if (e.key !== 'Enter' && e.key !== 'Escape') return;
        e.preventDefault();
        commit();
        cap.blur();
        if (typeof getPos === 'function') {
          const pos = getPos();
          if (pos != null) editor.chain().focus().setNodeSelection(pos).run();
        }
      });

      /* Two classes, not one. ProseMirror-selectednode is the ring, and it is
         wanted wherever the node is selected — including the read-only chapter
         previews, which start life with a NodeSelection because Selection.atStart
         lands on the first block and these chapters open on an image. The
         placeholder is the part that must not appear there, so it keys off a
         class this view only grants an editable editor.

         Keying the placeholder off :focus-within instead would have been simpler
         and wrong: view.dom blurs the moment the caption's own contenteditable
         takes focus, so the placeholder would vanish out from under the very
         click that was reaching for it. */
      const markSelected = () => {
        dom.classList.toggle('ProseMirror-selectednode', selected);
        dom.classList.toggle('book-img-capt-open', selected && editor.isEditable);
        /* Handles only when the photo is selected, editable and unlocked — the
           same three conditions the cover's own handles render under — and
           never inside a grid, where the cell's shape comes from the grid and
           sizing one photo on its own would mean nothing. The grid's own
           handles take over there. */
        const live = editor.state.doc.nodeAt(typeof getPos === 'function' ? (getPos() ?? -1) : -1);
        const isLocked = !!(live?.attrs as ImageNodeAttrs | undefined)?.locked;
        const inGrid = !!dom.parentElement?.classList.contains('book-image-grid');
        handles.style.display = selected && editor.isEditable && !isLocked && !inGrid ? 'block' : 'none';
      };

      const handles = buildResizeHandles((corner, e) => {
        if (typeof getPos !== 'function') return;
        const pos = getPos();
        if (pos == null) return;
        const current = editor.state.doc.nodeAt(pos);
        if (!current || current.type.name !== 'image') return;
        const attrs = current.attrs as ImageNodeAttrs;
        if (attrs.locked) return;
        dragResize({
          box: img,
          corner,
          event: e,
          lockAspect: attrs.lockAspect !== false,
          maxW: dom.parentElement?.clientWidth ?? 0,
          commit: (w, h) => {
            const at = getPos();
            if (at == null) return;
            const node2 = editor.state.doc.nodeAt(at);
            if (!node2 || node2.type.name !== 'image') return;
            /* Focus first, and keep the photo selected. The handles swallow
               their own pointer events so the view never took focus during the
               drag — and an unfocused editor's history keymap never sees ⌘Z,
               so the resize was landing in the undo stack with no way to reach
               it. scrollIntoView off: the thing you just dragged is by
               definition already under the pointer.

               Same consequence the W/H fields in the inspector apply: giving a
               photo a size IS leaving "fits the column", so the mode follows
               the act rather than being a second thing to set. */
            editor.view.focus();
            editor.chain()
              .setNodeSelection(at)
              .updateAttributes('image', { sizeMode: 'fixed', boxW: w, boxH: h })
              .run();
          },
        });
      });

      dom.appendChild(img);
      dom.appendChild(cap);
      dom.appendChild(handles);
      paint(node);

      return {
        dom,
        update: (updated: PMNode) => {
          if (updated.type.name !== 'image') return false;
          paint(updated);
          return true;
        },
        selectNode: () => { selected = true; markSelected(); },
        deselectNode: () => { selected = false; markSelected(); },
        /* Everything inside the caption is ours. Without this ProseMirror reads
           a keystroke there as a keystroke on the selected image, and its base
           keymap answers Backspace on a NodeSelection by deleting the node. */
        // globalThis.Node, not Node — @tiptap/core's Node is imported here and
        // shadows the DOM one at the type level.
        /* The handles are ours too, not just the caption. Without them here a
           pointerdown on a handle reaches ProseMirror, which answers it by
           moving the selection — so the drag would end before it began. */
        stopEvent: (e: Event) => !!e.target && (cap.contains(e.target as globalThis.Node) || handles.contains(e.target as globalThis.Node)),
        /* And the live width/height written straight onto the <img> mid-drag
           is a mutation this view caused on purpose; letting ProseMirror see
           it would have it re-read the node and throw the drag away. */
        ignoreMutation: (m: { target: globalThis.Node }) => cap.contains(m.target) || handles.contains(m.target) || m.target === img,
      };
    };
  },
});

/* The crop panel. Contents and order follow the eight products surveyed: aspect
   presets first, then rotate and flip (which live *with* crop in six of the
   eight, not as separate properties), then Reset, then an explicit commit.
   Cropping is always a mode you apply or cancel — none of the surveyed products
   let it happen live as a property. */
const CROP_ASPECTS: { id: string; label: string; ratio: number | null }[] = [
  { id: 'free', label: 'Free', ratio: null },
  { id: 'orig', label: 'Original', ratio: 0 },
  { id: '1:1', label: '1:1', ratio: 1 },
  { id: '4:5', label: '4:5', ratio: 4 / 5 },
  { id: '3:2', label: '3:2', ratio: 3 / 2 },
  { id: '16:9', label: '16:9', ratio: 16 / 9 },
];

function CropPanel({ aspectId, busy, error, onAspect, onReset, onCancel, onApply }: {
  aspectId: string;
  busy: boolean;
  error: string;
  onAspect: (id: string) => void;
  onReset: () => void;
  onCancel: () => void;
  onApply: () => void;
}) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto' }}>
        <InspectorShell>
          <InspectorSection label="Aspect" hint="Drag the corners on the page to fine-tune.">
            <OptionGrid columns={3} value={aspectId} onChange={onAspect} options={CROP_ASPECTS.map((a) => ({ id: a.id, label: a.label }))} />
          </InspectorSection>
          {error && (
            <div style={{ ...ns, fontSize: 11.5, color: '#B91C1C', lineHeight: 1.45, paddingBottom: 12 }}>{error}</div>
          )}
        </InspectorShell>
      </div>
      <div className="flex flex-col flex-shrink-0" style={{ gap: 8, padding: '12px 14px', borderTop: `1px solid ${BORDER}` }}>
        <div className="flex" style={{ gap: 8 }}>
          <button
            onClick={onCancel}
            className="flex-1 cursor-pointer"
            style={{ ...ns, fontSize: 12.5, fontWeight: 600, color: INK, background: '#fff', border: `1px solid ${BORDER}`, borderRadius: RADIUS_MD, padding: '9px 10px' }}
          >
            Cancel
          </button>
          <button
            onClick={onApply}
            disabled={busy}
            className="flex-1 cursor-pointer"
            style={{ ...ns, fontSize: 12.5, fontWeight: 700, color: '#fff', background: BLUE, border: 'none', borderRadius: RADIUS_MD, padding: '9px 10px', opacity: busy ? 0.6 : 1 }}
          >
            {busy ? 'Applying…' : 'Apply'}
          </button>
        </div>
        {/* Reset undoes the crop entirely by restoring originalSrc — which is why
            the original is kept rather than discarded after applying. */}
        <button
          onClick={onReset}
          className="cursor-pointer"
          style={{ ...ns, fontSize: 12, fontWeight: 600, color: SLATE, background: 'none', border: 'none', padding: '2px 0' }}
        >
          Reset to original
        </button>
      </div>
    </div>
  );
}

/* ── on-canvas crop overlay ──────────────────────────────────────────────────
   Body-portalled and positioned from getBoundingClientRect rather than absolutely
   placed inside the canvas: the canvas carries a transform:scale() for zoom, and a
   transformed ancestor breaks position:sticky and makes absolute offsets lie (see
   the zoom-breaks-sticky note on FloatingBarPortal above). Reading the live rect
   each frame is the only thing that stays correct at every zoom level.

   The look follows the eight products surveyed: everything outside the rect dims,
   the rect carries L-bracket corner handles, and a rule-of-thirds grid appears
   while dragging. Drag a corner to resize, drag the middle to reposition. */
function CropOverlay({ targetRef, crop, onChange }: {
  targetRef: React.RefObject<HTMLElement | null>;
  crop: CropSpec;
  onChange: (next: CropSpec) => void;
}) {
  const [box, setBox] = useState<{ top: number; left: number; width: number; height: number } | null>(null);
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    const update = () => {
      const el = targetRef.current;
      if (!el) { setBox(null); return; }
      const r = el.getBoundingClientRect();
      setBox(r.width && r.height ? { top: r.top, left: r.left, width: r.width, height: r.height } : null);
    };
    update();
    window.addEventListener('scroll', update, true);
    window.addEventListener('resize', update);
    const el = targetRef.current;
    const ro = el && typeof ResizeObserver !== 'undefined' ? new ResizeObserver(update) : null;
    if (el) ro?.observe(el);
    return () => {
      window.removeEventListener('scroll', update, true);
      window.removeEventListener('resize', update);
      ro?.disconnect();
    };
  }, [targetRef]);

  const startDrag = (mode: 'move' | 'nw' | 'ne' | 'sw' | 'se') => (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!box) return;
    const startX = e.clientX;
    const startY = e.clientY;
    const start = { ...crop };
    setDragging(true);
    const MIN = 0.05; // never let the rect collapse to something unclickable

    const onMove = (ev: PointerEvent) => {
      const dx = (ev.clientX - startX) / box.width;
      const dy = (ev.clientY - startY) / box.height;
      const next = { ...start };
      if (mode === 'move') {
        next.x = Math.min(Math.max(0, start.x + dx), 1 - start.w);
        next.y = Math.min(Math.max(0, start.y + dy), 1 - start.h);
      } else {
        // Each corner moves its own two edges; the opposite two stay pinned, so
        // the rect grows from where you grabbed it rather than from its centre.
        if (mode === 'nw' || mode === 'sw') {
          const nx = Math.min(Math.max(0, start.x + dx), start.x + start.w - MIN);
          next.w = start.w + (start.x - nx);
          next.x = nx;
        } else {
          next.w = Math.min(Math.max(MIN, start.w + dx), 1 - start.x);
        }
        if (mode === 'nw' || mode === 'ne') {
          const ny = Math.min(Math.max(0, start.y + dy), start.y + start.h - MIN);
          next.h = start.h + (start.y - ny);
          next.y = ny;
        } else {
          next.h = Math.min(Math.max(MIN, start.h + dy), 1 - start.y);
        }
      }
      onChange(next);
    };
    const onUp = () => {
      setDragging(false);
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  if (!box) return null;
  const rect = {
    left: box.left + crop.x * box.width,
    top: box.top + crop.y * box.height,
    width: crop.w * box.width,
    height: crop.h * box.height,
  };
  const BRACKET = 18;
  const corners: { id: 'nw' | 'ne' | 'sw' | 'se'; style: React.CSSProperties }[] = [
    { id: 'nw', style: { left: -2, top: -2, borderTop: '3px solid #fff', borderLeft: '3px solid #fff', cursor: 'nwse-resize' } },
    { id: 'ne', style: { right: -2, top: -2, borderTop: '3px solid #fff', borderRight: '3px solid #fff', cursor: 'nesw-resize' } },
    { id: 'sw', style: { left: -2, bottom: -2, borderBottom: '3px solid #fff', borderLeft: '3px solid #fff', cursor: 'nesw-resize' } },
    { id: 'se', style: { right: -2, bottom: -2, borderBottom: '3px solid #fff', borderRight: '3px solid #fff', cursor: 'nwse-resize' } },
  ];

  return createPortal(
    <div className="fixed" style={{ inset: 0, zIndex: 70, pointerEvents: 'none' }}>
      {/* Four panes dimming the image outside the rect, rather than one huge
          spread shadow. A 9999px shadow would dim whatever happened to sit below
          it in the stacking order — including the crop panel itself — so what got
          greyed out would depend on stacking accidents. Pinterest, Buffer and
          Magnific all scope the dim to the image exactly; these panes do that
          deterministically. */}
      {([
        { left: box.left, top: box.top, width: box.width, height: rect.top - box.top },
        { left: box.left, top: rect.top + rect.height, width: box.width, height: box.top + box.height - (rect.top + rect.height) },
        { left: box.left, top: rect.top, width: rect.left - box.left, height: rect.height },
        { left: rect.left + rect.width, top: rect.top, width: box.left + box.width - (rect.left + rect.width), height: rect.height },
      ]).map((pane, i) => (
        <div key={i} className="absolute" style={{ ...pane, width: Math.max(0, pane.width), height: Math.max(0, pane.height), background: 'rgba(15,23,51,0.55)' }} />
      ))}
      <div
        className="absolute"
        onPointerDown={startDrag('move')}
        style={{
          left: rect.left, top: rect.top, width: rect.width, height: rect.height,
          pointerEvents: 'auto', cursor: 'move',
          outline: '1px solid rgba(255,255,255,0.9)',
        }}
      >
        {dragging && (
          <>
            {[1, 2].map((i) => (
              <div key={`v${i}`} className="absolute" style={{ left: `${(i * 100) / 3}%`, top: 0, bottom: 0, width: 1, background: 'rgba(255,255,255,0.45)' }} />
            ))}
            {[1, 2].map((i) => (
              <div key={`h${i}`} className="absolute" style={{ top: `${(i * 100) / 3}%`, left: 0, right: 0, height: 1, background: 'rgba(255,255,255,0.45)' }} />
            ))}
          </>
        )}
        {corners.map((c) => (
          <div
            key={c.id}
            onPointerDown={startDrag(c.id)}
            className="absolute"
            style={{ width: BRACKET, height: BRACKET, pointerEvents: 'auto', ...c.style }}
          />
        ))}
      </div>
    </div>,
    document.body,
  );
}

/* ── crop model ──────────────────────────────────────────────────────────────
   A crop is a rect in normalised 0–1 coordinates against the ORIGINAL image,
   plus a quarter-turn rotation and two flips. Normalised so it survives the
   image being re-encoded at a different pixel size, and so re-entering crop can
   restore the exact rect the user last dragged. */
type TransformOp =
  | { kind: 'rotate-by'; deg: number }
  | { kind: 'rotate-to'; deg: number }
  | { kind: 'flip'; axis: 'h' | 'v' };
type CropSpec = { x: number; y: number; w: number; h: number; rotate: number; flipH: boolean; flipV: boolean };
type CropTarget =
  | { kind: 'node'; editor: Editor }
  | { kind: 'cover'; pageId: string; elementId: string };
const IDENTITY_CROP: CropSpec = { x: 0, y: 0, w: 1, h: 1, rotate: 0, flipH: false, flipV: false };

function parseCrop(raw: string): CropSpec {
  if (!raw) return { ...IDENTITY_CROP };
  const p = raw.split(',');
  if (p.length < 7) return { ...IDENTITY_CROP };
  const n = (i: number, fallback: number) => (Number.isFinite(Number(p[i])) ? Number(p[i]) : fallback);
  return {
    x: n(0, 0), y: n(1, 0), w: n(2, 1), h: n(3, 1),
    rotate: ((n(4, 0) % 360) + 360) % 360,
    flipH: p[5] === '1', flipV: p[6] === '1',
  };
}
function serializeCrop(c: CropSpec): string {
  const isIdentity = c.x === 0 && c.y === 0 && c.w === 1 && c.h === 1 && c.rotate === 0 && !c.flipH && !c.flipV;
  if (isIdentity) return '';
  const r = (v: number) => Math.round(v * 10000) / 10000;
  return [r(c.x), r(c.y), r(c.w), r(c.h), c.rotate, c.flipH ? 1 : 0, c.flipV ? 1 : 0].join(',');
}

/* Cuts the crop out of `srcUrl` and hands back a data URL. Rotation is applied
   to the OUTPUT canvas (so a quarter-turn swaps width and height) while the crop
   rect stays in the source image's own coordinate space — which is what keeps the
   rect meaningful when you re-open crop later.
   Remote images taint the canvas unless the host sends CORS headers, and a tainted
   canvas makes toDataURL throw — so this rejects with a message the panel can show
   rather than failing silently. */
function renderCrop(srcUrl: string, c: CropSpec): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onerror = () => reject(new Error("Couldn't load this image to crop it."));
    img.onload = () => {
      const sx = Math.round(c.x * img.naturalWidth);
      const sy = Math.round(c.y * img.naturalHeight);
      const sw = Math.max(1, Math.round(c.w * img.naturalWidth));
      const sh = Math.max(1, Math.round(c.h * img.naturalHeight));
      /* The output canvas is the rotated rect's bounding box, so any angle works,
         not just quarter-turns — at 90/270 this reduces to swapping width and
         height, and at other angles it leaves transparent corners. That is fine
         here because the image is a block in the text flow: it stays a rectangle
         and simply gets taller, rather than overlapping the paragraphs around it
         the way a CSS transform would. */
      const rad = (c.rotate * Math.PI) / 180;
      const cos = Math.abs(Math.cos(rad));
      const sin = Math.abs(Math.sin(rad));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(sw * cos + sh * sin));
      canvas.height = Math.max(1, Math.round(sw * sin + sh * cos));
      const ctx = canvas.getContext('2d');
      if (!ctx) { reject(new Error("Couldn't prepare the image for cropping.")); return; }
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate((c.rotate * Math.PI) / 180);
      ctx.scale(c.flipH ? -1 : 1, c.flipV ? -1 : 1);
      ctx.drawImage(img, sx, sy, sw, sh, -sw / 2, -sh / 2, sw, sh);
      try {
        // PNG keeps transparency (cut-outs, logos) but is heavy for photographs;
        // JPEG is picked when the source clearly isn't transparent. Quality 0.92
        // is the usual "no visible loss" point and roughly halves the payload,
        // which matters because the original is kept alongside this one.
        // A non-quarter-turn leaves transparent corners, and JPEG has no alpha —
        // it would render them black — so any such angle forces PNG regardless of
        // the source format.
        const needsAlpha = c.rotate % 90 !== 0;
        const isPng = needsAlpha || /^data:image\/png/i.test(srcUrl) || /\.png(\?|$)/i.test(srcUrl);
        resolve(canvas.toDataURL(isPng ? 'image/png' : 'image/jpeg', 0.92));
      } catch {
        reject(new Error("This image is hosted somewhere that blocks editing. Upload a copy to crop it."));
      }
    };
    img.src = srcUrl;
  });
}

/* The aspect picker in the AI composer used to be decorative: `aspect` only
   perturbed the seed that chose WHICH bundled photo came back, so picking
   Portrait and picking Square produced two differently-shaped stock photos and
   neither matched the label. These are the real ratios behind those labels. */
type Aspect = 'square' | 'landscape' | 'portrait';
const ASPECT_RATIOS: Record<Aspect, number> = {
  square: 1,
  landscape: 16 / 9,
  portrait: 9 / 16,
};

/* The three presets plus the shape of whatever slot the generator was opened
   for — see GenerateImagePanel's frameRatio. 'frame' has no entry in
   ASPECT_RATIOS because its number comes from the caller, not from this table. */
type GenAspect = Aspect | 'frame';

/* A decimal ratio as the whole-number pair people name shapes with: 1.5 → 3:2,
   0.5625 → 9:16. The denominator is capped at 12 and the pair reduced, so a
   banner at 3.35 reads "10:3" rather than an exact fraction nobody recognises —
   this is a label on a dropdown, and a label's job is to be recognised. */
function ratioLabel(ratio: number): string {
  let best = { num: 1, den: 1, err: Infinity };
  for (let den = 1; den <= 12; den++) {
    const num = Math.max(1, Math.round(ratio * den));
    const err = Math.abs(num / den - ratio);
    if (err < best.err) best = { num, den, err };
  }
  const gcd = (a: number, b: number): number => (b ? gcd(b, a % b) : a);
  const g = gcd(best.num, best.den);
  return `${best.num / g}:${best.den / g}`;
}

/* Centre-crops `srcUrl` to `ratio` and hands back a data URL — a "cover" crop,
   so the result always fills the requested shape with no letterboxing and no
   distortion, taking the middle of whichever axis is too long.
   The bundled stock images are same-origin, so the canvas can't taint here; the
   catch is kept anyway because the caller also passes generated entries back
   through, and a tainted canvas throws on toDataURL rather than failing the
   draw. The caller falls back to the uncropped source. */
function renderToAspect(srcUrl: string, ratio: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onerror = () => reject(new Error("Couldn't load the image."));
    img.onload = () => {
      const natW = img.naturalWidth;
      const natH = img.naturalHeight;
      // Take the full short axis and cut the long one down to the target.
      let sw = natW;
      let sh = natH;
      if (natW / natH > ratio) sw = Math.round(natH * ratio);
      else sh = Math.round(natW / ratio);
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, sw);
      canvas.height = Math.max(1, sh);
      const ctx = canvas.getContext('2d');
      if (!ctx) { reject(new Error("Couldn't prepare the image.")); return; }
      ctx.drawImage(img, Math.round((natW - sw) / 2), Math.round((natH - sh) / 2), sw, sh, 0, 0, sw, sh);
      // Photographs, and the source is always a bundled JPEG — no alpha to keep.
      try { resolve(canvas.toDataURL('image/jpeg', 0.92)); }
      catch { reject(new Error("This image is hosted somewhere that blocks editing.")); }
    };
    img.src = srcUrl;
  });
}

/* One place that turns the four styling attributes into CSS, called from the
   node's renderHTML — which drives both the live canvas and the serialized export,
   so there's no second code path to keep in step. Returns '' when nothing is set,
   which keeps an unstyled image's markup byte-identical to before. */
/* Shadow is stored as "x,y,blur,opacity" rather than a named preset, so any value
   in between is expressible — Figma's Effects and Canva's Shadows are both fully
   continuous, and named steps could only ever offer two or three of them. Empty
   string means no shadow, which keeps an unstyled image's markup unchanged.
   The two legacy preset names are still read so images styled before the switch
   don't lose their shadow. */
type ShadowSpec = { x: number; y: number; blur: number; spread: number; color: string; opacity: number };
const DEFAULT_SHADOW: ShadowSpec = { x: 0, y: 4, blur: 4, spread: 0, color: '#000000', opacity: 0.25 };
const LEGACY_SHADOWS: Record<string, ShadowSpec> = {
  soft: { x: 0, y: 2, blur: 10, spread: 0, color: '#0F1733', opacity: 0.14 },
  strong: { x: 0, y: 8, blur: 28, spread: 0, color: '#0F1733', opacity: 0.28 },
};
function parseShadow(raw: string): ShadowSpec | null {
  if (!raw || raw === 'none') return null;
  if (LEGACY_SHADOWS[raw]) return { ...LEGACY_SHADOWS[raw] };
  const p = raw.split(',');
  // 4 parts is the earlier x,y,blur,opacity form, kept readable so images styled
  // before spread and colour existed still render.
  if (p.length === 4) {
    const n = p.map(Number);
    if (n.some((v) => !Number.isFinite(v))) return null;
    return { x: n[0], y: n[1], blur: n[2], spread: 0, color: '#0F1733', opacity: n[3] };
  }
  if (p.length < 6) return null;
  const n = [p[0], p[1], p[2], p[3], p[5]].map(Number);
  if (n.some((v) => !Number.isFinite(v))) return null;
  return { x: n[0], y: n[1], blur: n[2], spread: n[3], color: p[4] || '#000000', opacity: n[4] };
}
function serializeShadow(sh: ShadowSpec | null): string {
  if (!sh) return '';
  const r = (v: number) => Math.round(v * 100) / 100;
  return [r(sh.x), r(sh.y), r(sh.blur), r(sh.spread), sh.color, r(sh.opacity)].join(',');
}

/* #RRGGBB + 0–1 alpha → rgba(), so a shadow colour can carry its own opacity the
   way Figma's colour row does (hex on the left, % on the right). */
function hexToRgba(hex: string, alpha: number): string {
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
  const n = parseInt(full, 16);
  if (!Number.isFinite(n) || full.length !== 6) return `rgba(15,23,51,${alpha})`;
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`;
}

/* One accent colour is the whole control for an info box — the two things it
   renders (a pale fill and the solid bar down its left edge) are that colour at
   two strengths, so asking for both would be asking someone to hand-mix a
   palette they can't see. Checked against the built-in presets: Info's #2563EB
   mixes to within a couple of points of its hand-picked #EAF2FF tint, so a
   custom colour lands in the same visual family as the presets, not beside
   it. */
function mixWithWhite(hex: string, strength: number): string {
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
  const n = parseInt(full, 16);
  if (!Number.isFinite(n) || full.length !== 6) return '#FFFFFF';
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255]
    .map((v) => Math.round(255 - (255 - v) * strength))
    .map((v) => v.toString(16).padStart(2, '0'));
  return `#${ch.join('')}`;
}
const CALLOUT_TINT_STRENGTH = 0.08;
function calloutCustomStyle(color: string): string {
  return [
    `background:${mixWithWhite(color, CALLOUT_TINT_STRENGTH)}`,
    `border-left-color:${color}`,
  ].join(';');
}

/* Corner radius is a string so corners can differ: "" or "8" is uniform,
   "8,4,2,0" is TL,TR,BR,BL — the order CSS border-radius already uses, and the
   order Figma's independent-corner fields are laid out in. */
function parseRadius(raw: string | number): number[] {
  if (typeof raw === 'number') return [raw, raw, raw, raw];
  if (!raw) return [0, 0, 0, 0];
  const p = String(raw).split(',').map(Number);
  if (p.some((n) => !Number.isFinite(n))) return [0, 0, 0, 0];
  return p.length === 1 ? [p[0], p[0], p[0], p[0]] : [p[0] ?? 0, p[1] ?? 0, p[2] ?? 0, p[3] ?? 0];
}
function serializeRadius(c: number[]): string {
  if (c.every((v) => v === 0)) return '';
  return c.every((v) => v === c[0]) ? String(c[0]) : c.join(',');
}
/* WHICH edges a stroke paints. Figma's model, because these are Figma's panels:
   a dropdown that reads All / Top / Right / Bottom / Left, plus a Custom mode
   whose four toggles cover every combination a book actually asks for — a rule
   under a photo, a hairline above a caption, an L, three sides of a frame.
   Word's border gallery and Webflow's four side tabs express the same choice;
   the dropdown-plus-custom form is the one that fits a 264px panel without
   spending a permanent row on five icon buttons.
   Stored as 'all' or a comma list of t/r/b/l, so the commonest case is one short
   token and content written before this existed — which carries no attribute at
   all — reads as 'all', exactly what it rendered as. */
type BorderSide = 't' | 'r' | 'b' | 'l';
const BORDER_SIDES: BorderSide[] = ['t', 'r', 'b', 'l'];
const BORDER_SIDE_CSS: Record<BorderSide, string> = { t: 'top', r: 'right', b: 'bottom', l: 'left' };
const BORDER_SIDE_STYLE_KEY: Record<BorderSide, string> = { t: 'borderTop', r: 'borderRight', b: 'borderBottom', l: 'borderLeft' };
const BORDER_SIDE_LABEL: Record<BorderSide, string> = { t: 'Top', r: 'Right', b: 'Bottom', l: 'Left' };

/* How the line is drawn, as opposed to where it is drawn. Solid/dashed/dotted are
   the three a CSS border and an SVG path can both express, so one field serves
   the photo, the cover shape and the body shape atom alike — a fourth (double,
   groove) would be CSS-only and would have to be missing from half the panels. */
type StrokeStyle = 'solid' | 'dashed' | 'dotted';
const STROKE_STYLE_OPTIONS = [
  { id: 'solid' as const, label: 'Solid' },
  { id: 'dashed' as const, label: 'Dashed' },
  { id: 'dotted' as const, label: 'Dotted' },
];
function strokeStyleOf(v?: string): StrokeStyle {
  return v === 'dashed' || v === 'dotted' ? v : 'solid';
}
/* The SVG equivalent, for the two shapes drawn as paths rather than boxes (the
   cover triangle, the body shape atom). Scaled by the stroke's own width so a
   dash on a hairline and a dash on a 12px rule look like the same pattern, and
   dots are zero-length dashes with a round cap — the one way SVG draws a dot. */
function strokeDash(style: StrokeStyle, width: number): { strokeDasharray?: string; strokeLinecap?: 'round' } {
  if (style === 'dashed') return { strokeDasharray: `${width * 2.5} ${width * 1.75}` };
  if (style === 'dotted') return { strokeDasharray: `0 ${width * 2}`, strokeLinecap: 'round' };
  return {};
}

function parseBorderSides(v?: string): BorderSide[] {
  if (!v || v === 'all') return [...BORDER_SIDES];
  const parts = v.split(',');
  const picked = BORDER_SIDES.filter((s) => parts.includes(s));
  /* No edges at all would render as no stroke while the section still claimed to
     have one — a control that silently contradicts its own header. Removing the
     stroke is what the section's minus button is for, so an empty set reads as
     all four instead. */
  return picked.length ? picked : [...BORDER_SIDES];
}
function serializeBorderSides(sides: BorderSide[]): string {
  return sides.length === BORDER_SIDES.length ? 'all' : BORDER_SIDES.filter((s) => sides.includes(s)).join(',');
}
/* One `border` when it's all four — shorter, and the only form DOCX carries
   across — otherwise one longhand per painted edge. */
function borderCssParts(width: number, color: string, sides: BorderSide[], style: StrokeStyle = 'solid'): string[] {
  if (sides.length === BORDER_SIDES.length) return [`border:${width}px ${style} ${color}`];
  return sides.map((s) => `border-${BORDER_SIDE_CSS[s]}:${width}px ${style} ${color}`);
}
/* The same declarations as a React style object, for the cover canvas, which
   builds its shapes and photos as styled divs rather than as a CSS string. */
function borderStyleObject(width: number, color: string, sides: BorderSide[], style: StrokeStyle = 'solid'): React.CSSProperties {
  if (sides.length === BORDER_SIDES.length) return { border: `${width}px ${style} ${color}` };
  const out: Record<string, string> = {};
  for (const s of sides) out[BORDER_SIDE_STYLE_KEY[s]] = `${width}px ${style} ${color}`;
  return out as React.CSSProperties;
}

/* Position, sides and style resolved for a box drawn in React rather than in a
   CSS string — the cover's shapes and photos. Same three positions and the same
   two exclusions as imageStyleValue (which is the CSS-string twin of this), so a
   dashed or partial stroke can't mean one thing in a chapter and another on the
   cover. The ring comes back separately because the caller has to compose it
   with its own drop shadow, which is the same box-shadow property. */
function strokeBoxStyle(width: number, color: string, sidesSpec?: string, positionSpec?: string, styleSpec?: string): { css: React.CSSProperties; ring: string | null } {
  if (!(width > 0)) return { css: {}, ring: null };
  const sides = parseBorderSides(sidesSpec);
  const style = strokeStyleOf(styleSpec);
  const whole = sides.length === BORDER_SIDES.length;
  const pos = whole && style === 'solid' ? (positionSpec ?? 'inside') : 'inside';
  if (pos === 'outside') return { css: {}, ring: `0 0 0 ${width}px ${color}` };
  if (pos === 'center') return { css: borderStyleObject(width / 2, color, sides, style), ring: `0 0 0 ${width / 2}px ${color}` };
  return { css: borderStyleObject(width, color, sides, style), ring: null };
}

function imageStyleValue({ radius, borderWidth, borderColor, shadow, opacity, borderPos, borderSides, borderStyle }: {
  radius: string; borderWidth: number; borderColor: string; shadow: string; opacity: number; borderPos?: string; borderSides?: string; borderStyle?: string;
}): string {
  const parts: string[] = [];
  if (opacity < 1) parts.push(`opacity:${Math.max(0, Math.min(1, opacity))}`);
  const corners = parseRadius(radius);
  if (corners.some((v) => v > 0)) parts.push(`border-radius:${corners.map((v) => `${v}px`).join(' ')}`);
  /* Stroke position, Figma's three options, each rendered with the CSS that
     actually behaves that way:
       inside  — a real `border`, which is also the only one DOCX carries across,
                 so it stays the default;
       outside — a hard box-shadow ring, which (unlike `outline`) follows the
                 corner radius;
       center  — half of each, which is exactly what "centered on the edge" means.
     A ring shadow composes with the drop shadow below by being listed first. */
  const rings: string[] = [];
  if (borderWidth) {
    const sides = parseBorderSides(borderSides);
    const whole = sides.length === BORDER_SIDES.length;
    /* A ring is a box-shadow, and a box-shadow has no sides — so Outside and
       Centre only exist while the stroke is on all four edges. The panel hides
       Position the moment it isn't, and the render agrees with it: a partial
       stroke is always a real per-edge border. */
    /* And a ring has no dashes either — it's one solid shadow — so a dashed or
       dotted stroke is likewise always the real border. Same rule, same place,
       so the panel has exactly one condition to hide Position under. */
    const style = strokeStyleOf(borderStyle);
    const pos = whole && style === 'solid' ? (borderPos ?? 'inside') : 'inside';
    if (pos === 'inside') parts.push(...borderCssParts(borderWidth, borderColor, sides, style));
    else if (pos === 'outside') rings.push(`0 0 0 ${borderWidth}px ${borderColor}`);
    else {
      parts.push(...borderCssParts(borderWidth / 2, borderColor, sides, style));
      rings.push(`0 0 0 ${borderWidth / 2}px ${borderColor}`);
    }
  }
  const sh = parseShadow(shadow);
  if (sh) rings.push(`${sh.x}px ${sh.y}px ${sh.blur}px ${sh.spread}px ${hexToRgba(sh.color, sh.opacity)}`);
  if (rings.length) parts.push(`box-shadow:${rings.join(',')}`);
  return parts.join(';');
}

/* A boxed note/tip — one of the block types named in the original document-tree
   decision but never actually built. A real schema node (not a plain <div>) so it
   survives ProseMirror's HTML parsing and stays selectable/deletable as a unit. */
/* Three, not six. A note, a tip and a warning are the three things a how-to
   ebook actually flags, and every extra hue past that is a decision the author
   has to make about a box they only wanted to put a sentence in. Amber, not red,
   for the warning — consistent with the banner-colour survey: red reads as
   failure, and a warning in a book is a caution, not an error. */
/* Info / Note / Warning — blue, grey, amber. Green "Tip" is gone: it sat in the
   same semantic slot as the blue one (both mean "here's something useful") and
   only differed in hue, while nothing covered the commonest case of all, an
   aside that shouldn't shout at any particular colour.

   The ids deliberately don't match the labels. `note` is the blue one because
   `data-callout-type="note"` is what every book already saved on disk says for
   a blue box, and it's what the base `.book-callout` rule renders in both this
   file and epub.ts — relabelling is free, renumbering would silently recolour
   books people have already written. The grey one is new, so it gets a new id.
   Old `tip` boxes fail calloutType's validation and fall back to blue, which is
   the closest of the three that remain. */
const CALLOUT_TYPES = [
  { id: 'note', label: 'Info', tint: '#EAF2FF', accent: '#2563EB' },
  { id: 'neutral', label: 'Note', tint: '#F4F6F8', accent: '#7A8698' },
  { id: 'warning', label: 'Warning', tint: '#FFF8EB', accent: '#B4770E' },
] as const;
type CalloutType = typeof CALLOUT_TYPES[number]['id'];

/* ── chapter title ───────────────────────────────────────────────────────────
   The chapter's name, living in the text rather than in a field beside it.

   That is the whole point: a title that is part of the flow can sit anywhere in
   the flow, which is what lets a chapter begin halfway down a page. The old
   separate field could only ever be at the top of its own page, because it was
   attached to the page rather than to the words.

   It serializes as a plain <h2>, which is what the exported file has always
   contained — the exporter used to reassemble one from the field on the way out.
   So this node makes the editor agree with the file instead of translating
   between them, and an <h2> in any book saved before this parses straight into
   one.

   `breakBefore` defaults to true, because a chapter opening a page is the
   convention every trade book and Amazon's own Kindle Create follow. Turning it
   off is the new capability, not the new default. */
const ChapterTitleBlock = Node.create({
  name: 'chapterTitle',
  group: 'block',
  content: 'inline*',
  defining: true,
  addAttributes() {
    return {
      breakBefore: {
        default: true,
        // Absent means true: an <h2> from an older book, or one pasted in from
        // Word, is a chapter that starts a page — the behaviour it already had.
        parseHTML: (el: HTMLElement) => el.getAttribute('data-break-before') !== 'false',
        renderHTML: (attrs: Record<string, unknown>) => (
          attrs.breakBefore === false ? { 'data-break-before': 'false' } : {}
        ),
      },
    };
  },
  /* Deliberately NOT a bare `h2` yet. The body editor allows heading levels 3
     and 4 only, so an <h2> sitting in saved content today parses as a paragraph;
     claiming the bare tag here would silently turn it into a page-breaking
     chapter title in books that never asked for one. This widens to `h2` in the
     same step that migrates the existing title fields into the flow, where the
     change is intended and can be tested against real books. */
  parseHTML() {
    return [{ tag: 'h2[data-chapter-title]' }];
  },
  renderHTML({ HTMLAttributes }) {
    return ['h2', mergeAttributes(HTMLAttributes, { 'data-chapter-title': 'true', class: 'book-chapter-title-block' }), 0];
  },
});

/* A quote's attribution, as a property of the quote.

   It was only ever available through the Pull quote template, which inserts the
   line as a SEPARATE italic paragraph underneath. That paragraph is an ordinary
   block: it can be dragged away from its quote, left behind when the quote
   moves, or paginated onto the next page on its own, and nothing in the document
   says the two belong together.

   The markup is the part worth being careful about. The HTML spec puts
   attribution OUTSIDE the blockquote — a blockquote's content is the quoted
   words, and a name is not something the source said — and the construction that
   associates the two is a <figure> with a <figcaption>. The <cite> element is
   deliberately NOT used: it marks the title of a work, never a person's name,
   and the cite="" attribute is ignored by every reading system, so emitting it
   would be decoration.

   Empty attribution renders a bare <blockquote>, byte-for-byte what it was
   before this existed — the same rule the image caption follows, and what keeps
   every quote already in a saved book unchanged. */
const QUOTE_FIGURE_CLASS = 'book-quote-figure';
const QUOTE_ATTRIBUTION_CLASS = 'book-quote-attribution';

const AttributedBlockquote = Blockquote.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      attribution: {
        default: '',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-attribution') ?? '',
        // Written by renderHTML below, which builds both tags itself.
        renderHTML: () => ({}),
      },
    };
  },
  parseHTML() {
    return [
      /* The figcaption is a rendering of the attribute, not content. Without
         this it would parse back as a loose paragraph inside the figure on the
         next load, so every save would print the attribution twice — once from
         the attribute and once from the stray paragraph. */
      { tag: `figcaption.${QUOTE_ATTRIBUTION_CLASS}`, ignore: true },
      { tag: 'blockquote' },
    ];
  },
  renderHTML({ HTMLAttributes, node }) {
    const attribution = String(node.attrs.attribution ?? '');
    if (!attribution) return ['blockquote', mergeAttributes(HTMLAttributes), 0];
    return [
      'figure',
      { class: QUOTE_FIGURE_CLASS },
      ['blockquote', mergeAttributes(HTMLAttributes, { 'data-attribution': attribution }), 0],
      /* contenteditable="false" because this text is not in the document. On the
         canvas it sits inside a contenteditable region, and without this a click
         lands a caret in text ProseMirror has no node for. */
      ['figcaption', { class: QUOTE_ATTRIBUTION_CLASS, contenteditable: 'false' }, attribution],
    ];
  },
});

/* A glossary — terms and what they mean.

   Called "Glossary" everywhere a person sees it, never "definition list": the
   HTML name describes the markup, and an author is adding a key-terms box, not a
   <dl>. The old editor's tile is called Definition List and ships Bootstrap's own
   demo content inside it.

   Deliberately small. Vellum and Atticus have no glossary at all, so this is not
   a gap we are behind on; the one tool that does — Pressbooks — works a different
   way entirely, tagging terms through the manuscript and GENERATING the list. That
   is a textbook feature. A lead magnet wants a box of terms, so this is a box of
   terms.

   The markup is a <dl> inside a section carrying role="doc-glossary". That role is
   the part that does real work for assistive technology; the EPUB Dictionaries and
   Glossaries vocabulary is deliberately NOT used, because current reading systems
   give it no accessibility benefit and it exists to serve look-up dictionaries. */
const GLOSSARY_CLASS = 'book-glossary';

const GlossaryTerm = Node.create({
  name: 'glossaryTerm',
  content: 'inline*',
  defining: true,
  parseHTML() { return [{ tag: 'dt' }]; },
  renderHTML({ HTMLAttributes }) { return ['dt', mergeAttributes(HTMLAttributes), 0]; },
});

const GlossaryDefinition = Node.create({
  name: 'glossaryDefinition',
  content: 'inline*',
  defining: true,
  parseHTML() { return [{ tag: 'dd' }]; },
  renderHTML({ HTMLAttributes }) { return ['dd', mergeAttributes(HTMLAttributes), 0]; },
});

const GlossaryBlock = Node.create({
  name: 'glossaryBlock',
  group: 'block',
  /* Pairs, enforced by the schema rather than by the UI. A <dl> whose last entry
     is a term with no definition is both invalid and meaningless, and making the
     content model say so means no keystroke can produce one. */
  content: '(glossaryTerm glossaryDefinition)+',
  defining: true,
  isolating: true,
  /* The <dl> is the node; the <section> around it is skipped, not matched.
     Matching both made the section a glossaryBlock and then the <dl> inside it a
     second one — which the content model forbids, so the whole thing parsed to an
     empty block and ProseMirror rejected it ("Invalid content for node
     glossaryBlock"). Skipping the wrapper parses straight through to the list,
     and renderHTML puts the section (and its role) back on the way out.
     The bare `dl` rule also means a glossary pasted in from elsewhere lands as
     one rather than as loose paragraphs. */
  parseHTML() { return [{ tag: `section.${GLOSSARY_CLASS}`, skip: true }, { tag: 'dl' }]; },
  renderHTML({ HTMLAttributes }) {
    return [
      'section',
      mergeAttributes(HTMLAttributes, { class: GLOSSARY_CLASS, role: 'doc-glossary' }),
      ['dl', {}, 0],
    ];
  },
  addKeyboardShortcuts() {
    return {
      /* Enter moves on rather than splitting: from a term to its definition, and
         from a definition to the next term. A glossary is a list of pairs, so the
         useful next thing is always the other half or the next entry — the same
         bargain a table makes with Tab. */
      Enter: ({ editor }) => {
        const { $from, empty } = editor.state.selection;
        if (!empty) return false;
        const parent = $from.parent.type.name;
        if (parent === 'glossaryTerm') {
          return editor.commands.setTextSelection($from.after() + 1);
        }
        if (parent === 'glossaryDefinition') {
          /* At the end of the last definition, Enter adds a new entry. Anywhere
             else it steps to the next term, so you can walk an existing glossary
             with one key. */
          const afterDef = $from.after();
          const grand = $from.node(-1);
          const isLast = afterDef >= $from.before(-1) + grand.nodeSize - 1;
          if (!isLast) return editor.commands.setTextSelection(afterDef + 1);
          return editor.chain()
            .insertContentAt(afterDef, { type: 'glossaryTerm' })
            .insertContentAt(afterDef + 2, { type: 'glossaryDefinition' })
            .setTextSelection(afterDef + 1)
            .run();
        }
        return false;
      },
    };
  },
});

/* ── Forms ──────────────────────────────────────────────────────────────────
   The blocks a reader fills in. Three tiles, one category: a question with
   space to answer, a question with a set to pick from, and a checklist.

   Print-first on purpose. Ruled lines and tick-boxes are for a page someone
   prints or marks up on screen, which is why these sit above the video/audio
   tail in the Elements index rather than beside the link-shaped blocks in
   Interactive. The parked interactive-PDF export is what would one day make
   them genuinely fillable; nothing here assumes it exists.

   Measurements are researched, not picked: workbook guidance puts writing-line
   spacing at 8-10mm (ours is 8.7mm, the wide-ruled figure — college-ruled 7.1mm
   is for continuous prose, not occasional workbook writing) and the rule itself
   at a light grey hairline rather than a full-strength line. Default five lines,
   because the named failure mode in every workbook critique is "beautiful
   layouts, but very little space to actually write". */
const QUESTION_CLASS = 'book-question';
const CHOICE_CLASS = 'book-choice';

type AnswerSpace = 'lines' | 'numbered' | 'box';
const ANSWER_SPACES: { id: AnswerSpace; label: string }[] = [
  { id: 'lines', label: 'Lines' },
  /* The "List three things you…" case. It is a setting rather than its own tile
     because the only difference is a number at the head of each rule — and a
     tile called "List" would collide with the bulleted and numbered lists the
     text toolbar already owns. */
  { id: 'numbered', label: 'Numbered lines' },
  { id: 'box', label: 'Box' },
];
/* 29px is 8.7mm at this page's own scale — 720px to 8.5in is ~84.7px/in, NOT
   CSS's 96dpi. The same correction the QR module floor needed; a canvas pixel
   here is ~0.30mm. Shared with the stylesheet below so the ruled lines and a
   box sized in lines can never drift apart. */
const QUESTION_LINE_PX = 29;
const QUESTION_LINES_DEFAULT = 5;
const QUESTION_LINES_MAX = 20;

type ChoiceMarker = 'circle' | 'box' | 'scale';
/* The survey tools' own words, not ours. The useful finding behind them: the
   industry's name for single-select IS "multiple choice" — Google Forms,
   SurveyMonkey and Qualtrics all use it that way — which is why our TILE is
   called that and why these three values cannot reuse the phrase. Qualtrics has
   the same collision and resolves it exactly like this: the type is Multiple
   Choice, the setting is Single Answer / Multiple Answer.
   "Rating scale" over a bare "Scale", which in an editor full of sizes could be
   read as one; it is what Qualtrics and SurveyMonkey both call it. */
const CHOICE_MARKERS: { id: ChoiceMarker; label: string }[] = [
  { id: 'circle', label: 'Single answer' },
  { id: 'box', label: 'Multiple answers' },
  { id: 'scale', label: 'Rating scale' },
];

const QUESTION_GAP_PX = 10;
const QUESTION_RULE_HEX = '#C7CDD5';

function clampNum(n: unknown, min: number, max: number, fallback: number): number {
  /* The null test is load-bearing: `Number(null)` is 0, not NaN, so an attribute
     absent from the markup — which is every block inserted from the tile, since
     the tile only writes the two attributes it means to set — came back as 0 and
     was clamped to the MINIMUM instead of falling back to the default. Line
     spacing shipped at 16px against a researched default of 29. */
  if (n === null || n === undefined || n === '') return fallback;
  const v = Math.round(Number(n));
  if (!Number.isFinite(v)) return fallback;
  return Math.max(min, Math.min(max, v));
}

/* Last-used settings for a new answer space. Set eight lines at 16px once and
   every question you add after it arrives that way — the behaviour every design
   tool has for its drawing tools, and the alternative is re-setting the same two
   numbers on every question in a workbook.

   Hooked into the attributes' own parseHTML rather than into the insert path:
   renderHTML always writes every attribute, so a block that already exists in a
   document carries explicit values and is untouched by this. The only markup
   that arrives WITHOUT them is the insert tile, which is exactly the case that
   should pick up what you last used. Nothing here can change an existing book.

   Kept in localStorage, under its own key rather than in the document: this is a
   preference of the person drawing, not a property of the book, and it should
   follow them into the next one. */
const FORM_PREFS_KEY = 'designrr-book-form-defaults';
const FORM_PREFS_FALLBACK: QuestionLook = {
  space: 'lines',
  lines: QUESTION_LINES_DEFAULT,
  spacing: QUESTION_LINE_PX,
  gap: QUESTION_GAP_PX,
  color: QUESTION_RULE_HEX,
  boxW: 0,
  choiceBoxW: 0,
  choiceGap: QUESTION_GAP_PX,
};
let formPrefsCache: QuestionLook | null = null;

function formPrefs(): QuestionLook {
  if (formPrefsCache) return formPrefsCache;
  let stored: QuestionLook = FORM_PREFS_FALLBACK;
  if (typeof window !== 'undefined') {
    try {
      const raw = window.localStorage.getItem(FORM_PREFS_KEY);
      // Every field is re-validated on the way in: this is the one input to the
      // schema that a person can edit by hand, and a bad number here would reach
      // renderHTML as an inline style.
      if (raw) stored = questionLook(JSON.parse(raw) as Record<string, unknown>);
    } catch { /* private mode, cleared storage, bad JSON — fall back and carry on */ }
  }
  formPrefsCache = stored;
  return stored;
}

function rememberFormPrefs(patch: Partial<QuestionLook>) {
  formPrefsCache = questionLook({ ...formPrefs(), ...patch } as unknown as Record<string, unknown>);
  if (typeof window === 'undefined') return;
  try { window.localStorage.setItem(FORM_PREFS_KEY, JSON.stringify(formPrefsCache)); } catch { /* non-fatal, like the autosave checkpoint's own catch */ }
}

function questionLook(attrs: Record<string, unknown>): QuestionLook {
  return {
    space: (ANSWER_SPACES.some((a) => a.id === attrs.space) ? attrs.space : 'lines') as AnswerSpace,
    lines: clampQuestionLines(attrs.lines),
    spacing: clampNum(attrs.spacing, 16, 60, QUESTION_LINE_PX),
    gap: clampNum(attrs.gap, 0, 48, QUESTION_GAP_PX),
    color: String(attrs.color ?? QUESTION_RULE_HEX),
    /* 0 is a real value here — fill the column — so it is let through rather
       than clamped up to the minimum a FIXED width would have.
       Named boxW and written as data-w because that is the contract every
       resizable block in this editor already uses, and it is what lets the drag
       handles commit to this node without a special case. */
    boxW: Number(attrs.boxW) > 0 ? clampNum(attrs.boxW, QUESTION_WIDTH_MIN, QUESTION_WIDTH_MAX, 0) : 0,
    choiceBoxW: Number(attrs.choiceBoxW) > 0 ? clampNum(attrs.choiceBoxW, QUESTION_WIDTH_MIN, QUESTION_WIDTH_MAX, 0) : 0,
    choiceGap: clampNum(attrs.choiceGap, 0, 48, QUESTION_GAP_PX),
  };
}

function clampQuestionLines(n: unknown): number {
  const v = Math.round(Number(n));
  if (!Number.isFinite(v)) return QUESTION_LINES_DEFAULT;
  return Math.max(1, Math.min(QUESTION_LINES_MAX, v));
}

/* The answer space is STATIC dom beside the content hole, not content: a reader
   writes on it, an author never types in it. contenteditable="false" is what
   stops a stray click putting a caret between two rules, and the parse rule
   below reads only the prompt back, so none of this can re-enter the document
   as empty paragraphs. */
interface QuestionLook { space: AnswerSpace; lines: number; spacing: number; gap: number; color: string; boxW: number;
  /* The choice block's own two numbers. Separate fields rather than a shared
     width, because narrowing a question says nothing about how wide you want
     your next checklist — they are different objects that happen to share a
     panel shape. Marker is deliberately NOT remembered: it is what the TILE
     means, and remembering it would make Multiple choice and Checklist drift
     into each other. */
  choiceBoxW: number; choiceGap: number }
/* 0 means fill the column. A real number is a max-width in px — the prompt and
   the lines narrow TOGETHER, which is the whole argument for putting this on the
   container rather than on the answer space: a full-width question over
   half-width lines is a mistake the panel should not make available. */
const QUESTION_WIDTH_MIN = 120;
const QUESTION_WIDTH_MAX = 720;

/* Written as inline styles rather than classes, because these are per-block
   numbers the stylesheet cannot know — and an inline literal is the one form
   that survives every path out of here, including the EPUB, which has no :root
   and no copy of this block's attributes. The class stays on for the defaults. */
function answerSpaceDom(look: QuestionLook, attrs: Record<string, unknown> = {}): unknown {
  const { space, lines, spacing, gap, color } = look;
  const own = (cls: string, style: string) => mergeAttributes(attrs, {
    'data-answer-space': 'true', class: cls, contenteditable: 'false', style,
  });
  if (space === 'box') {
    return ['div', own('book-question-box', `min-height:${lines * spacing}px;border-color:${color};margin-top:${gap}px`)];
  }
  const rules: unknown[] = [];
  for (let i = 0; i < lines; i += 1) {
    const style = `height:${spacing}px;line-height:${spacing}px;border-bottom-color:${color}`;
    rules.push(space === 'numbered'
      /* The number is real text on the rule, not a CSS counter or generated
         content: ::before and counters are the first things KF8 and the older
         EPUB renderers drop, and a numbered list whose numbers vanish is worse
         than one that never had them. */
      ? ['div', { class: 'book-question-rule', style }, ['span', { class: 'book-question-n' }, `${i + 1}.`]]
      : ['div', { class: 'book-question-rule', style }]);
  }
  return ['div', own('book-question-space', `margin-top:${gap}px`), ...rules];
}

/* The answer space is its OWN node, not decoration drawn inside the question.
   That is what makes the question a two-part object you can drill into: one
   click takes the whole thing (where the gap between the two halves lives), a
   second takes either the prompt — ordinary text, ordinary text panel — or the
   space itself, which has its own properties and no text at all. Drawn as
   decoration it could not be selected, so the biggest part of the block was
   dead to the pointer and its rules were only reachable through the sentence
   above them. */
const AnswerSpaceBlock = Node.create({
  name: 'answerSpaceBlock',
  group: 'block',
  // Nothing inside it is text: a reader writes here, an author never types here.
  atom: true,
  selectable: true,
  addAttributes() {
    return {
      space: {
        default: 'lines' as AnswerSpace,
        parseHTML: (el: HTMLElement) => {
          const s = el.getAttribute('data-space');
          return ANSWER_SPACES.some((a) => a.id === s) ? s : 'lines';
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-space': String(attrs.space ?? 'lines') }),
      },
      lines: {
        default: QUESTION_LINES_DEFAULT,
        parseHTML: (el: HTMLElement) => clampQuestionLines(el.getAttribute('data-lines')),
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-lines': String(clampQuestionLines(attrs.lines)) }),
      },
      /* How far apart the rules sit. The default is the researched 8.7mm; the
         range stops at 16 because a rule closer than that is not a writing line
         any more, and at 60 because past that one line eats the page. */
      spacing: {
        default: QUESTION_LINE_PX,
        parseHTML: (el: HTMLElement) => clampNum(el.getAttribute('data-spacing'), 16, 60, QUESTION_LINE_PX),
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-spacing': String(clampNum(attrs.spacing, 16, 60, QUESTION_LINE_PX)) }),
      },
      /* The air between the question and the first place to answer it. Stored
         here rather than on the question, because it renders as this element's
         own margin and an attribute that has to be copied into a sibling to take
         effect is an attribute in the wrong place. The panel that offers it is
         still the container's — see QuestionFields. */
      gap: {
        default: QUESTION_GAP_PX,
        parseHTML: (el: HTMLElement) => clampNum(el.getAttribute('data-gap'), 0, 48, QUESTION_GAP_PX),
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-gap': String(clampNum(attrs.gap, 0, 48, QUESTION_GAP_PX)) }),
      },
      color: {
        default: QUESTION_RULE_HEX,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-color') || QUESTION_RULE_HEX,
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-color': String(attrs.color ?? QUESTION_RULE_HEX) }),
      },
    };
  },
  parseHTML() { return [{ tag: 'div[data-answer-space]' }]; },
  renderHTML({ HTMLAttributes, node }) {
    return answerSpaceDom(questionLook(node.attrs), HTMLAttributes) as DOMOutputSpec;
  },
});

const QuestionBlock = Node.create({
  name: 'questionBlock',
  group: 'block',
  /* One paragraph then the answer space, in that order and nothing else. The
     prompt cannot split into two paragraphs and leave an orphan line above the
     rules, and the space cannot be deleted away leaving a question with nowhere
     to answer it — both guaranteed by the content model rather than by the UI. */
  content: 'paragraph answerSpaceBlock',
  defining: true,
  isolating: true,
  addAttributes() {
    return {
      boxW: {
        default: 0,
        /* Absent from the insert tile on purpose, so a new question takes the
           width you last used — same mechanism as the answer space's own
           attributes. See formPrefs. */
        parseHTML: (el: HTMLElement) => {
          const raw = el.getAttribute('data-w');
          if (raw === null || raw === '') return formPrefs().boxW;
          return Number(raw) > 0 ? clampNum(raw, QUESTION_WIDTH_MIN, QUESTION_WIDTH_MAX, 0) : 0;
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-w': String(Number(attrs.boxW) || 0) }),
      },
    };
  },
  parseHTML() { return [{ tag: 'div[data-question]' }]; },
  renderHTML({ HTMLAttributes, node }) {
    const w = Number(node.attrs.boxW) || 0;
    return ['div', mergeAttributes(HTMLAttributes, {
      'data-question': 'true',
      class: QUESTION_CLASS,
      // A literal px max-width, not a class: the number is per block and this
      // string has to survive into the EPUB, which has no copy of these attrs.
      ...(w > 0 ? { style: `max-width:${w}px` } : null),
    }), 0];
  },
});

/* The options are their own node for the same reason the answer space is: it
   makes the block a two-part object you can drill into. One click takes the whole
   thing — where its width and the gap under the prompt live — and the next takes
   either the prompt or the options, which own what KIND of answer they are.
   It wraps the editor's own bulletList rather than replacing it, so Enter,
   Backspace, Tab and paste all still behave the way every other list in the book
   does. */
const OptionListBlock = Node.create({
  name: 'optionListBlock',
  group: 'block',
  content: 'bulletList',
  defining: true,
  isolating: true,
  selectable: true,
  addAttributes() {
    return {
      marker: {
        default: 'circle' as ChoiceMarker,
        parseHTML: (el: HTMLElement) => {
          const m = el.getAttribute('data-marker');
          return CHOICE_MARKERS.some((c) => c.id === m) ? m : 'circle';
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-marker': String(attrs.marker ?? 'circle') }),
      },
      // The air under the prompt. Same property as the question's, on the same
      // reasoning: it renders as this element's own margin, so it lives here.
      gap: {
        default: QUESTION_GAP_PX,
        parseHTML: (el: HTMLElement) => {
          const raw = el.getAttribute('data-gap');
          return raw === null || raw === '' ? formPrefs().choiceGap : clampNum(raw, 0, 48, QUESTION_GAP_PX);
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-gap': String(clampNum(attrs.gap, 0, 48, QUESTION_GAP_PX)) }),
      },
    };
  },
  parseHTML() { return [{ tag: 'div[data-option-list]' }]; },
  renderHTML({ HTMLAttributes, node }) {
    const gap = clampNum(node.attrs.gap, 0, 48, QUESTION_GAP_PX);
    return ['div', mergeAttributes(HTMLAttributes, {
      'data-option-list': 'true',
      class: `${CHOICE_CLASS}-options`,
      style: `margin-top:${gap}px`,
    }), 0] as unknown as DOMOutputSpec;
  },
});

const ChoiceBlock = Node.create({
  name: 'choiceBlock',
  group: 'block',
  /* The prompt is OPTIONAL here, unlike the question's. A checklist is a list of
     things to do, not a question with answers — its intro, when it wants one, is
     ordinary prose that belongs above the block where it can be a heading or
     carry a link, not a slot inside it. A multiple choice ships with the prompt
     because there the question and its answers really are one object: narrow it
     or move it and both have to travel.
     Optional rather than absent, so the same node serves both tiles and switching
     answer type never has to throw a sentence away. */
  content: 'paragraph? optionListBlock',
  defining: true,
  isolating: true,
  addAttributes() {
    return {
      boxW: {
        default: 0,
        parseHTML: (el: HTMLElement) => {
          const raw = el.getAttribute('data-w');
          if (raw === null || raw === '') return formPrefs().choiceBoxW;
          return Number(raw) > 0 ? clampNum(raw, QUESTION_WIDTH_MIN, QUESTION_WIDTH_MAX, 0) : 0;
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-w': String(Number(attrs.boxW) || 0) }),
      },
    };
  },
  parseHTML() { return [{ tag: 'div[data-choice]' }]; },
  renderHTML({ HTMLAttributes, node }) {
    const w = Number(node.attrs.boxW) || 0;
    return ['div', mergeAttributes(HTMLAttributes, {
      'data-choice': 'true',
      class: CHOICE_CLASS,
      ...(w > 0 ? { style: `max-width:${w}px` } : null),
    }), 0] as unknown as DOMOutputSpec;
  },
});

const Callout = Node.create({
  name: 'callout',
  group: 'block',
  content: 'block+',
  defining: true,
  addAttributes() {
    return {
      // Old content wrote data-callout="true" with no type; that parses to the
      // default rather than to a broken class, so existing books keep rendering
      // exactly as they did.
      calloutType: {
        default: 'note',
        parseHTML: (el: HTMLElement) => {
          const t = el.getAttribute('data-callout-type');
          return CALLOUT_TYPES.some((c) => c.id === t) ? t : 'note';
        },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-callout-type': String(attrs.calloutType ?? 'note') }),
      },
      /* A custom accent, overriding calloutType's preset. Written as a real
         inline style rather than another class, so it survives every path the
         html takes out of here — Preview, PDF, EPUB — none of which carry this
         editor's injected <style> block. Unset (the default) leaves the preset
         class to do the work, so every book saved before this keeps rendering
         byte-for-byte as it did. */
      accentColor: {
        default: null,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-callout-color'),
        renderHTML: (attrs: Record<string, unknown>) => {
          const c = attrs.accentColor;
          if (typeof c !== 'string' || !c) return {};
          return { 'data-callout-color': c, style: calloutCustomStyle(c) };
        },
      },
    };
  },
  parseHTML() {
    return [{ tag: 'div[data-callout]' }];
  },
  renderHTML({ HTMLAttributes, node }) {
    const t = (node.attrs.calloutType as CalloutType) ?? 'note';
    return ['div', mergeAttributes(HTMLAttributes, { 'data-callout': 'true', class: `book-callout book-callout--${t}` }), 0];
  },
});

/* ProseMirror's live EditorView builds real DOM via plain `document.createElement`,
   which puts inline <svg>/<rect>/<path> tags in the HTML namespace instead of the SVG
   one — the browser then renders them at 0×0 (invisible), same as any unknown custom
   element. The exported/serialized HTML string doesn't have this problem (the browser's
   *native* HTML parser correctly foreign-content-switches into the SVG namespace when
   that string is later parsed, e.g. by Preview's dangerouslySetInnerHTML) — only the
   interactive canvas needs help, via a NodeView that sets innerHTML instead of building
   nodes imperatively, so the native parser does the namespace switch for us there too. */
function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/* One normaliser for every place a URL gets typed — the text link's popover and
   the button's inspector — so the two can't disagree about what a bare
   "example.com" means. `#`, `/`, mailto: and tel: pass through untouched: an
   in-book anchor must not be mangled into https://#section-2, and a scheme that
   isn't http is still a valid destination. Everything else gets https://,
   because a bare host in an href resolves relative to the current document and
   from inside an EPUB that points at nothing. */
function normaliseHref(raw: string): string {
  const href = (raw ?? '').trim();
  if (!href) return '';
  return /^(https?:|mailto:|tel:|#|\/)/i.test(href) ? href : `https://${href}`;
}

/* A small vector shape/icon, inserted as a unit. Every competitor with real content
   authoring (Designrr's own "Artwork & shapes" rail, Flipsnack, Visme) treats this as
   a core primitive. (QR/forms/jumbotron were excluded from an earlier pass of this
   editor as "marketing-widget sprawl" — reversed below at explicit request, since old
   Designrr shipped exactly these as core Elements, not marketing extras.) The visual
   is fully derived from attrs at insert time, so parseHTML only needs to read data-*
   back — no arbitrary markup to preserve. */
const SHAPE_MIN_PX = 24;
const SHAPE_DEFAULT_PX = 96;

/* Every visual property of a shape in one place, feeding the node view (live
   canvas) and renderHTML (getHTML, and every export downstream) from the same
   values — the split ShapeBlock already used for `d`, widened now that there are
   eight of them. */
interface ShapeAttrs extends ShapeGeom {
  color: string; borderWidth: number; borderColor: string; borderStyle: string;
  boxW: number; boxH: number; lockAspect: boolean; locked: boolean;
}
function shapeSvg(a: ShapeAttrs): { viewBox: string; path: string; fill: string; stroke: string; strokeWidth: string; dash: string; cap: string } {
  /* The dash is measured in the same viewBox units the stroke width already is,
     so it's derived from that scaled number rather than from the raw px weight —
     otherwise a dashed 2px border on a 300px shape would draw one dash. */
  const scaled = a.borderWidth > 0 ? (a.borderWidth * SHAPE_VB) / Math.max(SHAPE_MIN_PX, Math.min(a.boxW || SHAPE_DEFAULT_PX, a.boxH || SHAPE_DEFAULT_PX)) : 0;
  const dash = strokeDash(strokeStyleOf(a.borderStyle), scaled);
  return {
    dash: dash.strokeDasharray ?? '',
    cap: dash.strokeLinecap ?? '',
    // preserveAspectRatio is switched off by the caller: a shape you drag wider
    // should get wider, the way a rectangle does in any design tool, not sit
    // letterboxed in the middle of its own box.
    viewBox: `0 0 ${SHAPE_VB} ${SHAPE_VB}`,
    path: shapePath(a),
    fill: a.color,
    stroke: a.borderWidth > 0 ? a.borderColor : 'none',
    // The stroke is drawn in viewBox units, so it has to be scaled back out of
    // the box's own pixel size or a 2px border on a 300px shape renders as 25px.
    strokeWidth: a.borderWidth > 0 ? String(scaled) : '0',
  };
}

const ShapeBlock = Node.create({
  name: 'shapeBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    const num = (name: string, fallback: number) => ({
      default: fallback,
      parseHTML: (el: HTMLElement) => {
        const n = Number(el.getAttribute(`data-${name}`));
        return Number.isFinite(n) && n >= 0 ? n : fallback;
      },
      renderHTML: () => ({}),
    });
    return {
      /* No data-kind means content written before shapes were parametric, so it
         falls back to 'path' and keeps rendering the literal d it was saved with. */
      kind: {
        default: 'path' as ShapeKind,
        parseHTML: (el: HTMLElement) => (el.getAttribute('data-kind') as ShapeKind) || 'path',
        renderHTML: () => ({}),
      },
      d: { default: '' },
      sides: num('sides', 4),
      points: num('points', 5),
      starRatio: num('ratio', 0.382),
      cornerRadius: num('radius', 0),
      color: { default: SHAPE_DEFAULT_COLOR },
      borderWidth: num('bw', 0),
      borderColor: { default: INK, parseHTML: (el: HTMLElement) => el.getAttribute('data-bc') || INK, renderHTML: () => ({}) },
      borderStyle: { default: 'solid', parseHTML: (el: HTMLElement) => el.getAttribute('data-bs') || 'solid', renderHTML: () => ({}) },
      boxW: num('w', 0),
      boxH: num('h', 0),
      // Off by default: a shape is the one object you genuinely want to stretch —
      // a rectangle into a band, a line into a rule.
      lockAspect: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-lock-aspect') === 'true',
        renderHTML: () => ({}),
      },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-shape]',
      getAttrs: (el) => {
        const e = el as HTMLElement;
        const n = (name: string, fb: number) => {
          const v = Number(e.getAttribute(`data-${name}`));
          return Number.isFinite(v) && v >= 0 ? v : fb;
        };
        return {
          kind: (e.getAttribute('data-kind') as ShapeKind) || 'path',
          d: e.getAttribute('data-d') || '',
          sides: n('sides', 4),
          points: n('points', 5),
          starRatio: n('ratio', 0.382),
          cornerRadius: n('radius', 0),
          color: e.getAttribute('data-color') || SHAPE_DEFAULT_COLOR,
          borderWidth: n('bw', 0),
          borderColor: e.getAttribute('data-bc') || INK,
          borderStyle: e.getAttribute('data-bs') || 'solid',
          boxW: n('w', 0),
          boxH: n('h', 0),
          lockAspect: e.getAttribute('data-lock-aspect') === 'true',
          locked: e.getAttribute('data-locked') === 'true',
        };
      },
    }];
  },
  renderHTML({ node }) {
    const a = node.attrs as unknown as ShapeAttrs;
    const svg = shapeSvg(a);
    const w = a.boxW || SHAPE_DEFAULT_PX;
    const h = a.boxH || SHAPE_DEFAULT_PX;
    return ['div', {
      'data-shape': 'true', 'data-kind': a.kind, 'data-d': a.d, 'data-viewbox': svg.viewBox,
      'data-color': a.color, 'data-sides': String(a.sides), 'data-points': String(a.points),
      'data-ratio': String(a.starRatio), 'data-radius': String(a.cornerRadius),
      'data-bw': String(a.borderWidth), 'data-bc': a.borderColor,
      ...(strokeStyleOf(a.borderStyle) !== 'solid' ? { 'data-bs': a.borderStyle } : {}),
      ...(a.lockAspect ? { 'data-lock-aspect': 'true' } : {}),
      'data-w': String(w), 'data-h': String(h),
      ...(a.locked ? { 'data-locked': 'true' } : {}),
      class: 'book-shape', style: `width:${w}px;height:${h}px`,
    },
      ['svg', {
        viewBox: svg.viewBox, width: '100%', height: '100%', preserveAspectRatio: 'none',
        fill: svg.fill, stroke: svg.stroke, 'stroke-width': svg.strokeWidth,
        ...(svg.dash ? { 'stroke-dasharray': svg.dash } : {}),
        ...(svg.cap ? { 'stroke-linecap': svg.cap } : {}),
      },
        ['path', { d: svg.path }]],
    ];
  },
  addNodeView() {
    return ({ node, getPos, editor }) => {
      const dom = document.createElement('div');
      dom.contentEditable = 'false';
      const art = document.createElement('div');
      art.className = 'book-shape-art';
      let selected = false;

      const paint = (n: typeof node) => {
        const a = n.attrs as unknown as ShapeAttrs;
        const svg = shapeSvg(a);
        const w = a.boxW || SHAPE_DEFAULT_PX;
        const h = a.boxH || SHAPE_DEFAULT_PX;
        dom.className = 'book-shape';
        dom.setAttribute('data-shape', 'true');
        dom.setAttribute('data-kind', a.kind);
        dom.setAttribute('data-color', a.color);
        dom.style.width = `${w}px`;
        dom.style.height = `${h}px`;
        art.innerHTML = `<svg viewBox="${svg.viewBox}" width="100%" height="100%" preserveAspectRatio="none" fill="${escapeHtml(svg.fill)}" stroke="${escapeHtml(svg.stroke)}" stroke-width="${svg.strokeWidth}"${svg.dash ? ` stroke-dasharray="${escapeHtml(svg.dash)}"` : ''}${svg.cap ? ` stroke-linecap="${escapeHtml(svg.cap)}"` : ''}><path d="${escapeHtml(svg.path)}"></path></svg>`;
      };

      const liveAttrs = (): ShapeAttrs | null => {
        if (typeof getPos !== 'function') return null;
        const pos = getPos();
        if (pos == null) return null;
        const live = editor.state.doc.nodeAt(pos);
        return live && live.type.name === 'shapeBlock' ? (live.attrs as unknown as ShapeAttrs) : null;
      };

      const markSelected = () => {
        dom.classList.toggle('ProseMirror-selectednode', selected);
        // Same three conditions the photo's handles render under: selected,
        // editable, unlocked.
        handles.style.display = selected && editor.isEditable && !liveAttrs()?.locked ? 'block' : 'none';
      };

      /* The paths are drawn in a square viewBox with preserveAspectRatio="none",
         so a non-uniform drag is exactly what the renderer is built to express —
         which is why the proportions lock defaults OFF here, unlike a photo. */
      const handles = buildResizeHandles((corner, e) => {
        const a = liveAttrs();
        if (!a || a.locked) return;
        dragResize({
          box: dom,
          corner,
          event: e,
          lockAspect: !!a.lockAspect,
          maxW: dom.parentElement?.clientWidth ?? 0,
          commit: (w, h) => {
            if (typeof getPos !== 'function') return;
            const at = getPos();
            if (at == null) return;
            // Focus first and keep the shape selected — the handles swallow
            // their own pointer events, so without this the drag never focuses
            // the view and its undo step is unreachable by keyboard.
            editor.view.focus();
            editor.chain().setNodeSelection(at).updateAttributes('shapeBlock', { boxW: w, boxH: h }).run();
          },
        });
      });

      paint(node);
      dom.appendChild(art);
      dom.appendChild(handles);
      markSelected();

      return {
        dom,
        // Repaint in place rather than letting ProseMirror tear the node view
        // down and rebuild it on every attribute change — a rebuild mid-drag
        // would drop the element the resize is writing to.
        update: (updated) => {
          if (updated.type.name !== 'shapeBlock') return false;
          paint(updated);
          markSelected();
          return true;
        },
        selectNode: () => { selected = true; markSelected(); },
        deselectNode: () => { selected = false; markSelected(); },
      };
    };
  },
});

/* Video/audio embed. The one media type worth adding beyond images — present in
   Designrr's own real editor (Embed Video/Embed Audio) — kept to exactly those two,
   not the wider interactive-widget catalog (forms, shop tags) this editor avoids.

   The two halves behave differently on purpose, because the formats treat them
   differently. Audio is a core media type in EPUB 3 — any reading system that
   plays audio at all is REQUIRED to support MP3 — so a real <audio> element is
   honest: it works. Video is not a core media type, no reader has to play it, an
   e-ink screen physically can't, and a remote HTML page (a YouTube player) is the
   one resource class an EPUB may not reference at all. So a LINKED video renders
   as a poster frame wrapped in a link, the only construction that survives EPUB,
   PDF and Kindle alike. See lib/videoEmbed.ts for the full reasoning.

   An UPLOADED file is the other case, and it gets a real player: a video file in
   the container is a legal resource where a YouTube page is not, so the reason to
   hold back doesn't apply. Playback still isn't guaranteed — video has no core
   media type — so the player carries the same poster and caption inside it as
   fallback content, which is what a reader that can't play it shows instead. */
const EmbedBlock = Node.create({
  name: 'embedBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      kind: { default: 'video' },
      src: { default: '' },
      /* Resolved once when the video is chosen (provider oEmbed) rather than at
         render time: renderHTML also feeds getHTML() during export, which is
         synchronous, and a poster that had to be fetched mid-package would come
         out empty exactly when it matters. Empty falls back to the id-derived
         thumbnail, so a book saved before this existed still gets one. */
      poster: { default: '' },
      title: { default: '' },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-embed]',
      getAttrs: (el) => ({
        kind: (el as HTMLElement).getAttribute('data-kind') || 'video',
        src: (el as HTMLElement).getAttribute('data-src') || '',
        poster: (el as HTMLElement).getAttribute('data-poster') || '',
        title: (el as HTMLElement).getAttribute('data-title') || '',
        locked: (el as HTMLElement).getAttribute('data-locked') === 'true',
      }),
    }];
  },
  renderHTML({ node }) {
    const { kind, src, poster, title, locked } = node.attrs as {
      kind: string; src: string; poster: string; title: string; locked: boolean;
    };
    const lockedAttr = locked ? { 'data-locked': 'true' } : {};
    /* An uploaded file lives in IndexedDB, not in the document — `src` holds a
       reference and the playable URL is resolved from the session cache. The
       reference is repeated on the media element as `data-media` so the export
       pass can find it: by then the element's own src is a blob: URL, which means
       nothing outside this tab. */
    const uploaded = isMediaRef(src);
    const playable = uploaded ? mediaUrl(src) : src;

    if (kind === 'audio') {
      /* `controls="controls"`, not `controls="true"`. It is a boolean attribute,
         whose value in XHTML must be empty or the attribute's own name — the same
         defect the old iframe's allowfullscreen="true" had. */
      const audioAttrs = uploaded
        ? { controls: 'controls', src: playable, 'data-media': src }
        : { controls: 'controls', src: playable };
      /* Content inside <audio> is the element's intrinsic fallback, which does two
         jobs. A reader with no audio support shows it instead of nothing. And it
         is what makes a non-core format legal: EPUB requires core media types
         (MP3, MP4 audio) OR a fallback, and an uploaded WAV is neither core nor,
         without this, fallen back. */
      return ['div', { 'data-embed': 'true', 'data-kind': 'audio', 'data-src': src, ...lockedAttr, class: 'book-embed book-embed--audio' },
        ['audio', audioAttrs, ['span', { class: 'book-embed-caption' }, title || 'Audio']],
      ];
    }
    /* Re-parsed rather than trusting `src` to already be canonical: books saved
       before the picker normalised anything still hold raw watch URLs, and this
       is what converts them on load instead of leaving them broken. */
    const parsed = uploaded ? null : parseVideoUrl(src);
    const href = parsed?.watchUrl ?? src;
    const still = poster || parsed?.poster || '';
    const wrapper = {
      'data-embed': 'true', 'data-kind': 'video', 'data-src': src,
      ...(poster ? { 'data-poster': poster } : {}),
      ...(title ? { 'data-title': title } : {}),
      ...lockedAttr,
      class: still ? 'book-embed book-embed--video' : 'book-embed book-embed--video book-embed--noposter',
    };
    /* rel/target matter in the live HTML version and are inert everywhere else.
       A reading system that ignores the link entirely still shows the poster and
       the caption, which is the whole reason for building it this way. */
    const link = { href, class: 'book-embed-link', target: '_blank', rel: 'noopener noreferrer' };
    const badge = ['span', { class: 'book-embed-badge' }, ''] as const;

    /* Uploaded video: a real player, with the poster and a plain caption inside it
       as the fallback a reader without video support falls back to. No link — there
       is no page to send anyone to, the file is the content. */
    if (uploaded) {
      const videoAttrs = {
        controls: 'controls', src: playable, 'data-media': src, class: 'book-embed-video',
        ...(still ? { poster: still } : {}),
      };
      const fallbackCaption = ['span', { class: 'book-embed-caption' }, title || 'Video'] as const;
      if (!still) return ['div', wrapper, ['video', videoAttrs, fallbackCaption]];
      return ['div', wrapper, ['video', videoAttrs, ['img', { src: still, alt: '', class: 'book-embed-poster' }], fallbackCaption]];
    }

    const caption = ['span', { class: 'book-embed-caption' }, videoLinkLabel(title)] as const;
    if (!still) return ['div', wrapper, ['a', link, badge, caption]];
    return ['div', wrapper, ['a', link, ['img', { src: still, alt: '', class: 'book-embed-poster' }], badge, caption]];
  },
});

/* QR code — old Designrr's Elements rail includes one. Real, scannable output via
   the `qrcode` package's synchronous `create()` (a pure bit-matrix generator, no
   canvas/fs dependency, safe in the browser NodeView below). A 4-module quiet zone
   is added around the matrix — required by the QR spec for real scanners to lock
   on, and the old fake-pattern version had none since it was never meant to scan. */
const QR_QUIET_ZONE = 4;

/* ── QR scannability ─────────────────────────────────────────────────────────
   Two properties decide whether a printed code reads, and the block enforced
   neither: the contrast between the modules and their background, and how big
   one module ends up on paper.

   Numbers, and where they come from. ISO/IEC 18004 has scanners locate a symbol
   by the difference in REFLECTANCE between light and dark modules, and the
   widely-published print floor derived from it is a 4:1 contrast ratio — some
   houses say 3:1, some 4.5:1, so 4:1 is both the common figure and the middle
   one. For module size the guidance splits by press: ~0.25mm for offset, 0.4mm
   for inkjet and digital. A book made here is printed on demand or at home, so
   0.4mm is the honest floor. Overall, 2cm square is the usual "reliable at arm's
   length with a phone" minimum.

   Millimetres reach pixels through the book's own scale, not the CSS 96dpi
   default: PX_PER_IN here is 720/8.5 ≈ 84.7, so a canvas pixel is ~0.30mm. At
   the old fixed 84px a code stayed above the module floor up to about 63 modules
   across and fell below it after that — so a short link was always fine and a
   long one silently degraded, which is exactly the failure an author cannot see
   on screen. */
const QR_MIN_CONTRAST = 4;
const QR_MM_PER_PX = 25.4 / PX_PER_IN;
/** 0.4mm, the inkjet/digital-press module floor, in canvas pixels (~1.33). */
const QR_MIN_MODULE_PX = 0.4 / QR_MM_PER_PX;
/** The long-standing default. Above the 2cm overall minimum (~67px), so it stays
    the floor rather than being recomputed into something smaller. */
const QR_BASE_PX = 84;

/* WCAG's ratio, against the white the symbol is drawn on. The background is not
   the author's to change — renderHTML paints a white rect under the modules, so
   a dark page can't bleed through — which is what makes this a single number
   rather than a pair the author has to keep in step. */
function qrContrast(color: string): number {
  // Anything not a 6-digit hex is unmeasurable here, so it reports exactly the
  // threshold: no warning on a value this can't judge, rather than a false one.
  if (!/^#[0-9a-fA-F]{6}$/.test(color)) return QR_MIN_CONTRAST;
  return 1.05 / (relativeLuminance(color) + 0.05);
}
function qrColorSafe(color: string): boolean {
  return qrContrast(color) >= QR_MIN_CONTRAST;
}

/** Rendered size for a symbol of `total` modules: never below the default, and
    never so small that one module prints under 0.4mm. */
function qrRenderPx(total: number): number {
  return Math.max(QR_BASE_PX, Math.ceil(total * QR_MIN_MODULE_PX));
}
/** The side the symbol actually draws at: what the author dragged it to, or the
    natural size if they never did. Square either way — a QR has no other shape,
    so the box and the symbol are the same thing. */
function qrSidePx(total: number, boxW?: number): number {
  const dragged = Number(boxW) || 0;
  return dragged > 0 ? Math.round(dragged) : qrRenderPx(total);
}
/* null when there is nothing to encode, or when the text is too long to fit a
   symbol at this error-correction level. It used to substitute example.com in
   that case, which is the one QR failure an author can never catch by looking:
   the block drew a perfectly healthy code that sent every reader somewhere else.
   A blank placeholder plus a warning in the inspector is the honest answer. */
function realQrMatrix(url: string): { size: number; cells: boolean[] } | null {
  const value = (url ?? '').trim();
  if (!value) return null;
  try {
    /* Level M recovers ~15% of codewords — the standard default, and the right
       one for a symbol that now has nothing drawn on top of it. The margin is
       there for what happens to a printed page: a fold, a thumb, ink spread. */
    const qr = QRCode.create(value, { errorCorrectionLevel: 'M' });
    return { size: qr.modules.size, cells: Array.from(qr.modules.data, (v) => v === 1) };
  } catch {
    return null;
  }
}

/* What a screen reader says in place of the symbol. The destination, not the
   shape: "QR code" alone tells a blind reader there is something here they
   cannot use, which is the opposite of the point. */
function qrAltText(url: string): string {
  const host = destinationHost(url);
  return host ? `QR code — scan to open ${host}` : 'QR code';
}
const QrCodeBlock = Node.create({
  name: 'qrCodeBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      url: { default: 'https://example.com' },
      color: { default: '#15191F' },
      /* A data URI rather than a media-store reference. inlineUploadedMedia only
         rewrites <audio>/<video>, so a book-media: ref inside an SVG would export
         as a dead blob URL. The upload path downscales to 96px first, so what
         sits in the document is a few KB. */
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-qr]',
      getAttrs: (el) => {
        const box = el as HTMLElement;
        return {
          url: box.getAttribute('data-url') || '',
          color: box.getAttribute('data-color') || '#15191F',
          locked: box.getAttribute('data-locked') === 'true',
        };
      },
    }];
  },
  renderHTML({ node }) {
    const a = node.attrs as { url: string; color: string; locked: boolean; boxW?: number };
    const matrix = realQrMatrix(a.url);
    const box = {
      'data-qr': 'true', 'data-url': a.url, 'data-color': a.color,
      ...(a.locked ? { 'data-locked': 'true' } : {}),
      class: 'book-qr',
    };
    // Nothing encodable: emit the empty box rather than a square that looks
    // scannable and isn't. The editor is where that gets explained.
    if (!matrix) return ['div', box] as unknown as DOMOutputSpec;
    const { size, cells } = matrix;
    const total = size + QR_QUIET_ZONE * 2;
    const rects = cells.map((on, i) => (on
      ? ['rect', { x: (i % size) + QR_QUIET_ZONE, y: Math.floor(i / size) + QR_QUIET_ZONE, width: 1, height: 1, fill: a.color }]
      : null)).filter(Boolean);
    /* The symbol IS the link. It used to print its destination's host beneath
       itself, which no design tool does and which put a stray address on a
       printed page. The two jobs that caption was carrying are both covered
       now: a screen reader gets the alt text below, and a reader in EPUB, HTML
       or the flipbook — holding the very device that would have scanned it —
       taps the code. On paper the wrapper is simply inert. */
    return ['div', box,
      ['a', { href: normaliseHref(a.url), class: 'book-qr-link' },
        /* WCAG 1.1.1 wants the code's PURPOSE, not its appearance — a bare <svg>
           of 900 rects is announced as nothing at all. role + <title> is the pair
           that works in both EPUB readers and browsers. */
        /* Sized from the box, not from the module count alone: dragging the
           handles has to resize the SYMBOL. A fixed px symbol inside a resized
           div just sat in a bigger empty box, which is a resize that visibly
           does nothing. qrRenderPx is the natural size an un-dragged code
           takes, and the floor the inspector warns against going under. */
        ['svg', {
          viewBox: `0 0 ${total} ${total}`,
          width: String(qrSidePx(total, a.boxW)), height: String(qrSidePx(total, a.boxW)),
          role: 'img', 'aria-label': qrAltText(a.url),
        },
          ['title', {}, qrAltText(a.url)],
          ['rect', { x: 0, y: 0, width: total, height: total, fill: '#fff' }],
          ...(rects as (string | Record<string, unknown>)[][]),
        ],
      ],
    ] as unknown as DOMOutputSpec;
  },
  addNodeView() {
    return ({ node }) => {
      const a = node.attrs as { url: string; color: string };
      const matrix = realQrMatrix(a.url);
      const dom = document.createElement('div');
      dom.className = 'book-qr';
      dom.setAttribute('data-qr', 'true');
      dom.setAttribute('data-url', a.url);
      dom.setAttribute('data-color', a.color);
      dom.contentEditable = 'false';
      if (!matrix) {
        /* The author needs to SEE that there is no code, where the export simply
           leaves it out — an empty square on the canvas is what sends them to the
           panel, which names the reason. */
        dom.innerHTML = '<div style="width:' + QR_BASE_PX + 'px;height:' + QR_BASE_PX + 'px;'
          + 'border:1px dashed #C7CED8;border-radius:6px;background:#fff"></div>';
        applyBlockSize(dom, node.attrs);
        return { dom };
      }
      const { size, cells } = matrix;
      const total = size + QR_QUIET_ZONE * 2;
      const rectsHtml = cells.map((on, i) => (on
        ? `<rect x="${(i % size) + QR_QUIET_ZONE}" y="${Math.floor(i / size) + QR_QUIET_ZONE}" width="1" height="1" fill="${a.color}"></rect>`
        : '')).join('');
      const px = qrSidePx(total, Number(node.attrs.boxW) || 0);
      dom.innerHTML = `<svg viewBox="0 0 ${total} ${total}" width="${px}" height="${px}" role="img" aria-label="${escapeHtml(qrAltText(a.url))}">`
        + `<title>${escapeHtml(qrAltText(a.url))}</title>`
        + `<rect x="0" y="0" width="${total}" height="${total}" fill="#fff"></rect>${rectsHtml}</svg>`;
      applyBlockSize(dom, node.attrs);
      return { dom };
    };
  },
});

/* ── chart rendering ──────────────────────────────────────────────────────────
   Per the dataviz skill: bar/line compare magnitude or trend, so each gets one
   sequential hue (the user's own chosen colour) rather than a categorical set —
   only pie is "identity" (part-to-whole) and needs the fixed categorical palette.
   Geometry is computed once as a flat list of primitives, then rendered to either
   an HTML string (addNodeView's innerHTML, the live canvas) or a DOM output spec
   (renderHTML, what editor.getHTML() actually serializes into chapterContent/
   exported HTML) — same two-output split ShapeBlock/QrCodeBlock already use above,
   just factored through one shared geometry pass instead of hand-duplicating the
   math twice, since a chart has far more primitives than a shape's single path. */
type ChartPoint = { label: string; value: number };
type SvgPrim =
  | { tag: 'rect'; x: number; y: number; width: number; height: number; fill: string }
  | { tag: 'line'; x1: number; y1: number; x2: number; y2: number; stroke: string }
  | { tag: 'circle'; cx: number; cy: number; r: number; fill: string; ring?: string }
  | { tag: 'path'; d: string; fill?: string; stroke?: string; strokeWidth?: number }
  | { tag: 'polyline'; points: string; stroke: string }
  | { tag: 'text'; x: number; y: number; fill: string; size: number; weight?: number; anchor?: 'start' | 'middle' | 'end'; text: string };

const CHART_W = 400;
const CHART_H = 240;
// Chart-chrome tokens follow the dataviz skill's roles but reuse this app's own
// near-identical existing constants rather than a second, redundant set.
const CHART_AXIS = BORDER;
const CHART_LABEL = SLATE;
const CHART_VALUE = INK;

function relativeLuminance(hex: string): number {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}

// Round up to a "clean" tick value (1/2/5 × 10^n) — the skill's "round to clean
// numbers" rule for y-axis ticks, applied to whatever magnitude the data has.
function niceCeil(value: number): number {
  if (value <= 0) return 1;
  const pow = 10 ** Math.floor(Math.log10(value));
  const step = value / pow;
  const niceStep = step <= 1 ? 1 : step <= 2 ? 2 : step <= 5 ? 5 : 10;
  return niceStep * pow;
}

function roundedTopRectPath(x: number, y: number, w: number, h: number, r: number): string {
  const rr = Math.min(r, w / 2, Math.max(h, 0));
  if (h <= 0) return '';
  return `M${x},${y + h} L${x},${y + rr} Q${x},${y} ${x + rr},${y} L${x + w - rr},${y} Q${x + w},${y} ${x + w},${y + rr} L${x + w},${y + h} Z`;
}

function barChartGeometry(points: ChartPoint[], color: string): SvgPrim[] {
  const padL = 14, padR = 14, padT = 22, padB = 30;
  const plotW = CHART_W - padL - padR, plotH = CHART_H - padT - padB;
  const baseline = padT + plotH;
  const max = Math.max(...points.map((p) => p.value), 1);
  const band = plotW / Math.max(points.length, 1);
  const barW = Math.min(28, band * 0.55);
  const prims: SvgPrim[] = [{ tag: 'line', x1: padL, y1: baseline, x2: CHART_W - padR, y2: baseline, stroke: CHART_AXIS }];
  points.forEach((p, i) => {
    const cx = padL + band * i + band / 2;
    const h = max > 0 ? (p.value / max) * plotH : 0;
    prims.push({ tag: 'path', d: roundedTopRectPath(cx - barW / 2, baseline - h, barW, h, 4), fill: color });
    prims.push({ tag: 'text', x: cx, y: baseline - h - 7, fill: CHART_VALUE, size: 11, weight: 700, anchor: 'middle', text: String(p.value) });
    prims.push({ tag: 'text', x: cx, y: baseline + 17, fill: CHART_LABEL, size: 10, anchor: 'middle', text: p.label });
  });
  return prims;
}

function lineChartGeometry(points: ChartPoint[], color: string): SvgPrim[] {
  const padL = 30, padR = 14, padT = 18, padB = 26;
  const plotW = CHART_W - padL - padR, plotH = CHART_H - padT - padB;
  const baseline = padT + plotH;
  const niceMax = niceCeil(Math.max(...points.map((p) => p.value), 1));
  const xAt = (i: number) => (points.length <= 1 ? padL + plotW / 2 : padL + (plotW / (points.length - 1)) * i);
  const yAt = (v: number) => baseline - (v / niceMax) * plotH;
  const prims: SvgPrim[] = [];
  [0, 0.5, 1].forEach((f) => {
    const v = niceMax * f;
    const y = yAt(v);
    prims.push({ tag: 'line', x1: padL, y1: y, x2: CHART_W - padR, y2: y, stroke: CHART_AXIS });
    prims.push({ tag: 'text', x: padL - 6, y: y + 3, fill: CHART_LABEL, size: 9, anchor: 'end', text: String(Math.round(v)) });
  });
  const coords = points.map((p, i) => [xAt(i), yAt(p.value)] as const);
  prims.push({ tag: 'polyline', points: coords.map(([x, y]) => `${x},${y}`).join(' '), stroke: color });
  coords.forEach(([x, y], i) => {
    prims.push({ tag: 'circle', cx: x, cy: y, r: 4, fill: color, ring: '#fff' });
    prims.push({ tag: 'text', x, y: baseline + 16, fill: CHART_LABEL, size: 10, anchor: 'middle', text: points[i].label });
  });
  const last = coords[coords.length - 1];
  if (last) prims.push({ tag: 'text', x: last[0], y: last[1] - 10, fill: CHART_VALUE, size: 11, weight: 700, anchor: points.length > 1 ? 'end' : 'middle', text: String(points[points.length - 1].value) });
  return prims;
}

// Anything past the palette's own validated ceiling folds into a neutral "Other"
// slice, per the skill's own rule — a generated 9th hue is never the answer.
function pieChartGeometry(points: ChartPoint[]): SvgPrim[] {
  const cap = CHART_PALETTE.length;
  const shown = points.length > cap ? points.slice(0, cap - 1) : points;
  const overflow = points.length > cap ? points.slice(cap - 1).reduce((s, p) => s + p.value, 0) : 0;
  const rows = overflow > 0 ? [...shown, { label: 'Other', value: overflow }] : shown;
  const colors = rows.map((_, i) => (overflow > 0 && i === rows.length - 1 ? SLATE_HEX : CHART_PALETTE[i]));
  const total = rows.reduce((s, p) => s + p.value, 0) || 1;
  const cx = 118, cy = 120, r = 86;
  const prims: SvgPrim[] = [];
  let angle = -Math.PI / 2;
  rows.forEach((p, i) => {
    const frac = p.value / total;
    const start = angle;
    const end = angle + frac * Math.PI * 2;
    angle = end;
    const [x1, y1] = [cx + r * Math.cos(start), cy + r * Math.sin(start)];
    const [x2, y2] = [cx + r * Math.cos(end), cy + r * Math.sin(end)];
    const large = end - start > Math.PI ? 1 : 0;
    prims.push({ tag: 'path', d: `M${cx},${cy} L${x1},${y1} A${r},${r} 0 ${large} 1 ${x2},${y2} Z`, fill: colors[i], stroke: '#fff', strokeWidth: 2 });
    if (frac >= 0.06) {
      const mid = (start + end) / 2;
      const lx = cx + r * 0.62 * Math.cos(mid), ly = cy + r * 0.62 * Math.sin(mid);
      const labelColor = relativeLuminance(colors[i]) > 0.5 ? INK : '#fff';
      prims.push({ tag: 'text', x: lx, y: ly + 4, fill: labelColor, size: 11, weight: 700, anchor: 'middle', text: `${Math.round(frac * 100)}%` });
    }
  });
  // Legend — a pie always has >=2 series, so identity never rests on color alone.
  const legendX = 226;
  rows.forEach((p, i) => {
    const ly = 30 + i * 22;
    prims.push({ tag: 'rect', x: legendX, y: ly, width: 10, height: 10, fill: colors[i] });
    prims.push({ tag: 'text', x: legendX + 16, y: ly + 9, fill: CHART_VALUE, size: 11, anchor: 'start', text: p.label });
  });
  return prims;
}

function chartGeometry(chartType: 'bar' | 'line' | 'pie', points: ChartPoint[], color: string): SvgPrim[] {
  if (!points.length) return [];
  if (chartType === 'line') return lineChartGeometry(points, color);
  if (chartType === 'pie') return pieChartGeometry(points);
  return barChartGeometry(points, color);
}

function primsToSvgHtml(prims: SvgPrim[]): string {
  const parts = prims.map((p) => {
    if (p.tag === 'rect') return `<rect x="${p.x}" y="${p.y}" width="${p.width}" height="${p.height}" fill="${p.fill}"></rect>`;
    if (p.tag === 'line') return `<line x1="${p.x1}" y1="${p.y1}" x2="${p.x2}" y2="${p.y2}" stroke="${p.stroke}" stroke-width="1"></line>`;
    if (p.tag === 'circle') return `<circle cx="${p.cx}" cy="${p.cy}" r="${p.r}" fill="${p.fill}"${p.ring ? ` stroke="${p.ring}" stroke-width="2"` : ''}></circle>`;
    if (p.tag === 'polyline') return `<polyline points="${p.points}" fill="none" stroke="${p.stroke}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></polyline>`;
    if (p.tag === 'path') return `<path d="${p.d}" fill="${p.fill ?? 'none'}"${p.stroke ? ` stroke="${p.stroke}" stroke-width="${p.strokeWidth ?? 1}"` : ''}></path>`;
    return `<text x="${p.x}" y="${p.y}" fill="${p.fill}" font-size="${p.size}"${p.weight ? ` font-weight="${p.weight}"` : ''} text-anchor="${p.anchor ?? 'start'}" font-family="'Nunito Sans',sans-serif">${escapeHtml(p.text)}</text>`;
  });
  return `<svg viewBox="0 0 ${CHART_W} ${CHART_H}" width="100%">${parts.join('')}</svg>`;
}

function primsToSvgDom(prims: SvgPrim[]): unknown[] {
  const children = prims.map((p) => {
    if (p.tag === 'rect') return ['rect', { x: p.x, y: p.y, width: p.width, height: p.height, fill: p.fill }];
    if (p.tag === 'line') return ['line', { x1: p.x1, y1: p.y1, x2: p.x2, y2: p.y2, stroke: p.stroke, 'stroke-width': 1 }];
    if (p.tag === 'circle') return ['circle', { cx: p.cx, cy: p.cy, r: p.r, fill: p.fill, ...(p.ring ? { stroke: p.ring, 'stroke-width': 2 } : {}) }];
    if (p.tag === 'polyline') return ['polyline', { points: p.points, fill: 'none', stroke: p.stroke, 'stroke-width': 2, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }];
    if (p.tag === 'path') return ['path', { d: p.d, fill: p.fill ?? 'none', ...(p.stroke ? { stroke: p.stroke, 'stroke-width': p.strokeWidth ?? 1 } : {}) }];
    return ['text', { x: p.x, y: p.y, fill: p.fill, 'font-size': p.size, ...(p.weight ? { 'font-weight': p.weight } : {}), 'text-anchor': p.anchor ?? 'start', 'font-family': "'Nunito Sans',sans-serif" }, p.text];
  });
  return ['svg', { viewBox: `0 0 ${CHART_W} ${CHART_H}`, width: '100%' }, ...children];
}

/* Real, user-edited data (unlike QrCodeBlock/Wordgenie's mocked output above) —
   a chart's values don't need a backend or AI to be genuinely functional, so
   there's no reason to fake them. Bar/line use the user's own chosen accent
   colour (magnitude/trend are single-hue jobs per the dataviz skill); pie
   ignores it and uses the fixed categorical palette instead, since part-to-whole
   is an identity job and every slice needs to read as a distinct thing. */
const ChartBlock = Node.create({
  name: 'chartBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      chartType: { default: 'bar' },
      points: {
        default: [] as ChartPoint[],
        parseHTML: (el: HTMLElement) => { try { return JSON.parse(el.getAttribute('data-points') || '[]'); } catch { return []; } },
        renderHTML: (attrs: Record<string, unknown>) => ({ 'data-points': JSON.stringify(attrs.points ?? []) }),
      },
      color: { default: BLUE },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-chart]',
      getAttrs: (el) => ({
        chartType: (el as HTMLElement).getAttribute('data-type') || 'bar',
        color: (el as HTMLElement).getAttribute('data-color') || BLUE,
        locked: (el as HTMLElement).getAttribute('data-locked') === 'true',
      }),
    }];
  },
  renderHTML({ node }) {
    const { chartType, points, color, locked } = node.attrs as { chartType: 'bar' | 'line' | 'pie'; points: ChartPoint[]; color: string; locked: boolean };
    return ['div', { 'data-chart': 'true', 'data-type': chartType, 'data-color': color, ...(locked ? { 'data-locked': 'true' } : {}), class: 'book-chart' },
      primsToSvgDom(chartGeometry(chartType, points, color)) as never,
    ];
  },
  addNodeView() {
    return ({ node }) => {
      const { chartType, points, color } = node.attrs as { chartType: 'bar' | 'line' | 'pie'; points: ChartPoint[]; color: string };
      const dom = document.createElement('div');
      dom.className = 'book-chart';
      dom.setAttribute('data-chart', 'true');
      dom.contentEditable = 'false';
      dom.innerHTML = primsToSvgHtml(chartGeometry(chartType, points, color));
      applyBlockSize(dom, node.attrs);
      return { dom };
    };
  },
});

function countFootnoteRefsBefore(doc: PMNode, pos: number): number {
  let count = 0;
  doc.nodesBetween(0, pos, (n) => { if (n.type.name === 'footnoteRef') count++; });
  return count;
}

/* Inline footnote reference — the first `group: 'inline'` atom in this file
   (everything else here is block-level). Its own renderHTML never bakes in a
   number: a single node has no way to know its position among its siblings,
   so the number is always derived, never stored. Two separate derivations
   exist on purpose, matching this file's own established habit of splitting
   render logic across the live/export boundary (ChartBlock, QrCodeBlock):
   the live NodeView below counts prior footnoteRef nodes directly off the
   ProseMirror doc (always current, no stale cache), while export/Preview
   HTML (which has no JS running) gets its numbers baked in by
   applyFootnoteNumbering() in lib/footnotes.ts at render/export time. */
const FootnoteRefBlock = Node.create({
  name: 'footnoteRef',
  group: 'inline',
  inline: true,
  atom: true,
  addAttributes() {
    return { id: { default: null } };
  },
  parseHTML() {
    return [{
      tag: 'sup[data-footnote-ref]',
      getAttrs: (el) => ({ id: (el as HTMLElement).getAttribute('data-fid') }),
    }];
  },
  renderHTML({ node }) {
    return ['sup', { 'data-footnote-ref': 'true', 'data-fid': node.attrs.id, class: 'book-footnote-ref' }, '•'];
  },
  /* ⌘⌥F / Ctrl+Alt+F, the same binding Word uses. The floating bar is the
     discoverable route, but it only appears over a real selection — this is how
     you add a note from a bare caret. */
  addKeyboardShortcuts() {
    return {
      // Deferred a tick. Run inline, the caret move at the end of
      // insertFootnote lands while ProseMirror is still dispatching the key
      // event and gets mapped away again — you'd get the marker but end up
      // typing the note into the body. Off the keymap's own dispatch it sticks.
      'Mod-Alt-f': () => { const ed = this.editor; setTimeout(() => insertFootnote(ed), 0); return true; },
    };
  },
  addNodeView() {
    return ({ node, editor, getPos }) => {
      const dom = document.createElement('sup');
      dom.className = 'book-footnote-ref';
      dom.setAttribute('data-footnote-ref', 'true');
      dom.setAttribute('data-fid', node.attrs.id ?? '');
      dom.contentEditable = 'false';
      // No click handler needed — clicking an atom node already produces a
      // NodeSelection via ProseMirror's default behavior (same as every other
      // atom block in this file), which is all the selection/inspector wiring
      // below needs to pick it up.
      const render = () => {
        const pos = typeof getPos === 'function' ? getPos() : null;
        const ordinal = pos == null ? 1 : countFootnoteRefsBefore(editor.state.doc, pos) + 1;
        dom.textContent = String(ordinal);
        // "1" on its own is a meaningless accessible name — the DAISY notes
        // guidance is explicit about it. Same label the exporter writes.
        dom.setAttribute('aria-label', `Footnote ${ordinal}`);
        dom.title = `Footnote ${ordinal}`;
      };
      render();
      /* A marker's number depends on how many markers precede it, so the node's
         own `update` isn't enough — inserting marker 2 above marker 3 doesn't
         touch marker 3's node, and it would sit there still reading "2". Every
         marker recounts on every doc change instead; the count is a walk of the
         doc up to its own position, and there are never many of them. */
      const recount = () => render();
      editor.on('update', recount);
      return {
        dom,
        update: (updated) => (updated.type.name === 'footnoteRef' ? (render(), true) : false),
        destroy: () => { editor.off('update', recount); },
      };
    };
  },
});

/* ── footnote plumbing ────────────────────────────────────────────────────────
   Every note in a chapter is one <li> of one ordered list at the end of the
   chapter's document. That list is STORAGE, not placement: it keeps the notes
   in marker order, which is where their numbering comes from, and it's what
   export writes out (an EPUB reader wants the notes at the end of the file,
   paired to their markers by id — see lib/footnotes.ts).

   WHERE THEY APPEAR is the pagination plugin's job. It positions each <li> at
   the foot of the page its own marker landed on, and takes that room out of
   the page's text band, so a note sits on the same page as the sentence it
   annotates the way it does in a printed book. Nothing about the document
   changes to make that happen — the notes stay one list, in one place, in
   document order — so undo, export and numbering never see the difference.

   The list appears with the first marker and disappears with the last, so no
   empty "Notes" heading is ever left behind. Numbering restarts per chapter,
   which is what Atticus does and what falls out of each chapter being its own
   editor and its own exported file. */
function footnoteRefIds(doc: PMNode): string[] {
  const ids: string[] = [];
  doc.descendants((n) => { if (n.type.name === 'footnoteRef' && n.attrs.id) ids.push(n.attrs.id as string); });
  return ids;
}

function findFootnoteList(doc: PMNode): { node: PMNode; pos: number } | null {
  let found: { node: PMNode; pos: number } | null = null;
  doc.forEach((node, offset) => {
    if (node.type.name === 'orderedList' && node.attrs.class === FOOTNOTE_LIST_CLASS) found = { node, pos: offset };
  });
  return found;
}

function footnoteListFids(list: { node: PMNode } | null): string[] {
  const fids: string[] = [];
  list?.node.forEach((item) => fids.push((item.attrs['data-fid'] as string) ?? ''));
  return fids;
}

/* Reconciles the notes list against the markers in the body: adds an empty note
   for a new marker, drops the note for a deleted one, and reorders when a
   marker moves. Runs on every update but only dispatches when the id sequence
   genuinely differs — that guard is what stops the transaction it dispatches
   from re-triggering itself through onUpdate.

   Out of history on purpose. A sync is a consequence of the edit that caused
   it, so undo should step over the pair rather than through it: one ⌘Z takes
   back the marker, and the note goes with it. */
function syncFootnoteList(editor: Editor) {
  const { state } = editor;
  const ids = footnoteRefIds(state.doc);
  const list = findFootnoteList(state.doc);
  if (ids.join('\u0000') === footnoteListFids(list).join('\u0000')) return;

  const { listItem, paragraph, orderedList } = state.schema.nodes;
  const tr = state.tr;
  if (ids.length === 0) {
    if (list) tr.delete(list.pos, list.pos + list.node.nodeSize);
  } else {
    // Existing notes are carried over by id, never by position — position
    // breaks the moment someone deletes the second of three markers.
    const existing = new Map<string, PMNode>();
    list?.node.forEach((item) => {
      const fid = item.attrs['data-fid'] as string | null;
      if (fid) existing.set(fid, item);
    });
    const items = ids.map((id) => existing.get(id) ?? listItem.create({ 'data-fid': id }, paragraph.create()));
    const next = orderedList.create({ class: FOOTNOTE_LIST_CLASS }, items);
    if (list) tr.replaceWith(list.pos, list.pos + list.node.nodeSize, next);
    else tr.insert(state.doc.content.size, next);
  }
  if (!tr.docChanged) return;
  tr.setMeta('addToHistory', false);
  editor.view.dispatch(tr);
}

function footnotePos(doc: PMNode, fid: string): number | null {
  let at: number | null = null;
  doc.descendants((node, pos) => {
    if (node.type.name === 'listItem' && node.attrs['data-fid'] === fid) { at = pos; return false; }
    return true;
  });
  return at;
}

/* Inserting a marker moves the caret into its note, the way Word and Google
   Docs both do. The note is at the foot of the chapter rather than an inch
   below the caret, so leaving the caret in the body would mean the note you
   just created is somewhere you have to go and find. */
function insertFootnote(editor: Editor) {
  const id = `fn-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  editor.chain().focus().insertContent({ type: 'footnoteRef', attrs: { id } }).run();
  syncFootnoteList(editor);
  const at = footnotePos(editor.state.doc, id);
  if (at != null) editor.chain().focus().setTextSelection(at + 2).run();
}

/* ── pagination ───────────────────────────────────────────────────────────────
   Turns one chapter's continuous flow into fixed-height pages by inserting
   spacer widgets at the measured break points. See lib/pagination.ts for why
   it's decorations rather than one editor per page.

   The measure runs off a requestAnimationFrame after every update, because
   heights are only real once the browser has laid the change out. It dispatches
   only when the resulting breaks differ from the ones already applied — without
   that guard the dispatch would trigger another update, measure the same thing
   and dispatch again, forever. */
const paginationKey = new PluginKey<PaginationState>('pagination');

/** One note, lifted out of the list at the end of the chapter and put at the
    foot of the page its marker landed on. `top` is CSS, relative to the
    positioned wrapper the prose sits in. */
interface NotePlacement { fid: string; top: number; first: boolean }

interface PaginationState { breaks: PageBreak[]; notes: NotePlacement[]; pageCount: number }

/** Document position and size of every note item, by fid, in one walk. */
function footnoteItems(doc: PMNode): Map<string, { pos: number; size: number }> {
  const out = new Map<string, { pos: number; size: number }>();
  doc.descendants((node, pos) => {
    if (node.type.name !== 'listItem') return true;
    const fid = node.attrs['data-fid'] as string | null;
    if (fid) out.set(fid, { pos, size: node.nodeSize });
    return false;
  });
  return out;
}

/** Two placements are equal when they'd draw the same, to the pixel. */
function sameNotes(a: NotePlacement[], b: NotePlacement[]): boolean {
  if (a.length !== b.length) return false;
  return a.every((x, i) => x.fid === b[i].fid && x.first === b[i].first && Math.abs(x.top - b[i].top) < 1);
}

/* The table node a row-break widget sits inside, and its first row.

   Read from the DOCUMENT, not from the DOM. The obvious version of this asked
   view.nodeDOM for the table element — but a widget's toDOM runs while the view
   is mid-update, so nodeDOM could hand back null, and then the spacer fell back
   to colspan 1 (the table's own column rules drew straight through the gap) and
   the repeated header rendered as an empty row. The document is authoritative
   and always available. */
function rowBreakContext(doc: PMNode, pos: number): { cols: number } | null {
  const $p = doc.resolve(pos);
  const table = $p.node($p.depth);
  if (table.type.name !== 'table' || table.childCount === 0) return null;
  const first = table.child(0);
  let cols = 0;
  first.forEach((cell) => { cols += Number(cell.attrs.colspan) || 1; });
  return { cols: Math.max(1, cols) };
}

/* `geometry` is a getter, not a value: trim size and margins are a setting the
   reader can change at any time, and a TipTap extension is configured once when
   its editor is created. Reading it per measure keeps every chapter on the
   current page box without tearing down and rebuilding every editor in the
   book — which would lose the caret, the history and the scroll position. */
const Pagination = Extension.create<{ onLayout: (pageCount: number) => void; geometry: () => PageGeometry }>({
  name: 'pagination',
  addOptions() {
    return { onLayout: () => {}, geometry: () => DEFAULT_GEOMETRY };
  },
  addProseMirrorPlugins() {
    const notify = this.options.onLayout;
    const getGeometry = this.options.geometry;
    return [
      new Plugin<PaginationState>({
        key: paginationKey,
        state: {
          init: () => ({ breaks: [], notes: [], pageCount: 1 }),
          apply(tr, prev) {
            const next = tr.getMeta(paginationKey) as PaginationState | undefined;
            if (next) return next;
            /* Not remapped through tr.mapping on an ordinary edit: the measure
               that follows this transaction replaces the whole set anyway, and
               a remapped-but-stale break would flash a spacer at the wrong
               offset for one frame. Positions only have to survive until the
               next rAF. */
            return prev;
          },
        },
        props: {
          decorations(state) {
            const { breaks, notes } = paginationKey.getState(state) ?? { breaks: [], notes: [] };
            if (!breaks.length && !notes.length) return DecorationSet.empty;
            /* Node decorations, not a re-render: the <li> stays the same
               ProseMirror node in the same place in the document and only its
               box moves, so the caret, typing, selection and undo inside a
               note behave exactly as they did when the list was in the flow.
               Positions are read from the CURRENT doc rather than carried on
               the placement, so an edit between the measure and this call
               can't produce a decoration over a range that no longer exists. */
            const placed: Decoration[] = [];
            if (notes.length) {
              const items = footnoteItems(state.doc);
              const list = findFootnoteList(state.doc);
              // Collapses the list to nothing in the flow — see the CSS on
              // .book-fn-paged. Only once there are placements to collapse to.
              if (list) placed.push(Decoration.node(list.pos, list.pos + list.node.nodeSize, { class: 'book-fn-paged' }));
              for (const n of notes) {
                const item = items.get(n.fid);
                if (!item) continue;
                placed.push(Decoration.node(item.pos, item.pos + item.size, {
                  class: n.first ? 'book-fn-placed book-fn-first' : 'book-fn-placed',
                  style: `top:${Math.round(n.top)}px`,
                }));
              }
            }
            return DecorationSet.create(state.doc, placed.concat(breaks.flatMap((b) => {
              /* A row break lands inside a <tbody>, where a <div> is not valid
                 markup: the browser hoists it out of the table and the page
                 silently overflows. So the spacer has to BE a row, and the
                 continuation's repeated header is a second one. Both are
                 widgets rather than real nodes — the document stays unchanged,
                 which is the whole reason breaks are decorations — and both sit
                 in the same <table> as the rows they separate, so they inherit
                 its column widths for nothing. */
              if (b.rowIndex != null) {
                const ctx = rowBreakContext(state.doc, b.pos);
                const spacer = Decoration.widget(b.pos, () => {
                  const tr = document.createElement('tr');
                  tr.dataset.pageBreak = 'true';
                  tr.className = 'book-tr-spacer';
                  tr.contentEditable = 'false';
                  const td = document.createElement('td');
                  td.colSpan = ctx?.cols ?? 1;
                  /* Styled inline rather than from the sheet: this row exists to
                     occupy the page gap and must paint nothing at all, and a
                     missed selector here draws a cell border across the gap —
                     the exact artefact that makes other boxes monolithic. */
                  td.style.cssText = `height:${b.height}px;padding:0;border:none;background:transparent;line-height:0;font-size:0`;
                  tr.appendChild(td);
                  return tr;
                }, { side: -3, ignoreSelection: true, key: `pbr-${b.pos}-${Math.round(b.height)}` });
                /* The header is NOT repeated on a continuation. Word and Google
                   Docs both treat that as a per-table opt-in rather than
                   something an editor does on its own, and a row the author
                   never wrote appearing on page two is a surprise. */
                return [spacer];
              }
              return [Decoration.widget(b.pos, () => {
              const el = document.createElement('div');
              el.dataset.pageBreak = 'true';
              el.className = 'book-page-break';
              el.style.height = `${b.height}px`;
              // A split lands INSIDE a paragraph, where the surrounding content
              // is inline — the spacer has to declare itself a block or it
              // contributes no height at all and the page silently overflows.
              if (b.lineIndex != null) el.style.display = 'block';
              // Not editable and not selectable, so the caret steps over the
              // gap instead of landing inside it.
              el.contentEditable = 'false';
              return el;
              }, { side: -1, ignoreSelection: true, key: `pb-${b.pos}-${b.lineIndex ?? 'b'}-${Math.round(b.height)}` })];
            })));
          },
        },
        view(view) {
          let frame = 0;
          /* Two guards, both load-bearing. `busy` stops the measure re-entering
             itself: the dispatch below changes the DOM, which trips the
             ResizeObserver, which schedules another measure. `lastNotified`
             stops the React setState firing on every pass — React batches
             ResizeObserver callbacks, so an unconditional call here reads to it
             as an update loop and it bails with "maximum update depth". */
          let busy = false;
          let lastNotified = -1;
          /* Which page each note was last put on. A note takes room out of its
             page's text band, which can push its own marker onto the NEXT
             page — and then the band it left behind is roomy again and the
             marker comes straight back. That two-cycle has no fixpoint, so the
             assignment is sticky FORWARD: while the document is unchanged a
             note may move to a later page but never back to an earlier one,
             which is bounded and therefore settles. An actual edit clears it,
             so deleting the text above a marker really does bring its note
             back up. */
          const stuck = new Map<string, number>();
          const measure = () => {
            frame = 0;
            if (busy) return;
            busy = true;
            try {
              const geo = getGeometry();
              /* Read the flow as if it had never been paginated, by subtracting
                 the spacers already in it rather than zeroing them. Zeroing
                 meant writing style and reading layout in the same pass, and
                 the ResizeObserver below saw its own effect: measure, mutate,
                 resize, measure, forever. Spacers carry no margins, so nothing
                 collapses across one and plain subtraction is exact. */
              /* Rendered coordinates, relative to the first block's top —
                 measureBreaks works in the same space, so no unpaginated flow
                 has to be reconstructed and nothing here mutates style (which
                 the ResizeObserver below would read as a change it caused,
                 looping forever). */
              /* Origin is the STACK's content box, so page 0's band covers the
                 heading above the prose too. Falling back to the editor's own
                 top only matters before the stack has mounted. */
              const stack = view.dom.closest('[data-page-stack]') as HTMLElement | null;
              const originTop = (stack ? stack.getBoundingClientRect().top + geo.padTop : view.dom.getBoundingClientRect().top);
              const blocks: FlowBlock[] = [];
              // Screen-space line rects per block position, so a split break
              // can be turned back into a document position below.
              const screenLines = new Map<number, DOMRect[]>();
              let pendingSpacer = 0;
              /* The notes list is not part of the flow. It's the last block in
                 the document, but every item in it is about to be positioned
                 at the foot of some page, so counting it here would reserve
                 its height twice — once as a block at the end of the chapter
                 and again as the room its notes take from their own pages. */
              let noteList: HTMLElement | null = null;
              for (const el of Array.from(view.dom.children) as HTMLElement[]) {
                if (el.dataset.pageBreak === 'true') { pendingSpacer += el.offsetHeight; continue; }
                if (el.classList.contains(FOOTNOTE_LIST_CLASS)) { noteList = el; continue; }
                let pos: number | null = null;
                try {
                  const raw = view.posAtDOM(el, 0);
                  if (raw >= 0) {
                    const $raw = view.state.doc.resolve(raw);
                    /* A paragraph's own DOM resolves to a position INSIDE it, so
                       before(1) is the block. A node view — every table has one,
                       since they aren't resizable — resolves to a position at
                       doc level instead, where before(1) throws and the block
                       silently lost its position: no position, no break, and
                       the table overran the sheet whatever the measurement
                       said. At depth 0 the position already IS the block's. */
                    pos = $raw.depth > 0 ? $raw.before(1) : raw;
                  }
                } catch { pos = null; }
                const r = el.getBoundingClientRect();
                /* Only a plain paragraph is split across a page. A figure, a
                   table, a heading or a blockquote has to move whole: their
                   boxes paint something — a border, a rule, a background — that
                   would draw straight through the page gap, and a heading
                   separated from its own first line is the thing keep-with-next
                   exists to prevent. */
                /* The `div` in that list must not match the spacer THIS plugin
                   put inside the paragraph on the last pass: a paragraph that
                   had just been split would come back unsplittable, get moved
                   whole instead, lose its spacer, become splittable again — and
                   settle on whichever of the two the loop happened to end on,
                   which is why long paragraphs ran off the foot of the sheet. */
                const inner = Array.from(el.querySelectorAll<HTMLElement>('.book-page-break'));
                const splittable = el.tagName === 'P'
                  && !Array.from(el.querySelectorAll('figure, table, div')).some((x) => !(x as HTMLElement).dataset.pageBreak);
                const innerH = inner.reduce((sum, x) => sum + x.offsetHeight, 0);
                /* Line height and line COUNT, not line rects. Rects come from a
                   Range (el.getClientRects() on a block returns its single
                   border box, which made every paragraph look unsplittable),
                   but their positions are displaced by any spacer already
                   inside — and measureBreaks now derives positions rather than
                   reading them, so all it needs is the pitch and how many.
                   Subtracting the inner spacers keeps the count stable while
                   the paragraph is already split. */
                let lineHeight: number | undefined;
                let lineCount: number | undefined;
                if (splittable) {
                  const lh = parseFloat(window.getComputedStyle(el).lineHeight);
                  if (Number.isFinite(lh) && lh > 1) {
                    lineHeight = lh;
                    lineCount = Math.max(1, Math.round((r.height - innerH) / lh));
                  }
                }
                if (splittable && pos != null) {
                  const range = document.createRange();
                  range.selectNodeContents(el);
                  /* One rect per LINE, and only lines. getClientRects returns a
                     rect for every box in the range, so a paragraph already
                     split hands back its own spacer as a rect — which shifted
                     every line index after the first break by one — and a bold
                     or linked run hands back a second rect on the line it sits
                     in. Drop the spacers by position, then keep one rect per
                     distinct top. Index parity with measureBreaks' line count
                     is the whole contract here: it names a line by number and
                     this is what turns that number back into a position. */
                  const spacerTops = new Set(inner.map((x) => Math.round(x.getBoundingClientRect().top)));
                  const byTop = new Map<number, DOMRect>();
                  for (const q of Array.from(range.getClientRects())) {
                    const top = Math.round(q.top);
                    if (q.height <= 1 || spacerTops.has(top)) continue;
                    const seen = byTop.get(top);
                    if (!seen || q.left < seen.left) byTop.set(top, q);
                  }
                  screenLines.set(pos, Array.from(byTop.entries()).sort((a, x) => a[0] - x[0]).map(([, q]) => q));
                }
                /* A DATA table fragments at its row boundaries. A layout
                   table — book-split-columns, a stack — must not: its single
                   row is a set of side-by-side columns, so a row break either
                   does nothing or cuts every column off mid-flow.

                   Offsets are UNPAGINATED, the same contract the line path
                   works to: the spacer rows and repeated headers a previous
                   pass inserted are subtracted rather than measured around, so
                   this pass reads the table as if it had never been broken and
                   re-emits the same breaks. */
                let rows: number[] | undefined;
                let headerH: number | undefined;
                let rowDrop = 0;
                /* NOT `el` itself: TipTap gives every table a node view whenever
                   it isn't resizable, and that view wraps it in
                   <div class="tableWrapper">. So the top-level block here is
                   the wrapper, and the table is its child. Offsets stay
                   relative to the BLOCK's top, which is what measureBreaks
                   works in. */
                const tableEl = el.tagName === 'TABLE' ? el : el.querySelector<HTMLElement>(':scope > table');
                if (tableEl && !tableEl.classList.contains(STACK_CLASS)) {
                  const trs = Array.from(tableEl.querySelectorAll<HTMLElement>(':scope > tbody > tr'));
                  const offs: number[] = [];
                  let lastBottom = 0;
                  let head: HTMLElement | null = null;
                  for (const tr of trs) {
                    const tb = tr.getBoundingClientRect();
                    if (tr.dataset.pageBreak === 'true') { rowDrop += tb.height; continue; }
                    if (!head) head = tr;
                    offs.push(Math.round(tb.top - r.top - rowDrop));
                    lastBottom = Math.round(tb.bottom - r.top - rowDrop);
                  }
                  if (offs.length > 1) {
                    offs.push(lastBottom);
                    rows = offs;
                    // A header row is one that holds <th>. The worksheet markup
                    // puts it in <tbody> like every other row, so the tag is
                    // the only thing that identifies it.
                    headerH = head?.querySelector('th') ? Math.round(head.getBoundingClientRect().height) : 0;
                  }
                }
                /* The one measurement that isn't a measurement: the author said
                   this block opens a page. Read off the same attribute the node
                   serializes, so the rendered DOM stays the single source.
                   Only chapter titles carry it, and theirs defaults to TRUE —
                   a chapter breaks unless told not to. Every other block starts
                   a page by being split into its own container instead, which
                   this walk sees as a container boundary, not as a flag. */
                const forced = el.dataset.chapterTitle === 'true'
                  && el.dataset.breakBefore !== 'false';
                blocks.push({
                  forced,
                  pos,
                  top: r.top - originTop,
                  bottom: r.bottom - originTop - rowDrop,
                  spacerBefore: pendingSpacer,
                  lineHeight,
                  lineCount,
                  rows,
                  headerH,
                });
                pendingSpacer = 0;
              }

              /* Notes take their room BEFORE the flow is measured, because
                 which page a block lands on depends on how much of each page
                 the notes have already claimed. Assignment comes from the
                 markers as they sit right now — which is to say, as they sit
                 under the reserve the last pass applied. That's the fixpoint
                 this converges on, with `stuck` ruling out the one case where
                 no fixpoint exists. */
              const noteH = new Map<string, number>();
              if (noteList) {
                for (const li of Array.from(noteList.children) as HTMLElement[]) {
                  const fid = li.getAttribute('data-fid');
                  if (fid) noteH.set(fid, li.getBoundingClientRect().height);
                }
              }
              const perPage = new Map<number, string[]>();
              if (noteH.size) {
                for (const ref of Array.from(view.dom.querySelectorAll<HTMLElement>('.book-footnote-ref'))) {
                  const fid = ref.getAttribute('data-fid');
                  if (!fid || !noteH.has(fid)) continue;
                  const want = pageOfTop(ref.getBoundingClientRect().top - originTop, geo);
                  const page = Math.max(want, stuck.get(fid) ?? want);
                  stuck.set(fid, page);
                  const group = perPage.get(page);
                  if (group) group.push(fid); else perPage.set(page, [fid]);
                }
              }
              const reserve: number[] = [];
              for (const [page, fids] of perPage) {
                const h = fids.reduce((sum, fid) => sum + (noteH.get(fid) ?? 0), 0);
                reserve[page] = Math.min(h + FOOTNOTE_GAP, footnoteReserveMax(geo));
              }

              const measured = measureBreaks(blocks, geo, reserve);
              const pageCount = measured.pageCount;
              /* Temporary: `window.__pagedebug = true` in the console, then type
                 in the chapter, to see what the engine actually measured. */
              if ((window as unknown as { __pagedebug?: boolean }).__pagedebug) {
                console.log('[pag] geo', { h: geo.h, padTop: geo.padTop, contentH: contentH(geo), band1: bandTop(1, geo) });
                console.log('[pag] blocks', blocks.map((x) => ({
                  pos: x.pos, top: Math.round(x.top), bottom: Math.round(x.bottom),
                  lines: x.lineCount, rows: x.rows?.length, headerH: x.headerH,
                  rowOffsets: x.rows,
                })));
                console.log('[pag] breaks', measured.breaks, 'pageCount', pageCount);
              }
              /* CSS `top` is relative to the positioned wrapper the prose sits
                 in, which starts below the chapter eyebrow and title; the
                 measurements above are relative to the page stack's content
                 box, which starts above them. offsetParent is the element the
                 browser will actually resolve `top` against, so asking it is
                 exact whatever sits between the two. */
              const host = view.dom.offsetParent as HTMLElement | null;
              const toCss = originTop - (host ? host.getBoundingClientRect().top : originTop);
              const notes: NotePlacement[] = [];
              for (const [page, fids] of perPage) {
                const h = fids.reduce((sum, fid) => sum + (noteH.get(fid) ?? 0), 0);
                // Bottom-aligned: the last note ends on the page's bottom
                // margin, so the block grows upward into the text band the
                // reserve above already cleared for it.
                let y = bandTop(page, geo) + contentH(geo) - h;
                fids.forEach((fid, i) => {
                  notes.push({ fid, top: y + toCss, first: i === 0 });
                  y += noteH.get(fid) ?? 0;
                });
              }
              /* A split break is measured at a LINE; the decoration needs the
                 document position of that line's first character. posAtCoords
                 is the only thing that knows it — line boxes have no position
                 of their own in the document model. A couple of pixels in from
                 the line's own left/top lands inside the first glyph rather
                 than on the boundary between two lines. */
              const breaks = measured.breaks.flatMap((b) => {
                /* A row break is anchored between two tableRow nodes, which is
                   an exact walk rather than a hit test: the rows measured above
                   are the table node's children, in the same order. */
                if (b.rowIndex != null) {
                  const tbl = view.state.doc.nodeAt(b.pos);
                  if (!tbl || b.rowIndex >= tbl.childCount) return [];
                  let at = b.pos + 1;
                  for (let i = 0; i < b.rowIndex; i++) at += tbl.child(i).nodeSize;
                  return [{ ...b, pos: at }];
                }
                if (b.lineIndex == null) return [b];
                const rects = screenLines.get(b.pos);
                const rect = rects?.[b.lineIndex];
                if (!rect) return [];
                const at = view.posAtCoords({ left: rect.left + 2, top: rect.top + 2 });
                // No resolvable position means this line can't carry a break —
                // dropping it overflows one page, which beats splitting at the
                // wrong place.
                if (!at) return [];
                /* Snap back to the start of the word. Those 2px land past the
                   middle of a narrow opening glyph — an "i", an "l" — and the
                   browser then rounds the caret to the far side of it, so the
                   break went in one character into the line and the page ended
                   "...a working day i" with "s not..." overleaf. A line always
                   begins at a word, so the nearest word start behind the
                   resolved position IS the line start. */
                const $at = view.state.doc.resolve(at.pos);
                const off = at.pos - $at.start();
                const before = off > 0 ? $at.parent.textBetween(0, off, ' ', ' ') : '';
                const intoWord = before.length - before.replace(/\S+$/, '').length;
                return [{ ...b, pos: at.pos - intoWord }];
              });
              const current = paginationKey.getState(view.state);
              if (!current || !sameBreaks(current.breaks, breaks) || !sameNotes(current.notes, notes)) {
                view.dispatch(view.state.tr.setMeta(paginationKey, { breaks, notes, pageCount }).setMeta('addToHistory', false));
              }
              if (pageCount !== lastNotified) { lastNotified = pageCount; notify(pageCount); }
            } finally {
              busy = false;
            }
          };
          const schedule = () => { if (!frame) frame = requestAnimationFrame(measure); };
          schedule();
          // Images and webfonts land after the first measure, and both change
          // heights — a ResizeObserver catches them without polling.
          const ro = new ResizeObserver(schedule);
          ro.observe(view.dom);
          return {
            update: (v, prev) => {
              // An actual edit invalidates every sticky assignment: the whole
              // point of the stickiness is to settle a layout the document
              // isn't changing under.
              if (!prev.doc.eq(v.state.doc)) stuck.clear();
              schedule();
            },
            destroy: () => { ro.disconnect(); if (frame) cancelAnimationFrame(frame); },
          };
        },
      }),
    ];
  },
});

/* ── Button ──────────────────────────────────────────────────────────────────
   A real link that looks like a button. This replaces the old "Call to action"
   tile, which inserted `<p><strong>Get the companion workbook →</strong></p>` —
   bold text and a typed arrow, with nothing behind either, gated at Pro. Two
   separate defects, one fix:

   1. That tile stopped existing the moment it landed. It produced a paragraph
      indistinguishable from one the author typed, so its entire contribution was
      words they could type themselves and a Cmd+B.
   2. JumbotronBlock had the opposite problem: it DREW a button — a styled <div>
      — that could not be clicked in any output, and offered no URL field, so the
      author could not repair it either. Its heading/body/buttonLabel are
      plain-text attributes rather than rich content, so the link mark cannot
      reach them. A reader tapping it concludes the book is broken.

   Why a link is the right foundation: it is the most portable interactive thing
   a book has. PDF, EPUB, Kindle, HTML and the flipbook all honour <a href>. So
   unlike video or audio — which play in the live version and nowhere else — a
   button built on a real link works in every format we ship.

   The destination is also printed beneath the button, the way QrCodeBlock prints
   its address under the symbol and EmbedBlock prints "Watch: …" under its poster.
   On paper a button reading "Get it now" is a dead end; the URL in text is the
   one part of it that survives everywhere. */
const BUTTON_DEFAULT_BG = '#006EFE';
/* Legacy only. A button used to carry ONE icon plus a side, with 'none' as the
   off value; it now carries two independent slots whose off value is the empty
   string, so this survives purely to read documents saved under the old shape.
   See buttonAttrsOf. */
const BUTTON_ICON_NONE = 'none';
/* What a slot comes back as when it is switched on without a glyph remembered. */
const BUTTON_ICON_DEFAULT = 'arrow-right';

/* Size is a closed set of three, not a px field, and width is a boolean rather
   than a number. Both follow the systems — Polaris size micro/slim/medium/large
   plus fullWidth, MUI small/medium/large plus fullWidth, Carbon sm..2xl — but
   the format is the stronger reason. `.book-button` in lib/epub.ts is sized in
   em because a reading system's own base font size wins over ours: a px height
   would be honest on the canvas and a lie in EPUB and Kindle, where only a
   multiplier survives.

   Width is Fit or Fill, Figma's hug/fill without the third option. Fixed is
   missing on purpose, and it is the only one of the three that cannot be made
   to work here: a px width is read against a base font size we do not control,
   and the label's length isn't knowable when the control is set, so a fixed box
   either clips the text or strands a gap in whichever reading system the author
   didn't test. Fit and Fill are the two states that survive every format.

   The scale is em against the 15.5px prose base, with line-height pinned to 1.2
   so a height is actually derivable: small lands at ~46px, which is the point of
   the scale. The old single size was 13.5px text in 10px of padding — ~36px, under
   the 44px tap target every CTA guideline asks for — so the smallest preset here
   is deliberately bigger than what it replaces rather than equal to it. */
type ButtonSize = 'small' | 'medium' | 'large';
/* Three states, the same three the image block offers under its own W field
   (Fill column / Fixed size) plus the one an image cannot have: a photo has an
   intrinsic size, a button only has its label. Fixed is a px number here rather
   than the multiplier the HEIGHT uses, because every other box in this editor —
   image, shape, divider — states its width in px and exports it that way, and a
   control that is a number everywhere else should not be three named buttons
   here. The cost is real and worth stating: a px width is read against a column
   whose own width varies by reading system, so a fixed button can end up wider
   than the measure on a small screen. Fit and Fill cannot. */
type ButtonWidth = 'fit' | 'fill' | 'fixed';
const BUTTON_FIXED_W_DEFAULT = 240;
/* px and per-corner, exactly like the image block: a comma list TL,TR,BR,BL
   through the shared parseRadius, or one number when all four agree. (Image,
   shape and divider all already take a number here, and the EPUB stylesheet
   writes px radii throughout.) 7 is what `.book-button` had hard-coded, so an
   existing button is unchanged, and a pill is this field at its maximum rather
   than a named option. */
const BUTTON_RADIUS_DEFAULT = '7';
const BUTTON_RADIUS_MAX = 200;
/* parseRadius reads '' as [0,0,0,0] — right for an image, whose default is no
   radius, wrong for a button, where an absent attribute means a document saved
   before corners existed and must stay on 7. So absence is resolved to the
   default BEFORE parsing, and serializeButtonRadius never emits '' for an
   all-zero set the way serializeRadius does, or a deliberately square button
   would spring back to rounded on the next reload. */
function buttonCornersOf(v: unknown): number[] {
  const raw = v === undefined || v === null || v === '' ? BUTTON_RADIUS_DEFAULT : (v as string | number);
  return parseRadius(raw).map((n) => Math.min(Math.max(0, n), BUTTON_RADIUS_MAX));
}
function serializeButtonRadius(c: number[]): string {
  return c.every((v) => v === c[0]) ? String(c[0]) : c.join(',');
}
const BUTTON_SIZES: Record<ButtonSize, { font: number; padY: number; padX: number }> = {
  small: { font: 0.95, padY: 0.95, padX: 1.6 },
  medium: { font: 1.05, padY: 1, padX: 1.75 },
  large: { font: 1.2, padY: 1.05, padX: 1.9 },
};
const BUTTON_SIZE_DEFAULT: ButtonSize = 'medium';
/* A document saved before this attribute existed has no data-size, and reads as
   medium rather than as a fourth "legacy" size: its button was already under the
   tap target, so growing it is the fix, not a regression. */
function buttonSizeOf(v: unknown): ButtonSize {
  return v === 'small' || v === 'large' || v === 'medium' ? v : BUTTON_SIZE_DEFAULT;
}
function buttonWidthOf(v: unknown): ButtonWidth {
  return v === 'fill' || v === 'fixed' ? v : 'fit';
}
function buttonNum(v: unknown, fallback: number, max: number): number {
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) && n >= 0 ? Math.min(n, max) : fallback;
}

/* The prose base the em scale is written against — the same 15.5 lib/epub.ts
   divides by when it converts a theme's px font size to em. */
const BUTTON_EM_BASE = 15.5;

/* One table, two units. The export path (renderHTML, which is also what gets
   stored and re-parsed) writes em, because that is what survives a reading
   system. The canvas path (the NodeView, and the Insert tile's preview) writes
   px, because the tile renders OUTSIDE .book-chapter-prose, where an em would
   resolve against whatever the panel's font size happens to be and the specimen
   would stop matching the thing it inserts. Padding is em-of-its-own-font-size,
   so the px form multiplies by the button's size, not by the base. */
/* Takes the two fields it reads rather than a whole ButtonAttrs, so the call to
   action banner's button can share the one size table instead of growing a
   second copy of it. ButtonAttrs still satisfies this shape, so every existing
   call site is unchanged. */
function buttonBoxCss(a: {
  size?: unknown; width?: unknown; widthPx?: unknown; radius?: unknown;
  borderWidth?: unknown; borderColor?: unknown; borderStyle?: unknown;
}, unit: 'em' | 'px'): string {
  const s = BUTTON_SIZES[buttonSizeOf(a.size)];
  const round = (n: number) => Math.round(n * 10) / 10;
  const size = unit === 'em'
    ? `font-size:${s.font}em;padding:${s.padY}em ${s.padX}em`
    : `font-size:${round(s.font * BUTTON_EM_BASE)}px;padding:${round(s.padY * s.font * BUTTON_EM_BASE)}px ${round(s.padX * s.font * BUTTON_EM_BASE)}px`;
  const corners = buttonCornersOf(a.radius);
  /* One value when the four agree, the CSS shorthand when they don't — same
     order (TL TR BR BL) the shape block writes and parseRadius stores in. */
  const radius = corners.every((v) => v === corners[0])
    ? `${corners[0]}px`
    : corners.map((v) => `${v}px`).join(' ');
  /* Fill is display:block with no width:100%: a block box's auto width already
     resolves to the container, and its padding sits inside that rather than
     adding to it — so Fill needs no box-sizing, which is the rule oldest EPUB
     engines are least reliable about. Fixed does need it, since a stated width
     plus em padding would otherwise overflow by the padding; a reader that
     ignores box-sizing draws the button that much wider, which is a drift, not
     a break. */
  const width = buttonWidthOf(a.width);
  const box = width === 'fill' ? ';display:block;text-align:center'
    : width === 'fixed'
      ? `;display:block;width:${buttonNum(a.widthPx, BUTTON_FIXED_W_DEFAULT, 4000)}px;box-sizing:border-box;text-align:center`
      : '';
  /* An outlined button is a real CTA style — the secondary action next to a
     filled primary — and it was the one shape this block could not make: the
     fill was the only thing it drew. Width/style/colour only, no edges and no
     inside/outside: a border on three sides of a button is not a thing, and
     `position` has no meaning without box-sizing to play against. */
  const bw = buttonNum(a.borderWidth, 0, 40);
  const border = bw > 0
    ? `;border:${bw}px ${strokeStyleOf(a.borderStyle as string | undefined)} ${a.borderColor || INK_HEX}`
    : '';
  return `${size};border-radius:${radius}${border}${box}`;
}

/* White or ink, whichever clears the chosen fill, rather than a second colour
   control the author has to keep in sync with the first. relativeLuminance is
   the same helper the charts use to pick a value label against its own bar. */
function buttonInkFor(bg: string): string {
  return /^#[0-9a-fA-F]{6}$/.test(bg) && relativeLuminance(bg) > 0.55 ? INK_HEX : '#FFFFFF';
}

/* Two slots rather than one icon and a side. They are genuinely independent —
   a cart on the left and an arrow on the right is a real button — and with both
   empty meaning no icon, the picker no longer needs a "None" tile competing
   with eight glyphs for the same click. This is startIcon/endIcon in MUI,
   leading/trailing in Material 3 and Carbon; the single-icon-plus-side form is
   what email builders do, and it is the weaker of the two. '' = slot off. */
interface ButtonAttrs {
  label: string; url: string;
  iconLeft: string; iconRight: string; color: string;
  size: ButtonSize; width: ButtonWidth; widthPx: number; radius: string;
  borderWidth: number; borderColor: string; borderStyle: string;
  align: 'left' | 'center' | 'right'; locked: boolean;
}

function buttonAttrsOf(el: HTMLElement): ButtonAttrs {
  const align = el.getAttribute('data-align');
  /* A document saved before the two-slot change has data-icon + data-icon-side
     and neither slot attribute. Read it into whichever slot it named, so an
     existing book reopens looking exactly as it was left. */
  const legacy = el.getAttribute('data-icon');
  const hasSlots = el.hasAttribute('data-icon-left') || el.hasAttribute('data-icon-right');
  const migrated = !hasSlots && legacy && legacy !== BUTTON_ICON_NONE
    ? (el.getAttribute('data-icon-side') === 'left' ? { l: legacy, r: '' } : { l: '', r: legacy })
    : null;
  return {
    label: el.querySelector('.book-button-label')?.textContent || 'Get the companion workbook',
    url: el.getAttribute('data-url') || '',
    iconLeft: migrated ? migrated.l : el.getAttribute('data-icon-left') || '',
    iconRight: migrated ? migrated.r : el.getAttribute('data-icon-right') || '',
    color: el.getAttribute('data-color') || BUTTON_DEFAULT_BG,
    size: buttonSizeOf(el.getAttribute('data-size')),
    width: buttonWidthOf(el.getAttribute('data-width')),
    widthPx: buttonNum(el.getAttribute('data-width-px'), BUTTON_FIXED_W_DEFAULT, 4000),
    radius: el.getAttribute('data-radius') ?? BUTTON_RADIUS_DEFAULT,
    borderWidth: buttonNum(el.getAttribute('data-bw'), 0, 40),
    borderColor: el.getAttribute('data-bc') || INK_HEX,
    borderStyle: el.getAttribute('data-bs') || 'solid',
    align: align === 'center' || align === 'right' ? align : 'left',
    locked: el.getAttribute('data-locked') === 'true',
  };
}

/* The data-* attributes are the round-trip: everything visible is regenerated
   from them on parse, so an edited button survives a save/reload unchanged. */
function buttonDataAttrs(a: ButtonAttrs): Record<string, string> {
  return {
    'data-button': 'true', 'data-url': a.url,
    'data-icon-left': a.iconLeft, 'data-icon-right': a.iconRight,
    'data-color': a.color, 'data-align': a.align,
    'data-size': buttonSizeOf(a.size), 'data-width': buttonWidthOf(a.width),
    'data-width-px': String(buttonNum(a.widthPx, BUTTON_FIXED_W_DEFAULT, 4000)),
    'data-radius': serializeButtonRadius(buttonCornersOf(a.radius)),
    ...(buttonNum(a.borderWidth, 0, 40) > 0
      ? { 'data-bw': String(buttonNum(a.borderWidth, 0, 40)), 'data-bc': a.borderColor || INK_HEX, 'data-bs': a.borderStyle || 'solid' }
      : {}),
    ...(a.locked ? { 'data-locked': 'true' } : {}),
  };
}

/* String form of the button's innards — shared by the NodeView (which builds DOM
   by hand and never passes through renderHTML) and by the Insert tile, whose
   preview injects raw HTML straight into the panel. Without the sharing those
   three drift, which is exactly how the callout tile once previewed as a blank
   white box. */
function buttonInnerHtml(a: ButtonAttrs): string {
  const ink = buttonInkFor(a.color);
  const left = a.iconLeft ? bookIconHtml(a.iconLeft, ink) : '';
  const right = a.iconRight ? bookIconHtml(a.iconRight, ink) : '';
  const label = `<span class="book-button-label">${escapeHtml(a.label)}</span>`;
  return `<span class="book-button" style="background:${a.color};color:${ink};${buttonBoxCss(a, 'px')}">${left}${label}${right}</span>`;
}

/* The Insert tile's markup. It has to satisfy two readers at once: TipTap's
   parseHTML on drop, and the panel's own preview, which injects this string
   straight into the DOM without going through the editor at all. Generating it
   from the same helpers the node uses is what keeps the tile showing the button
   it actually inserts. */
const BUTTON_TILE_ATTRS: ButtonAttrs = {
  label: 'Get the companion workbook', url: '', iconLeft: '',
  iconRight: BUTTON_ICON_DEFAULT, color: BUTTON_DEFAULT_BG,
  size: BUTTON_SIZE_DEFAULT, width: 'fit', widthPx: BUTTON_FIXED_W_DEFAULT,
  radius: BUTTON_RADIUS_DEFAULT, borderWidth: 0, borderColor: INK_HEX, borderStyle: 'solid',
  align: 'left', locked: false,
};
function buttonTileHtml(a: ButtonAttrs): string {
  const attrs = Object.entries(buttonDataAttrs(a))
    .map(([k, v]) => `${k}="${escapeHtml(v)}"`).join(' ');
  return `<div ${attrs} class="book-button-wrap" style="text-align:${a.align}">${buttonInnerHtml(a)}</div>`;
}

const ButtonBlock = Node.create({
  name: 'buttonBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      label: { default: 'Get the companion workbook' },
      url: { default: '' },
      iconLeft: { default: '' },
      iconRight: { default: BUTTON_ICON_DEFAULT },
      color: { default: BUTTON_DEFAULT_BG },
      size: { default: BUTTON_SIZE_DEFAULT },
      width: { default: 'fit' },
      widthPx: { default: BUTTON_FIXED_W_DEFAULT },
      radius: { default: BUTTON_RADIUS_DEFAULT },
      borderWidth: { default: 0 },
      borderColor: { default: INK_HEX },
      borderStyle: { default: 'solid' },
      align: { default: 'left' },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{ tag: 'div[data-button]', getAttrs: (el) => buttonAttrsOf(el as HTMLElement) }];
  },
  renderHTML({ node }) {
    const a = node.attrs as unknown as ButtonAttrs;
    const ink = buttonInkFor(a.color);
    const href = normaliseHref(a.url);
    const left = a.iconLeft ? bookIconSpec(a.iconLeft, ink) : null;
    const right = a.iconRight ? bookIconSpec(a.iconRight, ink) : null;
    const inner: unknown[] = [['span', { class: 'book-button-label' }, a.label]];
    if (left) inner.unshift(left);
    if (right) inner.push(right);
    /* An <a> with no href is not a link — reading systems variously render it as
       dead text or drop it — so an unconfigured button degrades to a <span> that
       still looks right rather than to a broken anchor. */
    const style = `background:${a.color};color:${ink};${buttonBoxCss(a, 'em')}`;
    const box = href
      ? ['a', { href, class: 'book-button', style }, ...inner]
      : ['span', { class: 'book-button', style }, ...inner];
    const children: unknown[] = [box];
    if (href) children.push(['span', { class: 'book-button-url' }, href]);
    return ['div', {
      ...buttonDataAttrs(a), class: 'book-button-wrap', style: `text-align:${a.align}`,
    }, ...children] as unknown as DOMOutputSpec;
  },
  addNodeView() {
    return ({ node }) => {
      const a = node.attrs as unknown as ButtonAttrs;
      const href = normaliseHref(a.url);
      const dom = document.createElement('div');
      dom.className = 'book-button-wrap';
      dom.contentEditable = 'false';
      dom.style.textAlign = a.align;
      for (const [k, v] of Object.entries(buttonDataAttrs(a))) dom.setAttribute(k, v);
      /* A <span> on the canvas, not the <a> the export emits: a live anchor inside
         the editor navigates away from the book when the author clicks the thing
         they were trying to select. The URL line below it is still shown, so what
         they see is what the reader gets minus the navigation. */
      dom.innerHTML = buttonInnerHtml(a)
        + (href ? `<span class="book-button-url">${escapeHtml(href)}</span>` : '');
      return { dom };
    };
  },
});

/* ── Icon ────────────────────────────────────────────────────────────────────
   A standalone vector mark. Old Designrr's rail has an "Artwork & Shapes"
   category with an Artworks tab beside its Shapes tab; this editor built the
   Shapes half and left the other empty.

   Icons get their own Elements group rather than joining Shapes. They share a
   lot with a shape — place it, colour it, size it — but a shape is drawn from
   generated geometry (sides, points, corner radius) and an icon is fixed path
   data with a meaning attached, which is why the two inspectors and the two
   pickers have almost nothing in common: nobody browses shapes by name, and
   nobody wants a corner-radius field on a lightbulb.

   Of everything in this editor an icon has the widest reach: inline SVG renders
   in PDF, Flipbook, Kindle, EPUB and HTML, and prints on paper. Only the QR code
   matches that. */
const ICON_DEFAULT_SIZE = 40;

/* `style` is the solid/outline cut, not a CSS style. It rides on the node
   rather than being baked into `name` so that switching an already-placed icon
   between the two is an attribute change on the mark you selected, the same way
   colour and size are — and so a book saved before the library had two cuts
   still opens, on the solid one it was drawn with. */
interface IconAttrs { name: string; style: BookIconStyle; color: string; size: number; align: 'left' | 'center' | 'right'; locked: boolean }

function iconAttrsOf(el: HTMLElement): IconAttrs {
  const align = el.getAttribute('data-align');
  const size = Number(el.getAttribute('data-size'));
  return {
    name: el.getAttribute('data-name') || 'star',
    // Anything but the one word means solid, which is what every icon placed
    // before this attribute existed carries: no data-style at all.
    style: el.getAttribute('data-style') === 'outline' ? 'outline' : 'solid',
    color: el.getAttribute('data-color') || INK,
    size: Number.isFinite(size) && size > 0 ? size : ICON_DEFAULT_SIZE,
    align: align === 'center' || align === 'right' ? align : 'left',
    locked: el.getAttribute('data-locked') === 'true',
  };
}

function iconDataAttrs(a: IconAttrs): Record<string, string> {
  return {
    'data-icon-block': 'true', 'data-name': a.name, 'data-color': a.color,
    'data-size': String(a.size), 'data-align': a.align,
    // Written only when it isn't the default, so solid icons serialize exactly
    // as they did before the cut existed.
    ...(a.style === 'outline' ? { 'data-style': 'outline' } : {}),
    ...(a.locked ? { 'data-locked': 'true' } : {}),
  };
}

function iconWrapHtml(a: IconAttrs): string {
  const attrs = Object.entries(iconDataAttrs(a)).map(([k, v]) => `${k}="${escapeHtml(v)}"`).join(' ');
  return `<div ${attrs} class="book-icon-wrap" style="text-align:${a.align}">${bookIconHtml(a.name, a.color, a.size, 'book-icon', a.style)}</div>`;
}

const IconBlock = Node.create({
  name: 'iconBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      name: { default: 'star' },
      style: { default: 'solid' },
      color: { default: INK },
      size: { default: ICON_DEFAULT_SIZE },
      align: { default: 'left' },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{ tag: 'div[data-icon-block]', getAttrs: (el) => iconAttrsOf(el as HTMLElement) }];
  },
  renderHTML({ node }) {
    const a = node.attrs as unknown as IconAttrs;
    const spec = bookIconSpec(a.name, a.color, a.size, 'book-icon', a.style);
    return ['div', {
      ...iconDataAttrs(a), class: 'book-icon-wrap', style: `text-align:${a.align}`,
    }, ...(spec ? [spec] : [])] as unknown as DOMOutputSpec;
  },
  addNodeView() {
    return ({ node }) => {
      const a = node.attrs as unknown as IconAttrs;
      const host = document.createElement('div');
      host.innerHTML = iconWrapHtml(a);
      const dom = host.firstElementChild as HTMLElement;
      dom.contentEditable = 'false';
      return { dom };
    };
  },
});

/* ── Social row ──────────────────────────────────────────────────────────────
   A row of profile links, for the About-the-author page.

   Handles live on the block rather than in book metadata, which reverses an
   earlier intention worth recording: the plan was to set them once beside the
   author's name and have every social block resolve them, the way [Author name]
   does. That cannot work here. resolveFieldTokens walks TEXT nodes — deliberately,
   because a token is wrapped in marks — so it can fill a name in a sentence but
   can never fill an href. A metadata-backed link would render as a live link to
   nowhere in every export. Since a book has one About-the-author page, "set once"
   was solving a problem of one.

   Handles show beside the marks by default. A strip of bare glyphs is useless
   the moment the book is printed — same rule as the QR code's printed URL and
   the video poster's caption — so the text is the default rather than the
   option. What the option is for is width: three mark-and-handle pairs fit a
   line, seven wrap into a block. An icon-only row carries the handle in
   aria-label instead, so each link still has a name for a screen reader where
   there is nothing left to read.

   Brand marks come from Simple Icons (see scripts/gen-book-icons.mjs) rather
   than being drawn here: an approximated logo is both visibly wrong and a
   trademark problem. */
/* A link, not a handle. This block used to be nine fixed per-network slots, so
   the slot you typed into was what named the mark. Two consequences made that
   worth replacing: two accounts on one network could not be expressed at all,
   and a pasted profile URL could not be trusted — it was reduced to its last
   path segment and rebuilt from the slot's template, which turned a LinkedIn
   company page into a personal profile and a Facebook group into a numeric
   vanity URL, silently, in a file the author then published.

   The list is the author's now, in their order, and the mark is read off the
   link itself. `icon` is written only when they overrode what we detected, so a
   corrected mark survives later edits to the URL. */
interface SocialLink { url: string; text?: string; icon?: string }

/* Wider than the link templates in bookIcons, which only know each network's
   canonical host: fb.me and youtu.be are the same promise to a reader, and the
   reader is who the mark is for. Anything unrecognised is a website — a correct
   answer rather than a failure, which is what spares this a "couldn't tell"
   state and spares the author a required picker. */
const SOCIAL_HOSTS: { icon: string; hosts: string[] }[] = [
  { icon: 'brand:x', hosts: ['x.com', 'twitter.com'] },
  { icon: 'brand:instagram', hosts: ['instagram.com'] },
  { icon: 'brand:linkedin', hosts: ['linkedin.com'] },
  { icon: 'brand:facebook', hosts: ['facebook.com', 'fb.com', 'fb.me'] },
  { icon: 'brand:youtube', hosts: ['youtube.com', 'youtu.be'] },
  { icon: 'brand:tiktok', hosts: ['tiktok.com'] },
  { icon: 'brand:substack', hosts: ['substack.com'] },
];

function socialHostOf(raw: string): string {
  return (raw ?? '').trim()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .toLowerCase();
}

/** The mark a link earns on its own, before any manual override. */
function detectSocialIcon(raw: string): string {
  const value = (raw ?? '').trim();
  if (!value) return 'globe';
  // An address can be written either way, and neither form has a host to read.
  if (/^mailto:/i.test(value) || /^[^\s@/]+@[^\s@/]+\.[^\s@/]+$/.test(value)) return 'mail';
  const host = socialHostOf(value);
  for (const n of SOCIAL_HOSTS) {
    // Suffix match, so a subdomain still counts: casper.substack.com is
    // Substack and m.facebook.com is Facebook.
    if (n.hosts.some((h) => host === h || host.endsWith('.' + h))) return n.icon;
  }
  return 'globe';
}

/** Where the mark points. A link that already states its scheme is used exactly
    as written — the one rule the old per-network templates could not honour. */
function socialHref(raw: string): string {
  const value = (raw ?? '').trim();
  if (!value) return '';
  if (/^mailto:/i.test(value)) return value;
  if (/^[^\s@/]+@[^\s@/]+\.[^\s@/]+$/.test(value)) return 'mailto:' + value;
  if (/^https?:\/\//i.test(value)) return value;
  return 'https://' + value.replace(/^\/+/, '');
}

/* What the reader sees beside the mark. The author's own text wins; otherwise
   it is read off the link — an address whole, a website as its bare address,
   and a profile as @handle. An empty row shows its network's name rather than a
   stray "@", so a half-filled row reads as unfinished instead of broken. */
function socialLabel(link: SocialLink, icon: string): string {
  const own = (link.text ?? '').trim();
  if (own) return own;
  const raw = (link.url ?? '').trim();
  const fallback = BOOK_ICONS_BY_NAME[icon]?.label ?? icon;
  if (!raw) return fallback;
  if (icon === 'mail') return raw.replace(/^mailto:/i, '');
  if (icon === 'globe') return raw.replace(/^https?:\/\//i, '').replace(/\/+$/, '');
  const clean = cleanHandle(raw);
  return clean ? `@${clean}` : fallback;
}

/* Read back off the rendered children rather than a JSON blob in an attribute:
   the markup stays self-describing, and there is no escaping to get wrong when
   a link contains a quote.

   Books saved under the old model carry data-handle and no data-url. Those are
   rebuilt through socialUrl from the slot they sat in, and that slot is pinned
   as an override — the author did choose the network, so detection has no
   business second-guessing it when the book reopens. */
function socialLinksOf(el: HTMLElement): SocialLink[] {
  const out: SocialLink[] = [];
  el.querySelectorAll('[data-net]').forEach((item) => {
    const net = item.getAttribute('data-net') ?? '';
    const url = item.getAttribute('data-url');
    if (url !== null) {
      if (!url.trim()) return;
      const text = item.getAttribute('data-text') ?? '';
      out.push({
        url,
        ...(text ? { text } : {}),
        ...(item.getAttribute('data-pick') === 'true' && net ? { icon: net } : {}),
      });
      return;
    }
    const handle = item.getAttribute('data-handle') ?? '';
    if (!net || !handle) return;
    const built = socialUrl(net, handle);
    if (built) out.push({ url: built, icon: net });
  });
  return out;
}

interface SocialAttrs {
  links: SocialLink[]; color: string; align: 'left' | 'center' | 'right';
  locked: boolean; showHandles: boolean; size: number;
}

/* What an empty block shows: three marks at the block's own size, greyed back.
   It used to read "Add your links in the panel on the left", which was an
   instruction to go somewhere that selecting the block already opens — and set
   in the body typeface at body size, grey, it read as a form field someone had
   left blank rather than as a block waiting for content. A ghost of the thing
   itself needs no words and cannot be mistaken for an input.

   Editor-only by construction: renderHTML emits no children when there are no
   links, so an empty block still exports as nothing rather than shipping three
   marks nobody chose. */
const SOCIAL_GHOST_MARKS = ['brand:x', 'brand:instagram', 'brand:linkedin'];
const SOCIAL_GHOST_INK = '#C2CBD6';

const SOCIAL_DEFAULT_LINKS: SocialLink[] = [];
/* Matches the size the row was hard-coded to before it was a field, so every
   book already out there renders exactly as it did. */
const SOCIAL_DEFAULT_SIZE = 18;

function socialDataAttrs(a: SocialAttrs): Record<string, string> {
  return {
    'data-social': 'true', 'data-color': a.color, 'data-align': a.align,
    'data-size': String(a.size ?? SOCIAL_DEFAULT_SIZE),
    /* Only written when it is off: absent has to parse back as on, or every row
       saved before this attribute existed would reopen with its handles gone. */
    ...(a.showHandles === false ? { 'data-handles': 'false' } : {}),
    ...(a.locked ? { 'data-locked': 'true' } : {}),
  };
}

/* In the author's order, which is a real thing to preserve now that the list is
   one they built rather than nine slots in a fixed sequence. A row with nothing
   in it stays in the panel while it is being filled but never reaches the page:
   a mark with no destination is a dead link, not a draft. */
type SocialItem = { name: string; raw: string; pinned: boolean; text: string; url: string; label: string };

function socialItems(a: SocialAttrs): SocialItem[] {
  return (a.links ?? [])
    .filter((l) => (l.url ?? '').trim())
    .map((l) => {
      const name = l.icon || detectSocialIcon(l.url);
      return {
        name,
        raw: l.url.trim(),
        pinned: !!l.icon,
        text: (l.text ?? '').trim(),
        url: socialHref(l.url),
        label: socialLabel(l, name),
      };
    });
}

function socialItemDataAttrs(it: SocialItem): Record<string, string> {
  return {
    'data-net': it.name, 'data-url': it.raw,
    ...(it.text ? { 'data-text': it.text } : {}),
    ...(it.pinned ? { 'data-pick': 'true' } : {}),
  };
}

function socialRowHtml(a: SocialAttrs): string {
  const attrs = Object.entries(socialDataAttrs(a)).map(([k, v]) => `${k}="${escapeHtml(v)}"`).join(' ');
  const items = socialItems(a);
  const size = a.size ?? SOCIAL_DEFAULT_SIZE;
  const body = items.length
    ? items.map((it) => {
        const inner = bookIconHtml(it.name, a.color, size, 'book-social-icon')
          + (a.showHandles === false ? '' : `<span class="book-social-handle">${escapeHtml(it.label)}</span>`);
        const named = a.showHandles === false
          ? ` aria-label="${escapeHtml(it.label)}" title="${escapeHtml(it.label)}"` : '';
        const data = Object.entries(socialItemDataAttrs(it)).map(([k, v]) => `${k}="${escapeHtml(v)}"`).join(' ');
        return `<span class="book-social-item" ${data}${named} style="color:${a.color}">${inner}</span>`;
      }).join('')
    : SOCIAL_GHOST_MARKS
        .map((n) => `<span class="book-social-item book-social-ghost">${bookIconHtml(n, SOCIAL_GHOST_INK, size, 'book-social-icon')}</span>`)
        .join('');
  const empty = items.length ? '' : ' data-empty="true"';
  return `<div ${attrs}${empty} class="book-social" style="text-align:${a.align}">${body}</div>`;
}

const SocialRowBlock = Node.create({
  name: 'socialRowBlock',
  group: 'block',
  atom: true,
  addAttributes() {
    return {
      links: {
        default: SOCIAL_DEFAULT_LINKS,
        parseHTML: (el: HTMLElement) => socialLinksOf(el),
        renderHTML: () => ({}),
      },
      color: { default: INK },
      align: { default: 'left' },
      showHandles: { default: true },
      size: { default: SOCIAL_DEFAULT_SIZE },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-social]',
      getAttrs: (el) => {
        const box = el as HTMLElement;
        const align = box.getAttribute('data-align');
        return {
          links: socialLinksOf(box),
          color: box.getAttribute('data-color') || INK,
          align: align === 'center' || align === 'right' ? align : 'left',
          showHandles: box.getAttribute('data-handles') !== 'false',
          size: Number(box.getAttribute('data-size')) || SOCIAL_DEFAULT_SIZE,
          locked: box.getAttribute('data-locked') === 'true',
        };
      },
    }];
  },
  renderHTML({ node }) {
    const a = node.attrs as unknown as SocialAttrs;
    const items = socialItems(a);
    const children = items.map((it) => {
      const spec = bookIconSpec(it.name, a.color, a.size ?? SOCIAL_DEFAULT_SIZE, 'book-social-icon');
      const labelled = a.showHandles !== false;
      const inner: unknown[] = [
        ...(spec ? [spec] : []),
        ...(labelled ? [['span', { class: 'book-social-handle' }, it.label]] : []),
      ];
      const common = {
        class: 'book-social-item', ...socialItemDataAttrs(it),
        style: `color:${a.color}`,
        ...(labelled ? {} : { 'aria-label': it.label, title: it.label }),
      };
      // Same rule as the button: no href means a <span>, never a dead anchor.
      return it.url ? ['a', { ...common, href: it.url }, ...inner] : ['span', common, ...inner];
    });
    return ['div', {
      ...socialDataAttrs(a), class: 'book-social', style: `text-align:${a.align}`,
    }, ...children] as unknown as DOMOutputSpec;
  },
  addNodeView() {
    return ({ node }) => {
      const a = node.attrs as unknown as SocialAttrs;
      const host = document.createElement('div');
      host.innerHTML = socialRowHtml(a);
      const dom = host.firstElementChild as HTMLElement;
      dom.contentEditable = 'false';
      return { dom };
    };
  },
});

/* The banner paints its own background, so nothing below it can be a fixed
   colour: the heading was the theme's heading colour and the body a literal
   #52637A, both of which vanish the moment somebody picks a dark fill — and the
   fill is a free colour picker, so that is one click away rather than an exotic
   case. Same rule as buttonInkFor, applied to a box instead of a button.

   The colours below are literal hex, not tokens: this string is written into
   EXPORTED markup, and lib/epub.ts defines no :root, so a var() would resolve
   to nothing in a reading system. (buttonInkFor used to have that bug and now
   returns INK_HEX for the same reason.) */
function jumbotronIsDark(bg: string): boolean {
  return /^#[0-9a-fA-F]{6}$/.test(bg) ? relativeLuminance(bg) <= 0.55 : false;
}
/* Banners saved before the block held real content are three strings in three
   divs. Rewritten here, once, on the way into the editor — the same place
   migrateCoverBg runs, and for the same reason: the parser cannot do it, because
   `div[data-jb-body]` matches no paragraph rule and `div[data-jb-button]`
   matches no button rule, so a straight re-parse would drop the body and the
   button on the floor and ProseMirror would refill both with defaults. Which is
   to say: it would silently delete what the author wrote.

   Deliberately narrow. It only fires on a banner that still has the old
   children, it carries the button's colour and size across to the real button
   that replaces it, and it leaves a banner already in the new shape untouched,
   so running twice is a no-op. The button lands centred because that is where
   the old painted one always sat. */
function migrateJumbotronHtml(html: string): string {
  if (!html || !html.includes('data-jumbotron')) return html;
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, 'text/html');
  let touched = false;
  doc.querySelectorAll('div[data-jumbotron]').forEach((box) => {
    const oldHeading = box.querySelector('[data-jb-heading]');
    const oldBody = box.querySelector('[data-jb-body]');
    const oldButton = box.querySelector('[data-jb-button]');
    // Already migrated: a real button block sits inside instead of a painted one.
    if (!oldBody && !oldButton) return;
    touched = true;
    const title = doc.createElement('div');
    title.setAttribute('data-jb-heading', 'true');
    title.textContent = oldHeading?.textContent ?? '';
    const body = doc.createElement('p');
    body.textContent = oldBody?.textContent ?? '';
    const wrap = doc.createElement('div');
    wrap.setAttribute('data-button', 'true');
    wrap.setAttribute('data-url', box.getAttribute('data-url') ?? oldButton?.getAttribute('href') ?? '');
    wrap.setAttribute('data-color', box.getAttribute('data-btn-color') || BUTTON_DEFAULT_BG);
    wrap.setAttribute('data-size', buttonSizeOf(box.getAttribute('data-btn-size')));
    wrap.setAttribute('data-align', 'center');
    // The icon slots start empty: the old painted button had no icon, so giving
    // the replacement the Button tile's default arrow would be inventing one.
    wrap.setAttribute('data-icon-left', '');
    wrap.setAttribute('data-icon-right', '');
    const label = doc.createElement('span');
    label.className = 'book-button-label';
    label.textContent = oldButton?.textContent ?? '';
    const btn = doc.createElement('span');
    btn.className = 'book-button';
    btn.appendChild(label);
    wrap.appendChild(btn);
    box.replaceChildren(title, body, wrap);
    // Attributes that belonged to the painted button and now belong to the real
    // one. Left behind, they would be read back by nothing and confuse the next
    // person to open this markup.
    for (const a of ['data-url', 'data-btn-color', 'data-btn-size']) box.removeAttribute(a);
  });
  return touched ? doc.body.innerHTML : html;
}

/* Old Designrr's "Inline CTA / Jumbotron" — a self-contained hero section
   (heading + body + button + its own background) droppable mid-chapter.

   It used to be an ATOM holding three strings, and that was the whole problem:
   clicking the button inside it selected the banner, because there was no
   button there to select — just text painted to look like one. So the banner
   grew its own small copies of controls the real Button block already had, and
   the heading and body could never be bold, linked or restyled at all.

   It is a CONTAINER now, holding a title, a paragraph and a REAL buttonBlock.
   Clicking the text gives you the text panel, clicking the button gives you the
   button's own panel, and clicking once more out gives you the banner's. That
   is the WordPress Cover model (a container whose inner blocks keep their own
   settings, with the container setting what cascades) rather than the Elementor
   widget model (one sealed thing whose panel re-lists every sub-part), and it
   is also what this editor already does for stacks, columns and photo grids —
   see isLayoutContainer, which the banner is now a member of.

   The content expression is exact rather than `block+`: a banner is these three
   things in this order, and ProseMirror refills any one of them that gets
   deleted, so the shape cannot be broken from the inside. That is the same job
   Gutenberg's "Allowed Blocks" does for Cover. */

/* The title is NOT a `heading` node, and the reason is load-bearing rather than
   stylistic: addHeadingIds in lib/epub.ts regex-scans every exported chapter for
   h3/h4 and turns each one into an entry in the EPUB navigation document. A
   banner titled "Get the companion workbook" would file itself in the reader's
   table of contents as though it were a section of the book — and because that
   function numbers headings by document order to mint anchor ids, dropping a
   banner mid-chapter would renumber every heading after it and move the targets
   of existing internal links.

   So it is its own node that renders a div, exactly as the old string did.
   chapterTitle is the precedent: it, too, is a title that is deliberately not a
   heading level, and TextInspector already special-cases it. */
const JumbotronTitle = Node.create({
  name: 'jumbotronTitle',
  content: 'inline*',
  defining: true,
  parseHTML() {
    return [{ tag: 'div[data-jb-heading]' }];
  },
  renderHTML() {
    return ['div', { 'data-jb-heading': 'true', class: 'book-jumbotron-heading' }, 0];
  },
});

/* The markup the Insert tile drops. It has to parse back into exactly the three
   children the content expression names, so it is built from buttonTileHtml
   rather than written out by hand. */
function jumbotronTileHtml(): string {
  const button = buttonTileHtml({
    ...BUTTON_TILE_ATTRS, label: 'Get it now', align: 'center', iconRight: '',
  });
  return '<div data-jumbotron="true" data-bg="#EEF3FF">'
    + '<div data-jb-heading="true">Get the companion workbook</div>'
    + '<p>A short line of supporting copy.</p>'
    + button
    + '</div>';
}

const JumbotronBlock = Node.create({
  name: 'jumbotronBlock',
  group: 'block',
  content: 'jumbotronTitle paragraph buttonBlock',
  defining: true,
  isolating: true,
  addAttributes() {
    return {
      bgColor: {
        default: '#EEF3FF',
        /* Rendered by hand below as data-bg and as the background style, so it
           must not ALSO render itself. Once renderHTML started merging
           HTMLAttributes (so the width from BlockSize could get through), the
           default renderer began emitting a stray `bgcolor="#EEF3FF"` — a real,
           long-deprecated HTML attribute, in every export. */
        renderHTML: () => ({}),
      },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-jumbotron]',
      getAttrs: (el) => ({
        bgColor: (el as HTMLElement).getAttribute('data-bg') || '#EEF3FF',
        locked: (el as HTMLElement).getAttribute('data-locked') === 'true',
      }),
    }];
  },
  renderHTML({ HTMLAttributes, node }) {
    const { bgColor } = node.attrs as { bgColor: string };
    /* The ink goes on the CONTAINER as a flag, not on each child as an inline
       colour. Two reasons. The children render themselves now, so the parent
       has nothing to stamp; and an inline colour on the body would be
       indistinguishable from one the author set in the text panel, so clearing
       theirs could not put the automatic one back. A data attribute leaves the
       stylesheet in charge and leaves authored colour free to override it. */
    /* mergeAttributes, not a plain object: `boxW` is a GLOBAL attribute (see
       BlockSize), and the width it writes arrives through HTMLAttributes. Built
       by hand, this div dropped it on the floor — the Size field and the resize
       handles both wrote the attribute, the banner just never rendered it, so
       dragging the handle did nothing. mergeAttributes also joins the two style
       strings instead of one clobbering the other. */
    return ['div', mergeAttributes(HTMLAttributes, {
      'data-jumbotron': 'true', 'data-bg': bgColor,
      ...(jumbotronIsDark(bgColor) ? { 'data-ink': 'dark' } : {}),
      ...(node.attrs.locked ? { 'data-locked': 'true' } : {}),
      class: 'book-jumbotron', style: `background:${bgColor}`,
    }), 0] as unknown as DOMOutputSpec;
  },
});

/* Multi-column flowing text — the same CSS column-count technique the chapter-level
   "Two-column" layout already uses, just droppable mid-chapter instead of applying to
   a whole chapter. One content slot rather than N separate column slots: content
   flows across the columns like a newspaper, matching old Designrr's own block. */
const ColumnsBlock = Node.create({
  name: 'columnsBlock',
  group: 'block',
  content: 'block+',
  defining: true,
  addAttributes() {
    return {
      columns: { default: 2 },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{ tag: 'div[data-columns]', getAttrs: (el) => ({ columns: Number((el as HTMLElement).getAttribute('data-columns')) || 2 }) }];
  },
  renderHTML({ HTMLAttributes, node }) {
    const { columns } = node.attrs as { columns: number };
    return ['div', mergeAttributes(HTMLAttributes, { 'data-columns': String(columns), class: `book-columns book-columns--${columns}` }), 0];
  },
});

/* `ratio` only means anything at two columns — it's the width SPLIT between the
   pair, and three or four cells have no 1:3 to express. Kept as its own
   attribute rather than folded into `cols` (a '1-3' column count isn't a
   number, and every count-based path here does arithmetic on it); switching to
   3 or 4 columns resets it, see setGridColumns. */
type GridRatio = 'equal' | '1-3' | '3-1';
interface GridAttrs { cols: number; ratio: GridRatio; boxW: number; boxH: number; fit: string; lockAspect: boolean; locked: boolean }

/* The grid div's attributes, in one place, feeding both renderings — the node
   view's live DOM and renderHTML's exported markup. Same split as
   imageFigureParts, for the same reason: two copies of this drifted apart the
   moment either one gained an attribute. */
function gridDivAttrs(attrs: GridAttrs): Record<string, string> {
  const { cols, ratio, boxW, boxH, fit } = attrs;
  // An uneven split is still a 2-column grid: it keeps --2 (so anything keyed to
  // the count, including the EPUB float fallback, still matches) and adds the
  // ratio class on top to override the template.
  const uneven = cols === 2 && ratio && ratio !== 'equal';
  const sizing: string[] = [];
  // 0 means "fits the column", which is the state you have until you set a
  // width — same convention as `image`, and Reset puts it back.
  if (boxW) sizing.push(`width:${boxW}px`, 'max-width:100%', 'margin-left:auto', 'margin-right:auto');
  if (boxH) sizing.push(`height:${boxH}px`);
  return {
    'data-image-grid': 'true',
    'data-cols': String(cols),
    ...(boxW ? { 'data-w': String(boxW) } : {}),
    ...(boxH ? { 'data-h': String(boxH) } : {}),
    'data-fit': fit,
    ...(uneven ? { 'data-ratio': ratio } : {}),
    class: `book-image-grid book-image-grid--${cols}${uneven ? ` book-image-grid--${ratio}` : ''}`,
    ...(sizing.length ? { style: sizing.join(';') } : {}),
  };
}

/* Image grid — a CSS-grid container so dropped-in images (WrappableImage figures)
   arrange in true grid cells rather than the wrap wrappers finding their own
   position, like old Designrr's Image Grid 2/3/4 layout blocks. */
const ImageGridBlock = Node.create({
  name: 'imageGridBlock',
  group: 'block',
  content: 'block+',
  defining: true,
  addAttributes() {
    return {
      cols: { default: 2 },
      ratio: {
        default: 'equal' as GridRatio,
        parseHTML: (el: HTMLElement) => (el.getAttribute('data-ratio') as GridRatio) ?? 'equal',
        renderHTML: () => ({}),
      },
      /* How every cell's photo fills its cell. A grid gives each cell a fixed
         shape, so unlike a lone photo there IS a real mismatch to resolve — and
         it belongs here rather than per-cell, because a grid whose cells were
         individually trimmed and letterboxed would stop reading as a grid. */
      fit: {
        default: 'cover',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-fit') ?? 'cover',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.fit === 'contain' ? { 'data-fit': 'contain' } : {}),
      },
      /* Size of the WHOLE grid. Resizing a photo inside it only ever changed
         that one cell; there was no way to make the block itself narrower,
         which is what you want when a four-up grid dominates the page. Same
         model as `image` on purpose — W/H in px with 0 meaning "fits the
         column" — so one size vocabulary covers both, and `fit` says how each
         photo sits in the cell the grid gives it. */
      boxW: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-w') ?? 0), renderHTML: () => ({}) },
      boxH: { default: 0, parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-h') ?? 0), renderHTML: () => ({}) },
      lockAspect: { default: true, parseHTML: (el: HTMLElement) => el.getAttribute('data-lock-aspect') !== 'false', renderHTML: () => ({}) },
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
    };
  },
  parseHTML() {
    return [{
      tag: 'div[data-image-grid]',
      getAttrs: (el) => ({
        cols: Number((el as HTMLElement).getAttribute('data-cols')) || 2,
        ratio: ((el as HTMLElement).getAttribute('data-ratio') as GridRatio) ?? 'equal',
        boxW: Number((el as HTMLElement).getAttribute('data-w') ?? 0),
        boxH: Number((el as HTMLElement).getAttribute('data-h') ?? 0),
        lockAspect: (el as HTMLElement).getAttribute('data-lock-aspect') !== 'false',
        fit: (el as HTMLElement).getAttribute('data-fit') ?? 'cover',
      }),
    }];
  },
  renderHTML({ HTMLAttributes, node }) {
    return ['div', mergeAttributes(HTMLAttributes, gridDivAttrs(node.attrs as GridAttrs)), 0];
  },
  /* A node view purely so the grid can carry resize handles. Everything about
     how the grid itself renders still comes from gridDivAttrs, the same
     function renderHTML uses, so the live DOM and the exported HTML cannot
     drift — the split imageFigureParts already makes for a figure.

     The handles need a positioned box that is NOT the grid: the grid is a CSS
     grid, and an extra child of it would be laid out as another cell. So the
     node view wraps the grid in a plain block, keeps contentDOM on the grid
     itself, and hangs the handles off the wrapper. Export never sees the
     wrapper. */
  addNodeView() {
    return ({ node, getPos, editor }) => {
      const dom = document.createElement('div');
      dom.className = 'book-image-grid-wrap';
      const grid = document.createElement('div');
      let selected = false;

      const paint = (n: PMNode) => {
        const attrs = gridDivAttrs(n.attrs as GridAttrs);
        for (const a of Array.from(grid.attributes)) {
          if (a.name !== 'class' && a.name !== 'style' && !(a.name in attrs)) grid.removeAttribute(a.name);
        }
        for (const [k, v] of Object.entries(attrs)) grid.setAttribute(k, v);
        if (!('style' in attrs)) grid.removeAttribute('style');
      };

      const markSelected = () => {
        dom.classList.toggle('ProseMirror-selectednode', selected);
        const pos = typeof getPos === 'function' ? getPos() : null;
        const live = pos == null ? null : editor.state.doc.nodeAt(pos);
        const isLocked = !!(live?.attrs as GridAttrs | undefined)?.locked;
        handles.style.display = selected && editor.isEditable && !isLocked ? 'block' : 'none';
      };

      const handles = buildResizeHandles((corner, e) => {
        if (typeof getPos !== 'function') return;
        const pos = getPos();
        if (pos == null) return;
        const current = editor.state.doc.nodeAt(pos);
        if (!current || current.type.name !== 'imageGridBlock') return;
        const attrs = current.attrs as GridAttrs;
        if (attrs.locked) return;
        dragResize({
          box: grid,
          corner,
          event: e,
          lockAspect: attrs.lockAspect !== false,
          maxW: dom.parentElement?.clientWidth ?? 0,
          commit: (w, h) => {
            const at = getPos();
            if (at == null) return;
            const node2 = editor.state.doc.nodeAt(at);
            if (!node2 || node2.type.name !== 'imageGridBlock') return;
            editor.view.focus();
            editor.chain().setNodeSelection(at).updateAttributes('imageGridBlock', { boxW: w, boxH: h }).run();
          },
        });
      });

      dom.appendChild(grid);
      dom.appendChild(handles);
      paint(node);

      return {
        dom,
        contentDOM: grid,
        update: (updated: PMNode) => {
          if (updated.type.name !== 'imageGridBlock') return false;
          paint(updated);
          markSelected();
          return true;
        },
        selectNode: () => { selected = true; markSelected(); },
        deselectNode: () => { selected = false; markSelected(); },
        stopEvent: (e: Event) => !!e.target && handles.contains(e.target as globalThis.Node),
        ignoreMutation: (m: { target: globalThis.Node }) => handles.contains(m.target) || m.target === grid,
      };
    };
  },
});

/* TipTap's own TableView copies a table's rendered attributes onto the <table>
   element in its CONSTRUCTOR and never again — its update() re-measures the
   colgroup and nothing else. So banding or cell padding changed on a table
   already on the page updated the document and changed nothing on screen: the
   transaction landed, the attribute was in the doc, and the DOM still had
   whatever the node view built the first time. This re-applies them on every
   update, which is the only reason the Table extension takes a `View` option.

   setProperty rather than the constructor's cssText assignment: by update time
   updateColumns has written a min-width onto the same element, and replacing
   the whole declaration would drop it. */
function syncTableDom(table: HTMLTableElement, node: PMNode) {
  /* TableView builds its own <table> and copies nothing off the node, so the
     class never reached the DOM while editing — a `book-split-columns` stack
     rendered as a plain data table, complete with the borders and cell rules a
     layout is defined by NOT having. It came out right on export, where
     renderHTML runs instead of the node view, which is why only the canvas
     showed it. Reconciled through a token list rather than assigned, because
     ProseMirror puts its own classes on this element too (selectednode among
     them) and className = would drop them; data-book-cls remembers what we put
     there so the next sync can take exactly that back off. */
  const cls = String(node.attrs.class || '').trim();
  const prev = table.dataset.bookCls || '';
  if (prev !== cls) {
    prev.split(/\s+/).forEach((c) => c && table.classList.remove(c));
    cls.split(/\s+/).forEach((c) => c && table.classList.add(c));
    if (cls) table.dataset.bookCls = cls;
    else delete table.dataset.bookCls;
  }
  const bw = Number(node.attrs.bw) || 0;
  if (bw) table.style.setProperty('--book-tbl-bw', `${bw}px`);
  else table.style.removeProperty('--book-tbl-bw');
  const bc = String(node.attrs.bc || '');
  if (bc) table.style.setProperty('--book-tbl-bc', bc);
  else table.style.removeProperty('--book-tbl-bc');
  /* Used as chosen. The control offers the highlight palette, whose colours are
     already safe behind body text, so weakening them here would only make the
     stripe fainter than the swatch that promised it. */
  const tint = String(node.attrs.tint || '');
  if (tint) {
    table.style.setProperty('--book-tbl-tint', tint);
  } else {
    table.style.removeProperty('--book-tbl-tint');
  }
  const tstyle = String(node.attrs.tstyle || 'plain');
  if (tstyle !== 'plain') table.setAttribute('data-table-style', tstyle);
  else table.removeAttribute('data-table-style');
  if (node.attrs.locked) table.setAttribute('data-locked', 'true');
  else table.removeAttribute('data-locked');
  const pad = Number(node.attrs.pad) || 0;
  if (pad) table.style.setProperty('--book-cell-pad', `${pad}px`);
  else table.style.removeProperty('--book-cell-pad');
}

class BookTableView extends TableView {
  /* Also on construction, not only on update: a stack inserted and never
     touched again never gets an update() call, so the class has to land the
     moment the view is built or the block stays bordered until you edit it. */
  constructor(...args: ConstructorParameters<typeof TableView>) {
    super(...args);
    syncTableDom(this.table, args[0]);
  }
  update(node: PMNode) {
    const ok = super.update(node);
    if (ok) syncTableDom(this.table, node);
    return ok;
  }
}

/* Table, extended with the same `locked` attribute every other movable block
   gets — its own parseHTML/renderHTML already round-trip via HTMLAttributes,
   so declaring the attribute is the entire change needed. */
/* prosemirror-tables resizes COLUMNS and has no notion of row height, so this
   adds one: a plain pixel height on the <tr>, which a table treats as a minimum
   rather than a cap — a row never clips the text inside it, it only grows. The
   pagination measures rendered rows, so a resized row repaginates by itself. */
const SizedTableRow = TableRow.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      height: {
        default: null,
        parseHTML: (el: HTMLElement) => {
          const h = parseInt(el.style.height || '', 10);
          return Number.isFinite(h) ? h : null;
        },
        renderHTML: (attrs: Record<string, unknown>) => (attrs.height ? { style: `height:${attrs.height}px` } : {}),
      },
    };
  },
});

/* Per-CELL properties, on both cell types so a header can be filled too.
   TipTap merges `style` across attributes by parsing its entries, so the two
   below compose instead of overwriting each other.

   A fill lives on the cell rather than in the sheet because it is a deliberate
   accent on one cell — a totals row, a "don't do this" column — which is
   exactly what a table-wide style cannot express. Being inline it also wins
   over the striped style's own tint, which is the right precedence: a colour
   someone chose beats one a style supplied. */
const CELL_STYLE_ATTRS = {
  bg: {
    default: null as string | null,
    parseHTML: (el: HTMLElement) => el.style.backgroundColor || null,
    renderHTML: (attrs: Record<string, unknown>) => (attrs.bg ? { style: `background-color: ${String(attrs.bg)}` } : {}),
  },
  valign: {
    default: null as string | null,
    parseHTML: (el: HTMLElement) => el.style.verticalAlign || null,
    renderHTML: (attrs: Record<string, unknown>) => (attrs.valign ? { style: `vertical-align: ${String(attrs.valign)}` } : {}),
  },
};

const StyledTableCell = TableCell.extend({
  addAttributes() { return { ...this.parent?.(), ...CELL_STYLE_ATTRS }; },
});
const StyledTableHeader = TableHeader.extend({
  addAttributes() { return { ...this.parent?.(), ...CELL_STYLE_ATTRS }; },
});

const LockableTable = Table.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      locked: {
        default: false,
        parseHTML: (el: HTMLElement) => el.getAttribute('data-locked') === 'true',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.locked ? { 'data-locked': 'true' } : {}),
      },
      /* The colour the style is drawn in — the stripe's tint and the bold
         header's fill are the same hue at two strengths. Stored as a plain hex
         and weakened in syncTableDom rather than offered as a fill the author
         sets directly: a stripe at full strength competes with the text, which
         is the failure mode a free colour picker on a table always finds. */
      tint: {
        default: '',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-tint') || '',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.tint ? { 'data-tint': String(attrs.tint) } : {}),
      },
      /* The rules themselves, published as custom properties the cell rule
         reads — one pair for the whole table. Per-EDGE borders are what Docs
         and Word paint onto a cell selection; this is the part of it a book
         table actually needs, and it composes with the style gallery rather
         than fighting it. */
      bw: {
        default: 0,
        parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-bw')) || 0,
        renderHTML: (attrs: Record<string, unknown>) => (attrs.bw ? { 'data-bw': String(attrs.bw) } : {}),
      },
      bc: {
        default: '',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-bc') || '',
        renderHTML: (attrs: Record<string, unknown>) => (attrs.bc ? { 'data-bc': String(attrs.bc) } : {}),
      },
      /* The table's look, as ONE named style rather than a pile of independent
         switches. It is a property of the table and not a colour painted onto
         rows: the rows a stripe tints have to change when a row is inserted,
         and a fill stored per row would leave the stripe order wrong the moment
         one is. The sheet does the counting — see the [data-table-style] rules.

         `data-banded` is the old boolean this replaced, read here so a table
         saved with striping keeps it. */
      tstyle: {
        default: 'plain',
        parseHTML: (el: HTMLElement) => el.getAttribute('data-table-style')
          || (el.getAttribute('data-banded') === 'true' ? 'striped' : 'plain'),
        renderHTML: (attrs: Record<string, unknown>) => (attrs.tstyle && attrs.tstyle !== 'plain' ? { 'data-table-style': String(attrs.tstyle) } : {}),
      },
      /* One number for all four sides, published as a custom property the cell
         rule reads. 0 means "unset", so a table made before this attribute
         existed keeps the sheet's own 8/12 rather than collapsing to no padding.
         The horizontal pad stays 1.5x the vertical because that ratio is what a
         table cell has always looked like here. */
      pad: {
        default: 0,
        parseHTML: (el: HTMLElement) => Number(el.getAttribute('data-pad')) || 0,
        renderHTML: (attrs: Record<string, unknown>) => {
          const n = Number(attrs.pad) || 0;
          return n ? { 'data-pad': String(n), style: `--book-cell-pad:${n}px` } : {};
        },
      },
    };
  },
});

/* TipTap's stock nodes drop any class attribute they didn't put there
   themselves — Author name/Display text are otherwise plain paragraphs,
   and the asymmetric-columns
   layout (book-split-columns) is otherwise a plain table, so without this
   their class (and with it, all their styling) would silently vanish the
   moment the HTML round-trips through parseHTML. */
const ParagraphClass = Extension.create({
  name: 'paragraphClass',
  addGlobalAttributes() {
    return [{
      types: ['paragraph', 'bulletList', 'table', 'orderedList'],
      attributes: {
        class: {
          default: null,
          parseHTML: (el) => el.getAttribute('class'),
          renderHTML: (attrs) => (attrs.class ? { class: attrs.class } : {}),
        },
      },
    }, {
      // Pairs a footnote's list-item entry back to its inline reference by a
      // stable id (not document position — position breaks under out-of-order
      // deletion, id doesn't) — see applyFootnoteNumbering in lib/footnotes.ts.
      types: ['listItem'],
      attributes: {
        'data-fid': {
          default: null,
          parseHTML: (el) => el.getAttribute('data-fid'),
          renderHTML: (attrs) => (attrs['data-fid'] ? { 'data-fid': attrs['data-fid'] } : {}),
        },
      },
    }];
  },
});

/* StarterKit's own horizontalRule, re-declared so a divider can carry a look.
   Every value lands in one composed inline `style` rather than five attributes
   each emitting their own — mergeAttributes concatenates `class` and `style`
   specially, and relying on five separate contributions to merge cleanly into one
   declaration is the kind of thing that works until a TipTap minor bump.
   Also re-read from data-* on parse, so a divider survives the HTML round-trip
   that chapter content is stored and exported as. */
interface DividerAttrs { color: string; thickness: number; widthPct: number; radius: number; align: 'left' | 'center' | 'right' }
const DIVIDER_DEFAULTS: DividerAttrs = { color: BORDER, thickness: 1, widthPct: 100, radius: 0, align: 'center' };
const numAttr = (name: string, fallback: number) => ({
  default: fallback,
  parseHTML: (el: HTMLElement) => {
    const n = Number(el.getAttribute(`data-${name}`));
    return Number.isFinite(n) && n > 0 ? n : fallback;
  },
  renderHTML: () => ({}),
});
const Divider = HorizontalRule.extend({
  addAttributes() {
    return {
      color: { default: DIVIDER_DEFAULTS.color, parseHTML: (el: HTMLElement) => el.getAttribute('data-color') || DIVIDER_DEFAULTS.color, renderHTML: () => ({}) },
      thickness: numAttr('thickness', DIVIDER_DEFAULTS.thickness),
      widthPct: numAttr('width', DIVIDER_DEFAULTS.widthPct),
      // radius can legitimately be 0, so it can't use numAttr's >0 guard.
      radius: {
        default: DIVIDER_DEFAULTS.radius,
        parseHTML: (el: HTMLElement) => {
          const n = Number(el.getAttribute('data-radius'));
          return Number.isFinite(n) && n >= 0 ? n : DIVIDER_DEFAULTS.radius;
        },
        renderHTML: () => ({}),
      },
      align: {
        default: DIVIDER_DEFAULTS.align,
        parseHTML: (el: HTMLElement) => {
          const a = el.getAttribute('data-align');
          return a === 'left' || a === 'right' ? a : 'center';
        },
        renderHTML: () => ({}),
      },
    };
  },
  renderHTML({ HTMLAttributes, node }) {
    const { color, thickness, widthPct, radius, align } = node.attrs as {
      color: string; thickness: number; widthPct: number; radius: number; align: 'left' | 'center' | 'right';
    };
    /* Deliberately unchanged by the hit-area fix below: this style string is
       what gets stored and exported, and every trick for growing a 1px box
       (padding plus background-clip, transparent borders) relies on CSS a
       reading system might not implement — where it doesn't, the rule paints
       across the whole padded box and a divider exports as a thick bar. The
       editor grows the target with a pseudo-element instead, which never
       leaves the canvas. */
    const margin = align === 'left' ? '26px auto 26px 0' : align === 'right' ? '26px 0 26px auto' : '26px auto';
    return ['hr', mergeAttributes(HTMLAttributes, {
      'data-color': color, 'data-thickness': String(thickness), 'data-width': String(widthPct),
      'data-radius': String(radius), 'data-align': align,
      style: `border:none;background:${color};height:${thickness}px;width:${widthPct}%;border-radius:${radius}px;margin:${margin};`,
    })];
  },
});

/* Straight quotes are the single most visible tell of an unfinished manuscript —
   typographers call them dumb quotes, and no printed book uses them. Every author
   types " and ' because that is what the keyboard has, so this converts as you go
   rather than leaving it to a character picker nobody opens. Written as local
   input rules instead of pulling in @tiptap/extension-typography: it is ~20 lines
   of the same thing, and the pack's other conversions (1/2 → ½, -> → →) are not
   ones we want firing unannounced inside book prose.
   Opening vs closing is decided by what precedes the quote — start of a block, or
   whitespace/an opening bracket, means opening; anything else means closing. That
   same rule gives don't → don’t for free, since the apostrophe follows a letter. */
const SmartTypography = Extension.create({
  name: 'smartTypography',
  addInputRules() {
    return [
      textInputRule({ find: /(?:^|[\s([{<])(")$/, replace: '“' }),
      textInputRule({ find: /"$/, replace: '”' }),
      textInputRule({ find: /(?:^|[\s([{<])(')$/, replace: '‘' }),
      textInputRule({ find: /'$/, replace: '’' }),
      // Three dots before two hyphens, or "..--" would resolve the wrong way.
      textInputRule({ find: /\.\.\.$/, replace: '…' }),
      // En dash for a range typed as 1-5 would be wrong as often as right, so
      // only the explicit double hyphen converts, and it converts to an em dash
      // the way every word processor does.
      textInputRule({ find: /--$/, replace: '—' }),
    ];
  },
});

/* ── selection rings ──────────────────────────────────────────────────────────
   An atom object (image, shape, embed, QR, jumbotron…) already draws a solid
   ring through ProseMirror's own selectednode class. A container block does
   not: columns/table/callout/blockquote aren't atoms, so the live selection
   sits inside their content and nothing on the page was ever marked. You could
   have a 2-column block active — its floating duplicate/delete bar showing, its
   Properties panel open — with no indication of which block either one was
   about to act on.

   Two tiers, so "an object is selected" and "the caret is here" can't be
   mistaken for each other: a solid ring on the active container, and, when the
   caret is in ordinary prose instead, the same soft blue glow the chapter-title
   field already uses on focus. Decorations, not node-view styling, so neither
   ever round-trips into the saved HTML or the export. */
/* ── layout stacks ────────────────────────────────────────────────────────────
   Columns, Photo and text and the side-by-side text templates all insert the
   same thing: a `book-split-columns` table. It is a table in the document model
   only — one row of independently-edited cells used as a layout, no borders,
   nothing tabular about it — so it behaves like the photo grid instead: the
   first click selects the stack, the second takes whatever is in the cell.
   Before this, a caret anywhere inside one reported as a table, so Properties
   showed rows/columns/size and the text in the columns could never be formatted
   at all — the column count was the only thing the panel would ever offer. */
const STACK_CLASS = 'book-split-columns';

function isStackNode(node: PMNode | null | undefined): boolean {
  if (!node || node.type.name !== 'table') return false;
  const cls = node.attrs.class;
  return typeof cls === 'string' && cls.includes(STACK_CLASS);
}

/* A `columnsBlock` is the other layout container and drills in identically: it
   is one text stream flowed into CSS columns, so a caret inside it belongs to
   the prose, not to the box. Before this it reported as the container from
   anywhere inside, which meant Properties only ever offered the column count —
   the text in the columns could never be formatted, the same dead end stacks
   used to have. */
function isLayoutContainer(node: PMNode | null | undefined): boolean {
  /* The banner joined these when it stopped being an atom. Same contract as the
     other two: one click selects the banner, the next reaches the title, the
     body or the button inside it. */
  /* The two Forms blocks joined for the same reason the banner did: most of a
     question is NOT text — the ruled lines are the bulk of it, and before this a
     click anywhere on them did nothing at all, so the block could only be reached
     through the one paragraph at the top of it. One click now takes the whole
     question, the next reaches the prompt. */
  return !!node && (isStackNode(node) || node.type.name === 'columnsBlock' || node.type.name === 'jumbotronBlock'
    || node.type.name === 'questionBlock' || node.type.name === 'choiceBlock');
}

/* The CELL a document position sits in, or -1. A stack's cells are layout
   columns and drill in as a container instead — see isLayoutContainer. */
function cellPosAt(doc: PMNode, pos: number): number {
  if (pos < 0 || pos > doc.content.size) return -1;
  const $at = doc.resolve(pos);
  for (let d = $at.depth; d > 0; d -= 1) {
    const name = $at.node(d).type.name;
    if (name === 'tableCell' || name === 'tableHeader') {
      // A stack's own cells are columns, not table cells.
      for (let u = d - 1; u > 0; u -= 1) {
        if ($at.node(u).type.name === 'table') return isStackNode($at.node(u)) ? -1 : $at.before(d);
      }
      return $at.before(d);
    }
  }
  return -1;
}

/* One click selects the CELL, a second puts the caret in it — the two-stage
   step every design tool uses, and what Canva does with a table specifically.
   `cellBefore` is the cell the selection was in when the mouse went down: the
   browser has already moved the caret by the time this runs, so the previous
   cell has to be captured on mousedown exactly as the container drill-in does.
   Clicking a cell you were already in falls through, which is what makes the
   second click start editing. */
function selectCellAt(view: EditorView, pos: number, cellBefore: number): boolean {
  const target = cellPosAt(view.state.doc, pos);
  if (target < 0 || target === cellBefore) return false;
  view.focus();
  view.dispatch(view.state.tr.setSelection(CellSelection.create(view.state.doc, target)));
  return true;
}

/* What to CALL the container a position sits in. The header beside the back
   arrow names where that arrow goes, and it used to say "Columns" for every
   layout container because the only two were a stack and a columns block, which
   are both columns. The banner joined them and is not. */
function layoutContainerLabel(doc: PMNode, pos: number): string {
  const at = layoutContainerPosAt(doc, pos);
  const name = at >= 0 ? doc.nodeAt(at)?.type.name : null;
  if (name === 'jumbotronBlock') return 'Banner';
  /* Named the way their Properties groups are, so the back arrow and the panel
     above it agree about what you are standing in. */
  if (name === 'questionBlock' || name === 'choiceBlock') return 'Question';
  return 'Columns';
}

/* The layout container a document position sits inside, or -1. Innermost first,
   so a stack nested in a columns block selects as the stack. */
function layoutContainerPosAt(doc: PMNode, pos: number): number {
  if (pos < 0 || pos > doc.content.size) return -1;
  const $at = doc.resolve(pos);
  for (let d = $at.depth; d > 0; d -= 1) if (isLayoutContainer($at.node(d))) return $at.before(d);
  return -1;
}

/* The container the selection is already in — either selected whole (the first
   click) or drilled into (everything after). -1 when the selection is outside
   every one of them, which is what makes the next click on one select it. */
function enteredContainerPos(state: EditorState): number {
  const { selection } = state;
  if (selection instanceof NodeSelection && isLayoutContainer(selection.node)) return selection.from;
  return layoutContainerPosAt(state.doc, selection.from);
}

/* Whether the innermost table around the caret is a stack — a real table nested
   in a stack cell is still a table, and reports as one. */
function innermostTableIsStack(state: EditorState): boolean {
  const { $from } = state.selection;
  for (let d = $from.depth; d > 0; d -= 1) {
    if ($from.node(d).type.name === 'table') return isStackNode($from.node(d));
  }
  return false;
}

/* One click selects the container; once the selection is inside it, clicks fall
   through to the paragraph or photo under the pointer, so a column's text edits
   like any other text. `enteredBefore` is read at mousedown rather than here —
   see containerBeforeClick. Returns true when it consumed the click. */
/* The same job as selectContainerAt, resolved from the DOM instead of from a
   coordinate, for the one case the coordinate lookup cannot reach: a click on
   the container's own PADDING. posAtCoords maps a point with no inline content
   under it to the nearest position OUTSIDE the container, so
   layoutContainerPosAt finds nothing and the click falls through to the prose
   as though the padding were not part of the block. The banner carries 32px of
   it on all four sides, which is a lot of surface that looked dead — click the
   left edge and you got a text caret instead of the banner.

   Whatever element was actually under the pointer knows which container it
   belongs to, so ask it. Listed by selector rather than by walking node types
   because this runs before any position is resolved. */
function containerPosFromDom(view: EditorView, target: EventTarget | null): number {
  const el = target instanceof HTMLElement
    /* The Forms blocks are listed for the case this function exists to solve,
       and they are its worst instance: the answer space is NOT editable, so
       posAtCoords maps a click on the ruled lines to the nearest editable
       position outside the block, and the largest part of it was dead to the
       pointer. */
    ? target.closest('[data-jumbotron], .book-split-columns, .book-columns, [data-question], [data-choice]')
    : null;
  if (!el || !view.dom.contains(el)) return -1;
  const pos = view.posAtDOM(el, 0);
  if (pos < 0) return -1;
  const $at = view.state.doc.resolve(pos);
  for (let d = $at.depth; d > 0; d -= 1) if (isLayoutContainer($at.node(d))) return $at.before(d);
  return -1;
}

function selectContainerFromDom(view: EditorView, target: EventTarget | null, enteredBefore: number): boolean {
  const at = containerPosFromDom(view, target);
  if (at < 0 || at === enteredBefore) return false;
  view.focus();
  view.dispatch(view.state.tr.setSelection(NodeSelection.create(view.state.doc, at)));
  return true;
}

function selectContainerAt(view: EditorView, pos: number, enteredBefore: number): boolean {
  const target = layoutContainerPosAt(view.state.doc, pos);
  if (target < 0 || target === enteredBefore) return false;
  view.focus();
  view.dispatch(view.state.tr.setSelection(NodeSelection.create(view.state.doc, target)));
  return true;
}

const ACTIVE_CONTAINERS = new Set(['table', 'callout', 'blockquote']);
const activeBlockKey = new PluginKey('activeBlock');

const ActiveBlockRing = Extension.create({
  name: 'activeBlockRing',
  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: activeBlockKey,
        props: {
          decorations(state) {
            // A NodeSelection is the atom case, already ringed — a second box
            // around its container would read as two things being selected.
            if (state.selection instanceof NodeSelection) return DecorationSet.empty;
            const { $from } = state.selection;
            // Innermost ancestor first, so a table nested inside a columns block
            // rings as the table — the same precedence activeObjectKind uses.
            for (let d = $from.depth; d > 0; d--) {
              // A stack or columns block is drilled into, not entered as a
              // container: with the caret inside one, what's selected is the
              // paragraph in the column, so the paragraph is what gets marked.
              if (isLayoutContainer($from.node(d))) continue;
              if (ACTIVE_CONTAINERS.has($from.node(d).type.name)) {
                return DecorationSet.create(state.doc, [
                  Decoration.node($from.before(d), $from.after(d), { class: 'book-block-active' }),
                ]);
              }
            }
            /* Nothing below a container. This used to ring the paragraph the
               caret sat in (`book-text-active`), which made a ring mean two
               different things: "this object is selected" on an image or a
               table, and "you are typing here" on a paragraph. The second is
               the one no document editor draws — Word, Docs and Notion all let
               the caret speak for itself — and here it had already needed two
               exceptions, for a paragraph split across a page (its box is one
               rectangle spanning the gutter) and for one flowing beside a
               floated photo (its box claims width the text never occupies).

               The Forms blocks made the third and the clearest: a choice
               option's label is a `display: inline` paragraph, so the ring
               closed around a single character and read as a badge on the
               number, competing with the checkbox beside it.

               So the ring now means exactly one thing anywhere in the editor —
               an object is selected — matching the text fields, which stopped
               ringing on focus for the same reason. Where the caret is stays
               legible through the caret itself, plus the margin handle and the
               block menu that already track it. */
            return DecorationSet.empty;
          },
        },
      }),
    ];
  },
});

/* ── document model ───────────────────────────────────────────────────────── */
type LayoutId = 'standard' | 'opener' | 'image-led' | 'quote-pull' | 'two-column';

/* Per-chapter style overrides: the token/override mechanism. A chapter's heading
   colour and body font normally point at the active theme; the moment a user
   picks a value by hand in the Inspector, that single property freezes here and
   stops tracking the theme. Re-applying a theme only ever touches chapters (and
   properties) that aren't in this map. */
interface ChapterOverrides {
  headingColor?: string;
  bodyFont?: string;
}

/* The accent rule above a chapter opener's eyebrow. It's an object you can select
   and restyle, not template decoration — same vocabulary as the Divider block in
   the body flow, but it lives on the page rather than in the chapter's document,
   because it sits outside the editable prose. Unset properties track the theme
   (colour) and the opener's own proportions (56 x 4), so a book that never touches
   the rule still re-themes with everything else. */
const DEFAULT_EYEBROW_HTML = '<p>Chapter</p>';
interface OpenerRule { width: number; thickness: number; color: string }
const OPENER_RULE_SIZE = { width: 56, thickness: 4 };
function openerRuleOf(page: ChapterPage | undefined, theme: ThemeDef): OpenerRule {
  return { ...OPENER_RULE_SIZE, color: theme.accentColor, ...page?.openerRule };
}

interface ChapterPage {
  id: string;
  type: 'chapter';
  /* Per-page background fill. Falls back to the theme's own bg when unset, so a
     book that never touches this looks exactly as it did — but the colour stops
     being one book-wide value you can only change by swapping template. Themes
     were faking a coloured page by dropping a full-bleed rectangle SHAPE onto
     the cover, which is why clicking the background opened a shape inspector. */
  bg?: string;

  /* Plain-text mirror of titleHtml, kept in sync on every keystroke — this is what
     Preview's thumbnail rail, the Inspector breadcrumb and Design's "Layout · …"
     header read, since they want a string, not a field to render. */
  title: string;
  layout: LayoutId;
  overrides: ChapterOverrides;
  /* The chapter's title is its own field now (rendered via SimpleFieldEditor, same
     as Cover's title/subtitle/author) — a real, independently-selectable block, not
     just the first <h2> inside the body flow. initialHtml is body content only. */
  titleHtml: string;
  initialHtml: string;
  /* Old Designrr's TOC is a drop-in element built from whichever chapters are on the
     canvas — this is the one knob it exposes on top of that: a front-matter or
     backmatter-ish chapter (an Acknowledgements page, say) can opt out without being
     deleted or hidden. Defaults to included. */
  /* Only meaningful when layout === 'opener' — a photo that bleeds across the top of
     the page with the eyebrow/numeral/title overlaid on it, instead of the plain
     eyebrow-bar-above-title treatment. Optional: unset chapters render exactly as
     before. Picked/replaced via the same PhotoSourcePanel the cover and body images
     already use. */
  openerImage?: string;
  /* Per-chapter overrides for the opener's accent rule — see OpenerRule. Absent
     means "whatever the theme says", exactly like ChapterOverrides. */
  openerRule?: Partial<OpenerRule>;
}

/* ── book metadata — EPUB 3.2 requires identifier, title and language; the rest is
   what every retailer asks for on submission. None of this existed before. ────── */
interface BookMetadata {
  title: string;
  subtitle: string;
  author: string;
  identifier: string;
  language: string;
  publisher: string;
  description: string;
  subjects: string;
  /* Series + reading direction: both real EPUB/retailer fields (Amazon series
     metadata, and the dir attribute EPUB readers use for RTL scripts) that the old
     Designrr editor exposed and this one didn't. */
  seriesName: string;
  seriesPosition: string;
  readingDirection: 'ltr' | 'rtl';
}
const DEFAULT_METADATA: BookMetadata = {
  title: 'Focus: The Anti-Portfolio',
  subtitle: 'A book about doing less',
  author: 'Casper Weldings',
  identifier: '',
  language: 'en',
  publisher: '',
  description: '',
  subjects: '',
  seriesName: '',
  seriesPosition: '',
  readingDirection: 'ltr',
};
const REQUIRED_METADATA: (keyof BookMetadata)[] = ['title', 'identifier', 'language'];
/* What the warning calls each one — the field's own visible label, so the
   sentence names something you can go and find rather than a data key. */
const REQUIRED_METADATA_LABELS: Record<string, string> = {
  title: 'Title',
  identifier: 'Identifier',
  language: 'Language',
};
function missingMetadata(m: BookMetadata): (keyof BookMetadata)[] {
  return REQUIRED_METADATA.filter((k) => !m[k].trim());
}

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
}
function deriveSubheadings(html: string): string[] {
  const out: string[] = [];
  const re = /<h3[^>]*>([\s\S]*?)<\/h3>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    const text = m[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
    if (text) out.push(text);
  }
  return out;
}
/* ── cover elements — a freeform, positioned canvas, unlike everything else in this
   editor (chapters/TOC/backmatter are flowing, theme-driven text). x/y/w/h are percent
   of the cover stage (0-100), so the same element list renders correctly at any scale
   — full-size in the live editor, or shrunk via a plain CSS transform for a Preview
   device frame or a Templates-tab card thumbnail. ─────────────────────────────────── */
/* Who put this element on the cover. Absent means the template did — which is
   what every element in THEMES and every cover saved before this flag existed
   is, so no migration is needed. 'author' means the user added it by hand (a
   dropped photo, a duplicated element), and that is the whole difference that
   decides whether applying a template may delete it.

   The distinction exists because a cover is a free canvas, unlike the flowing
   theme-driven pages: a template owns the arrangement it shipped with, but it
   cannot own a shape the user drew on top of it. Squarespace, Shopify and
   WordPress all lose exactly the work that lives inside the theme's namespace,
   and the fix in all three is the same one taken here — move the user's work
   out of that namespace rather than warn about losing it. */
interface CoverElementBase { id: string; x: number; y: number; w: number; h: number; opacity?: number; locked?: boolean; origin?: 'author'; }
interface CoverTextElement extends CoverElementBase {
  type: 'text';
  // Content itself lives in fieldContent (see fieldKeyForCoverText below), not here —
  // singleton roles are keyed by role so a template swap can't orphan a user's real
  // typed title/subtitle/author text under an old element id.
  role: 'category' | 'title' | 'subtitle' | 'author' | 'custom';
  fontFamily: string; fontSize: number; color: string;
  fontWeight?: number; fontStyle?: 'italic'; textAlign?: 'left' | 'center' | 'right';
  letterSpacing?: string; textTransform?: 'uppercase';
  /* Unitless multiplier, percentage or px, exactly as typed — see
     parseTypeMetric. Absent means the browser's own default for the face, which
     is what every cover has had until now. */
  lineHeight?: string;
  /* Which TEXT_STYLES preset produced the five properties above, so the picker
     can show the current one instead of always rendering unselected. Cleared the
     moment any of those properties is set by hand — at that point the element no
     longer *is* the preset, and leaving the tile lit would claim otherwise. */
  stylePreset?: string | null;
  /* Every theme seeds a generous placeholder slot (h is a guess at "room for a
     couple of lines," not the actual rendered text), so the box shown while
     editing used to dwarf a short line by 30-40px of dead vertical space —
     visibly a different size than the text sitting inside it. Undefined/true
     means the box hugs the rendered line instead of the stored `h`, the same
     "auto until you touch it" relationship ChapterOverrides already uses for
     theme properties. The first manual resize (see beginResize) freezes it to
     false, so a deliberately taller box a user drags open stays open. */
  heightAuto?: boolean;
}
/* originalSrc/crop are the same pair the body image node carries: renderCrop
   bakes the cut into `src`, and these two are what let a crop be widened or
   undone afterwards rather than being a one-way destruction of the photo. */
/* The stroke four are the body image's, spelled the same and read by the same
   helpers: a framed photo is the commonest border in a book, and the cover was
   the one place you couldn't draw one. */
interface CoverImageElement extends CoverElementBase {
  type: 'image'; src: string; overlayDark?: boolean; originalSrc?: string; crop?: string;
  /* Spelled the same as the body image node's, because they are the same two
     ideas and an exporter should not have to learn two vocabularies for one
     concept. The cover is the strongest case for both: it is the first thing a
     screen reader meets, and the EU Accessibility Act has required alt text on
     meaningful images in ebooks sold in the EU since June 2025 — the published
     guidance names the cover explicitly, with "Book cover: <title> by <author>"
     as the pattern. Which is also why a cover is close to never decorative. */
  alt?: string; decorative?: boolean;
  /* How the photo sits in its box. 'cover' crops the overflow and is the default
     every cover photo has always had; 'contain' shows the whole picture and lets
     the page show through the gaps.

     Fill and Fit are a PAIR, and Crop is deliberately not a third option beside
     them: the first two are automatic rules that recompute whenever the box
     changes, the third is a window you place by hand once. Figma does list all
     three together, but only because its crop IS a fill mode internally — Word
     nests Fill and Fit *inside* Crop as presets, and InDesign keeps fitting as
     commands and repositioning as a gesture. Three products, three answers, so
     there is no "standard" to copy here; this follows the distinction that
     actually holds rather than any one of them. */
  fit?: 'cover' | 'contain';
  borderWidth?: number; borderColor?: string; borderSides?: string; borderPos?: string; borderStyle?: string;
}
interface CoverShapeElement extends CoverElementBase {
  type: 'shape'; shape: 'rectangle' | 'triangle' | 'circle' | 'rounded'; color: string;
  /* How far the triangle is turned, in degrees clockwise, 0 = right angle at the
     bottom right. Free, not the four fixed diagonals it replaces: those were a
     stand-in for rotation, and every one of them is still reachable here as a
     quarter turn (see CORNER_ROTATION). */
  rotation?: number;
  /* Legacy: which corner held the right angle, on covers saved before `rotation`
     existed. Read only as rotation's fallback, never written. */
  corner?: 'tl' | 'tr' | 'bl' | 'br';
  /* Fill was the only thing a cover shape had. These are the rest of what any
     design tool gives a rectangle — the same four properties the body image
     inspector already carries (radius / stroke / shadow), stored the same way, so
     the two panels describe an object with one vocabulary instead of two.
     'rounded' predates `radius`: it WAS "a rectangle with a corner radius", so it
     now reads as exactly that (see coverShapeRadius) rather than as a fourth
     silhouette sitting beside the shape it's a variant of. */
  radius?: number;
  borderWidth?: number;
  borderColor?: string;
  /* Which edges the stroke paints — 'all' or a comma list of t/r/b/l, the same
     token the body image carries, so one StrokeSidesField serves both panels.
     Absent on a triangle: its outline is an SVG polygon, and a polygon has no
     top or left to paint separately. */
  borderSides?: string;
  /* Where the stroke sits on the edge and how the line is drawn — the body
     image's own two, stored under the same names and read by the same helpers.
     A triangle takes the style (an SVG path dashes fine) but not the position:
     inside/outside a polygon would have to be clipped, not offset. */
  borderPos?: string;
  borderStyle?: string;
  // serializeShadow's string form, shared with the body image node so parseShadow
  // and the Effects fields are one implementation, not two.
  shadow?: string;
}
/* The legacy 'rounded' type's radius, in px — what ShapeFill used to hard-code as
   RADIUS_LG before the corner-radius field existed. */
const COVER_ROUNDED_PX = RADIUS_LG;
function coverShapeRadius(el: CoverShapeElement): number {
  return el.radius ?? (el.shape === 'rounded' ? COVER_ROUNDED_PX : 0);
}
/* Each legacy corner as the rotation that reproduces it exactly — the base
   triangle (right angle bottom-right) turned a quarter at a time. Because the
   turn happens in the SVG's own 100×100 viewBox, BEFORE the box stretches it,
   these four angles render a saved cover pixel-for-pixel as it was. */
const CORNER_ROTATION: Record<NonNullable<CoverShapeElement['corner']>, number> = { br: 0, bl: 90, tl: 180, tr: 270 };
function coverShapeRotation(el: CoverShapeElement): number {
  return el.rotation ?? CORNER_ROTATION[el.corner ?? 'br'];
}
/* The cover's QR is the same symbol the chapter block draws, positioned on a free
   canvas instead of flowing in text — so it shares realQrMatrix, the quiet zone and
   the contrast floor, and owns none of that itself. A cover QR is always the
   author's (`origin: 'author'`), never a template's: no theme ships one, and a
   template switch must not delete the address someone typed. */
interface CoverQrElement extends CoverElementBase {
  type: 'qr'; url: string; color: string;
}
type CoverElement = CoverTextElement | CoverImageElement | CoverShapeElement | CoverQrElement;

function coverElementLabel(page: SimplePage | undefined, elementId: string): string {
  const el = (page?.coverElements ?? []).find((e) => e.id === elementId);
  if (!el) return 'Cover element';
  if (el.type === 'text') return 'Text';
  if (el.type === 'image') return 'Photo';
  if (el.type === 'qr') return 'QR code';
  if (el.shape === 'circle') return 'Ellipse';
  if (el.shape === 'triangle') return 'Triangle';
  /* A rectangle covering the whole cover is the page's background, whatever the
     data model calls it — naming it "Rectangle" at the top of Properties
     described the primitive rather than the thing you clicked. Only full-bleed
     ones: a 40%-wide rule is also a rectangle, and calling that "Page" would be
     the same mistake in the other direction. */
  if (el.x === 0 && el.y === 0 && el.w === 100 && el.h === 100) return 'Page';
  // 'rounded' is a rectangle with a corner radius, and says so.
  return 'Rectangle';
}

function fieldKeyForCoverText(pageId: string, el: CoverTextElement): string {
  return el.role === 'custom' ? `${pageId}::el:${el.id}` : `${pageId}::${el.role}`;
}

interface SimplePage {
  id: string;
  type: 'cover' | 'toc' | 'backmatter';
  title: string;
  /* Per-page background fill. Falls back to the theme's own bg when unset, so a
     book that never touches this looks exactly as it did — but the colour stops
     being one book-wide value you can only change by swapping template. Themes
     were faking a coloured page by dropping a full-bleed rectangle SHAPE onto
     the cover, which is why clicking the background opened a shape inspector. */
  bg?: string;

  coverElements?: CoverElement[];
  /* backmatter only — one optional QR on the About-the-Author page, which is where
     a printed book conventionally puts "find me here". Not a CoverElement: that page
     is a fixed two-column layout, not a free canvas, so the code takes its place in
     the flow under the bio rather than being positioned. One per page, because a
     second one on an author page is a question nobody has asked. */
  backQr?: { url: string; color: string };
  /* backmatter only — a real author photo for the About-the-Author panel, picked
     the same way as openerImage/cover images. Unset falls back to the drawn
     circle+body silhouette. */
  authorPhoto?: string;
}
type PageMeta = ChapterPage | SimplePage;

/* ── Chapter start vs continuation ───────────────────────────────────────────
   A `type: 'chapter'` entry is a CONTAINER, not necessarily a chapter. It earns
   chapter-hood by having a heading, exactly the way Pandoc, Leanpub and every
   HTML→EPUB pipeline derive structure from headings rather than from files.

   An untitled container is a continuation page: body text that belongs to the
   chapter above it. It takes no table-of-contents entry, no chapter number and
   no opener chrome, and on export it folds back into that chapter's own file so
   the reader never sees a phantom break in the navigation. Typing a heading
   promotes it; clearing the heading demotes it again. That reversibility is the
   whole point — "add a page" and "start a chapter" stop being two decisions the
   user has to get right up front.

   The live title is the field, not `titleHtml`: the field is what the user is
   editing, and `titleHtml` is only its seed. Reading the seed alone would leave
   a page the user just emptied still counting as a chapter until reload. */
function chapterTitleText(p: PageMeta, fieldContent: Record<string, string>): string {
  if (p.type !== 'chapter') return '';
  return stripTags(fieldContent[`${p.id}::title`] ?? p.titleHtml).trim();
}
function isChapterStart(p: PageMeta, fieldContent: Record<string, string>): boolean {
  return chapterTitleText(p, fieldContent) !== '';
}
/** Chapters in reading order — continuation pages excluded. */
function chapterStarts(pages: PageMeta[], fieldContent: Record<string, string>): ChapterPage[] {
  return pages.filter((p): p is ChapterPage => isChapterStart(p, fieldContent));
}
/** 1-based number as printed on the opener. 0 for a continuation page. */
function chapterNumberOf(pages: PageMeta[], fieldContent: Record<string, string>, id: string): number {
  return chapterStarts(pages, fieldContent).findIndex((c) => c.id === id) + 1;
}
/* What a continuation page's boundary becomes once the book is a file. The
   canvas shows it as a new sheet, so the export says so too — inline rather
   than via a stylesheet class, because this has to survive whatever the
   packager does with CSS. Reflowable readers in scroll mode ignore it; that is
   the correct outcome, since there are no pages there to break. */
const CONTINUATION_BREAK_HTML = '<div style="break-before:page;page-break-before:always"></div>';

/** The chapter a page belongs to: itself if titled, else the nearest titled one above. */
function owningChapterId(pages: PageMeta[], fieldContent: Record<string, string>, id: string): string | null {
  const idx = pages.findIndex((p) => p.id === id);
  for (let i = idx; i >= 0; i--) if (isChapterStart(pages[i], fieldContent)) return pages[i].id;
  return null;
}

let coverElId = 0;
const nextCoverElId = () => `cel-${++coverElId}`;
/* The counter is module state, so it restarts at 0 on every page load while the
   book being restored still holds the ids a previous session handed out. Left
   alone, the next template applied would mint cel-1 again and collide with a
   restored cel-1 — harmless while a template swap replaced the whole element
   list, and a real duplicate-key bug now that authored elements survive one.
   Cover text keys off the element id too (see fieldKeyForCoverText), so a
   collision would cross-wire two boxes onto one piece of text. */
function reserveCoverElIds(pages: PageMeta[]): void {
  for (const p of pages) {
    for (const el of (p.type === 'cover' ? p.coverElements ?? [] : [])) {
      const n = /^cel-(\d+)$/.exec(el.id);
      if (n) coverElId = Math.max(coverElId, Number(n[1]));
    }
  }
}

/* Books saved before the cover had a real background: a full-bleed rectangle
   SHAPE sitting at the bottom of the element list, which is what made clicking a
   cover's background open a shape inspector. Without this, the fix only reaches
   covers created from here on — the book already on disk keeps the fake one, and
   keeps opening the wrong panel.

   Deliberately narrow: only a rectangle, only at 0,0 covering the whole page, and
   only the bottom-most one, so a deliberate full-bleed colour block layered OVER
   the artwork isn't quietly swallowed. */
function migrateCoverBg(p: SimplePage): SimplePage {
  if (p.type !== 'cover' || p.bg) return p;
  const els = p.coverElements ?? [];
  const first = els[0];
  if (!first || first.type !== 'shape' || first.shape !== 'rectangle') return p;
  if (first.x !== 0 || first.y !== 0 || first.w !== 100 || first.h !== 100) return p;
  return { ...p, bg: first.color, coverElements: els.slice(1) };
}

function cloneCoverElements(elements: CoverElement[]): CoverElement[] {
  return elements.map((el) => ({ ...el, id: nextCoverElId() }));
}

/* ── cover overrides — freeze on touch ────────────────────────────────────────
   A cover text slot's styling normally belongs to the template: pick a new one
   and the type is restyled to match the layout it was drawn for. The moment the
   author sets a property BY HAND, that single property stops tracking the
   template and travels with them instead. Untouched properties keep re-styling.

   This is not a new idea in this file — it is exactly the relationship
   ChapterOverrides has with the theme on the chapter side, and the cover was the
   half that lacked it. It is also how InDesign, Word and Visual Studio all model
   a style and a local override: the style is the base, the override is a layer,
   and a property is in one or the other, never half of both.

   SCOPE, and the two boundaries that matter:

   · Keyed by ROLE, not element id, and only the four singleton roles. Those are
     the slots every template has a counterpart for, which is what makes
     "carry it across" meaningful. A template's decorative shapes have no
     counterpart — Growth's stepped blocks are not Academic Clean's hairlines —
     so there is nothing to carry them onto. Author-added elements need none of
     this: they already survive whole (see mergeCoverElements).

   · Position and size are NOT here, deliberately. A colour is portable — red is
     red on any cover — but x/y/w/h are coordinates in the layout being
     replaced. Freeze those and the title stays exactly where the old template
     put it, which on the next template is usually on top of something.

   The override is only safe because it is visible: every frozen property is
   marked in the inspector with one click to release it (see OverrideDot and
   resetCoverSlot). Without that, a colour set once silently overrides every
   template tried afterwards, and the symptom — "this template looks broken" —
   points nowhere near the cause. */
type CoverSlotRole = 'category' | 'title' | 'subtitle' | 'author';
const COVER_SLOT_ROLES: CoverSlotRole[] = ['category', 'title', 'subtitle', 'author'];
/* Listed in the order they read down a cover, not alphabetically — the panel is
   describing a layout, so it should be walkable against the thing it describes. */
const COVER_SLOT_LABELS: Record<CoverSlotRole, string> = {
  category: 'Category', title: 'Title', subtitle: 'Subtitle', author: 'Author',
};
function isCoverSlotRole(r: CoverTextElement['role']): r is CoverSlotRole {
  return r !== 'custom';
}
/* Every styling property a cover text element has, and nothing else. Spelled as
   a list rather than "the element minus geometry" so that adding a new geometry
   field can't silently make it freezable. */
const COVER_STYLE_KEYS = [
  'fontFamily', 'fontSize', 'color', 'fontWeight', 'fontStyle', 'textAlign',
  'letterSpacing', 'textTransform', 'lineHeight', 'stylePreset',
] as const;
type CoverTextStyle = Partial<Pick<CoverTextElement, typeof COVER_STYLE_KEYS[number]>>;
/* What each frozen property is called when the inspector names it back to you.
   The words the controls themselves use, so "Colour" in the notice and "Colour"
   on the field are the same thing said twice, not two things. */
const COVER_STYLE_LABELS: Record<typeof COVER_STYLE_KEYS[number], string> = {
  fontFamily: 'Font', fontSize: 'Size', color: 'Colour', fontWeight: 'Weight',
  fontStyle: 'Italic', textAlign: 'Alignment', letterSpacing: 'Letter spacing',
  textTransform: 'Caps', lineHeight: 'Line height', stylePreset: 'Style',
};
interface CoverOverrides {
  text: Partial<Record<CoverSlotRole, CoverTextStyle>>;
  /* The cover's own background. Same rule, one property: unset means the
     template decides, set means the author picked it and it travels. */
  bg?: string;
  /* Slots the author deleted on purpose. A template that ships one is told not
     to put it back — "this book has no subtitle" is a fact about the book, so it
     outlives the layout that happened to offer the box. */
  removed?: CoverSlotRole[];
}
const EMPTY_COVER_OVERRIDES: CoverOverrides = { text: {} };

/** "Colour", "Colour and size", "Font, colour and size" — a plain English list. */
function listOf(items: string[]): string {
  if (items.length <= 1) return items[0] ?? '';
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/* The styling half of a patch, or null when the patch was pure geometry. Takes
   Partial<CoverTextElement> rather than CoverElementPatch so it reads a whole
   template element too — resetCoverSlot uses it to pull the values back out. */
function pickCoverStyle(patch: Partial<CoverTextElement>): CoverTextStyle | null {
  let found: CoverTextStyle | null = null;
  for (const k of COVER_STYLE_KEYS) {
    if (!(k in patch)) continue;
    (found ??= {})[k] = patch[k] as never;
  }
  return found;
}

/** Lays the author's frozen properties back over a template's own slots, and
    drops the slots they deleted on purpose. */
function applyCoverOverrides(els: CoverElement[], ov: CoverOverrides): CoverElement[] {
  const removed = ov.removed ?? [];
  if (!Object.keys(ov.text).length && !removed.length) return els;
  return els.flatMap((el) => {
    if (el.type !== 'text' || el.origin === 'author' || !isCoverSlotRole(el.role)) return [el];
    if (removed.includes(el.role)) return [];
    const frozen = ov.text[el.role];
    return [frozen ? { ...el, ...frozen } : el];
  });
}

/* Where a slot goes when the author adds one the template never drew. Derived
   from the title rather than fixed, so it lands inside whatever grid the
   template uses: same left edge, same width, stacked under it. Every one of the
   nine templates has a title, so there is always something to hang this on, and
   under the title is where all four of these sit on essentially every cover.
   It will not be as good as a slot the designer placed — but it is reachable,
   and the moment it is dragged that position becomes the author's own anyway. */
function derivedSlotBox(tpl: ThemeDef, role: CoverSlotRole): Pick<CoverElementBase, 'x' | 'y' | 'w' | 'h'> {
  const texts = tpl.coverElements.filter((e): e is CoverTextElement => e.type === 'text');
  const title = texts.find((e) => e.role === 'title');
  if (!title) return { x: 10, y: role === 'category' ? 12 : 70, w: 80, h: 6 };
  const H = 6;
  // Category is the one that belongs ABOVE the title — it is a kicker, and
  // putting it under would read as a second subtitle.
  if (role === 'category') {
    return { x: title.x, y: clampPct(title.y - 8, 0, 94), w: title.w, h: H };
  }
  /* Below-title roles have to dodge whatever the template already put there.
     Forgotten Memories is the case that forced this: its title runs to 83% and
     its author line starts at 84%, so a subtitle placed at "just under the
     title" landed on top of the author's name. Start at the preferred spot and
     step below anything it would overlap, so the derived slot lands in the gap
     the layout actually has rather than the gap it looked like it had. */
  let y = clampPct(title.y + title.h + (role === 'author' ? 12 : 3), 0, 100 - H);
  const others = texts.filter((e) => e.role !== role);
  for (let pass = 0; pass < others.length + 1; pass++) {
    const hit = others.find((e) => y < e.y + e.h && e.y < y + H);
    if (!hit) break;
    y = clampPct(hit.y + hit.h + 2, 0, 100 - H);
  }
  return { x: title.x, y, w: title.w, h: H };
}

/* One slot, built the way this template would have built it. The template's own
   element when it ships one; otherwise derived from its TITLE — position, font
   and above all colour, stepped down a size.

   Colour is the load-bearing inheritance. A derived box lands under the title,
   and the title is by construction legible against whatever it sits on, so
   anything taking its colour and sitting beneath it is legible too. That is what
   makes deriving safe on a dark cover or over a colour block, where a fixed
   default would be invisible. Size steps down because a subtitle at the title's
   own 56px would outshout the thing it sits under. */
function coverSlotElement(tpl: ThemeDef, role: CoverSlotRole, id: string): CoverTextElement {
  const fromTpl = tpl.coverElements.find((e): e is CoverTextElement => e.type === 'text' && e.role === role);
  if (fromTpl) return { ...fromTpl, id };
  const title = tpl.coverElements.find((e): e is CoverTextElement => e.type === 'text' && e.role === 'title');
  return {
    ...(title ?? { fontFamily: tpl.bodyFont, color: tpl.headingColor, textAlign: 'center' as const }),
    id,
    type: 'text',
    role,
    fontSize: role === 'subtitle' ? 15 : 12,
    fontWeight: undefined,
    stylePreset: null,
    heightAuto: true,
    ...derivedSlotBox(tpl, role),
  };
}

/* Text the author wrote that the incoming template has nowhere to put — placed,
   rather than dropped.

   This is the same call already made for the PHOTO one function below: a
   template with no image slot keeps the author's picture instead of destroying
   it, on the grounds that something you can see and move beats something that
   silently stopped existing. A sentence is not different from a photograph in
   that respect, and for a while this file treated it as if it were.

   Placing it also removes the need to announce it. There is nothing to warn
   about, no marker to notice and no panel to go and find — and because the
   template cards render through this same merge, the gallery now SHOWS you your
   subtitle sitting under the title before you pick the template at all.

   Deliberately not author-owned: these are re-derived on every switch, so the
   next template gets to place the slot its own way rather than inheriting a box
   shaped for the last one. And an author-owned copy would collide with the real
   slot the moment a template that HAS one came along — two boxes rendering the
   same role, which is one piece of text drawn twice. */
function autoPlaceCoverText(
  els: CoverElement[],
  tpl: ThemeDef,
  pageId: string,
  fieldContent: Record<string, string>,
): CoverElement[] {
  const extra = COVER_SLOT_ROLES
    .filter((role) => (
      !els.some((e) => e.type === 'text' && e.role === role)
      && !!stripTags(fieldContent[`${pageId}::${role}`] ?? '').trim()
    ))
    .map((role) => coverSlotElement(tpl, role, nextCoverElId()));
  return extra.length ? [...els, ...extra] : els;
}

/* Applying a template used to replace the cover wholesale, so a chosen photo
   went with it. A template IS a layout — and a look, coordinated font/colour
   choices that go with that specific arrangement — so both the arrangement
   and the styling get replaced. Only the author's actual content survives:

   · Photo — always carries onto the new layout's image slot. It's the
     author's content, not the template's; its treatment (overlay, etc.)
     comes from the new template, matching whatever look it was designed for.
   · Text — the words already survive, because they live in fieldContent
     keyed by role rather than by element id (see fieldKeyForCoverText). Font,
     colour, size and alignment come from the new template UNLESS the author
     set that one property by hand, in which case it is frozen and travels —
     see CoverOverrides. A blanket "keep the old template's type choices"
     toggle used to live here and was rightly removed: it kept styling from a
     layout the type was never designed for. Freezing only the properties
     actually touched is the opposite trade, and it is the relationship
     ChapterOverrides has always had with the theme on the chapter side.
   · Position and size — never carry, for TEMPLATE-OWNED elements. They're
     coordinates in the layout being replaced; keeping them is what produces a
     title floating in dead space.

   · Anything the author added themselves — a dropped photo, a duplicated
     element, a second text box — carries across WHOLE, position and styling
     included, and lands on top of the new layout. The reasoning is the mirror
     image of the line above: a sticker placed at 70/20 is a decision about
     this cover, not a coordinate in a layout that no longer exists, so there
     is nothing for the new template to have an opinion about. This used to be
     dropped on the floor, which made picking a template a silent way to delete
     your own work. */
function mergeCoverElements(current: CoverElement[], incoming: CoverElement[], outgoing: CoverElement[]): CoverElement[] {
  const authored = current.filter((el) => el.origin === 'author');
  /* The photo of record, and only if the AUTHOR chose it: an image still
     carrying the outgoing template's own stock src is that template's artwork,
     not a picture anyone picked, and carrying it forward would spread one
     theme's stock photo across every other theme you try. */
  const stockSrcs = new Set(outgoing.filter((el) => el.type === 'image').map((el) => (el as CoverImageElement).src));
  const chosenPhoto = current.find((el): el is CoverImageElement => (
    // `el.src &&` is the empty-frame guard: an emptied frame has no picture to
    // carry, and without this it would carry its emptiness onto the next
    // template and blank that template's own photo too.
    el.type === 'image' && !!el.src && el.origin !== 'author' && !stockSrcs.has(el.src)
  ));
  const slots = cloneCoverElements(incoming).map((el) => {
    /* originalSrc/crop travel with src, not just src: src is the already-baked
       cut, so carrying it alone would hand the new cover a photo whose crop can
       never be widened or undone. */
    if (el.type === 'image' && chosenPhoto) {
      return { ...el, src: chosenPhoto.src, originalSrc: chosenPhoto.originalSrc, crop: chosenPhoto.crop };
    }
    return el;
  });
  /* A template with no image slot at all (Growth) used to destroy the author's
     photo outright — the one case where switching template deleted content
     that could not be typed back. It survives as an authored element instead:
     it keeps its old box, so it may well sit oddly on the new layout, but a
     photo you can see and move beats a photo that silently stopped existing. */
  const orphanPhoto = chosenPhoto && !slots.some((el) => el.type === 'image')
    ? [{ ...chosenPhoto, origin: 'author' as const }]
    : [];
  // Authored elements last = drawn in front (see reorderCoverElement, where
  // 'front' pushes to the end), which is where something added on top belongs.
  return [...slots, ...orphanPhoto, ...authored];
}

/* ── templates — one bundled thing, not two: a template is a cover layout AND the
   chapter/TOC/back-matter color+font that goes with it, applied together. Cover
   layout and chapter theming used to be two separate systems (a cover-only gallery,
   and this array as a chapter-color-only "Theme" swap) — they're merged here so
   picking a template actually changes the whole book, not just one page. */
type ThemeId = 'statement-lettering' | 'academic-clean' | 'vintage-literary' | 'gradient-tech' | 'pastel-wellness' | 'forgotten-memories' | 'hand-illustrated' | 'collage-maximalist' | 'growth';
interface ThemeDef {
  id: ThemeId;
  name: string;
  /* Which layout a NEW chapter opens with. The template has always decided what
     a chapter looks like — it just had no way to say so, so every chapter the
     user added came out 'standard' while the seeded ones carried real designs.
     Vellum's Styles answer exactly this question, and answer it once for the
     whole book rather than per chapter. Optional: unset means 'opener', the
     designed treatment, so a theme only speaks up when it wants something else.
     The per-chapter Layout control still overrides this for a single chapter. */
  chapterLayout?: LayoutId;
  headingFont: string;
  bodyFont: string;
  headingColor: string;
  accentColor: string;
  bg: string;
  /* Body/paragraph ink — separate from headingColor so a dark-page theme (Dark
     Thriller) can carry a softer off-white for running text while the heading
     stays crisp, instead of both reusing one color built for a white page. */
  bodyColor: string;
  /* The cover's own page fill, when it differs from the book's. Dark Thriller's
     near-black cover used to be a full-bleed rectangle SHAPE sitting at the
     bottom of coverElements — which is why clicking the cover's background
     opened a shape inspector offering to turn the page's background into a
     circle. It's a page property, so it's stored as one (SimplePage.bg) and set
     from here when the template is applied. Unset means "the book's own bg". */
  coverBg?: string;
  requiredPlan?: GateTier;
  coverElements: CoverElement[];
}
/* Full replacement set (2026-09-15) — the original 7 stock-photo/color-block themes
   are gone, not just supplemented. Two things drove the swap: (1) a photo-based cover
   (Vintage Literary v1) got rejected outright because none of the 7 stock photos in
   this library read as book-cover subject matter — see the comment on Vintage
   Literary below; (2) real cover-design guidance (KDPeasy, Matsuo) says a cover
   should bleed color/imagery to its true edge, since most shelves/carousels sit on a
   white page and a pale-edged cover disappears into it — so every theme here is
   typographic/graphic (shapes + type), no stock photos, and deliberately mostly
   white/off-white (6 of 8) so that's the default read, not the exception, matching
   what 2026 nonfiction/business cover trends (Damonza, Troubador) actually show:
   one font, one accent color, generous white space, title doing the heavy lifting.
   The two exceptions are deliberate, not missed quota — Dark Thriller stays dark
   because "dark/moody" is the genre's own convention, not a style preference. */
/* A photo is still worth having in a handful of these — 3 of 8 (Academic Clean,
   Gradient Tech, Collage Maximalist) — just never as a full-bleed background behind
   text again. Each uses a photo as one CONTAINED element (a top band, a corner card,
   a collage fragment) sized well under 100% of the cover, so the white ground still
   reads as dominant and the photo never needs a dark tint to keep text legible. */
/** The layout a new chapter takes from the active theme. */
function chapterLayoutOf(theme: ThemeDef): LayoutId { return theme.chapterLayout ?? 'opener'; }

